window.KG_CALC = [{"set": 1, "date": "2026-09-28", "session": "day", "title": "资料分析速算训练 · 第 1 批（估算 / 直除 / 增长率 / 比重）", "difficulty": "基础+中等", "items": [{"type": "pure", "level": "基础", "stem": "计算 4823 ÷ 617，结果最接近下列哪一项？", "options": ["5.8", "6.8", "7.8", "8.8"], "answer": ["C"], "method": "直除定首位：617×7＝4319，4823－4319＝504，余数 504 小于 617 且接近 617 的 0.8 倍 → 商约 7.8。\n速算口诀：除数三/四位数，先算首商，再看余数占除数的比例。", "explain": "617×7＝4319；617×8＝4936 已经超过 4823。所以商在 7～8 之间，且 4823－4319＝504，504÷617≈0.82，故约 7.8，选 C。", "tip": "别用笔硬除到小数点后两位：资料分析只要选到“最接近”的选项，首商＋余数比例就够了。", "hard": "余数与除数的比例是判断小数的关键，别忘了这一步，否则容易在 7.8 和 6.8 之间犹豫。"}, {"type": "pure", "level": "基础", "stem": "计算 2023.4 ÷ 3.87，结果最接近下列哪一项？", "options": ["403", "523", "691", "829"], "answer": ["B"], "method": "把除数看成 3.9：2023.4÷3.9≈518.8；也可以直接验证 3.87×523＝2024.0，与 2023.4 几乎相等。", "explain": "3.87≈3.9，2023.4÷3.9≈519；再用 3.87×523＝2024.0 验证，误差仅 0.6，所以答案是 523（B）。", "tip": "除数四舍五入后要反向验证一次（乘回去），避免估算误差把答案推到相邻选项。", "hard": "3.87 与 3.9 的差异约为 0.8%，在大数值上会放大到 15 左右，正好决定 B 还是 C。"}, {"type": "pure", "level": "基础", "stem": "某指标由 428 增长到 561，增长率最接近下列哪一项？", "options": ["26%", "31%", "36%", "41%"], "answer": ["B"], "method": "增长率＝(现期－基期)÷基期＝(561－428)÷428＝133÷428。\n速算：428×30%＝128.4，略小于 133，所以略高于 30% → 约 31%。", "explain": "133÷428：先算 1/4＝25%（107），再补 26（约 6%），合计约 31%，选 B。", "tip": "增长率的分母一定是基期（428），不是现期。分母搞反是最高频的低级错误。", "hard": "选项间隔只有 5 个百分点，必须用“先取整百分数、再补差”的方式逼近，不能只看大概。"}, {"type": "pure", "level": "基础", "stem": "部分值 1586，整体值 4820，部分占整体的比重最接近下列哪一项？", "options": ["33%", "28%", "43%", "38%"], "answer": ["A"], "method": "整体×1/3＝4820÷3≈1606.7，比 1586 略大 → 比重应略小于 1/3（33.3%）→ 约 33%。", "explain": "4820×0.33＝1590.6，与 1586 只差 4.6，说明比重几乎正好是 33%，选 A。", "tip": "比重的常用基准：1/3≈33.3%、1/4＝25%、2/5＝40%、3/4＝75%。先找最近基准再微调，比硬除快得多。", "hard": "选项 28% 与 33% 的差距看似明显，但如果用“1586/4820≈0.29”的粗估（把 4820 当 5500）就会选错。"}, {"type": "pure", "level": "基础", "stem": "计算 25.6% ＋ 18.9% － 9.4%，结果最接近下列哪一项？", "options": ["16.4%", "25.1%", "45.1%", "35.1%"], "answer": ["D"], "method": "整数部分先加：25＋18－9＝34；小数部分：0.6＋0.9－0.4＝1.1；合计 35.1%。", "explain": "25.6%＋18.9%＝44.5%，44.5%－9.4%＝35.1%，选 D。", "tip": "百分数的加减可以直接当小数运算，但要小心借位：44.5－9.4 容易错算成 34.1 或 35.9。", "hard": "多步加减要先合并同号的项（这里先加后减），减少一次心算，出错率明显下降。"}, {"type": "pure", "level": "基础", "stem": "计算 3842 ÷ 612，结果最接近下列哪一项？", "options": ["4.3", "5.3", "6.3", "7.3"], "answer": ["C"], "method": "612×6＝3672，3842－3672＝170；170÷612≈0.28 → 商约 6.3。", "explain": "612×6＝3672，612×7＝4284 已超过 3842，所以商在 6～7 之间，约为 6.3，选 C。", "tip": "除数接近 600 时，可用“6 倍”作锚点；余数不到除数的三分之一，商的小数部分就小于 0.35。", "hard": "若把 612 粗看成 600 直接算 3842/600＝6.4，会倾向选 C 也正确，但如果选项里有 6.4 就容易被带偏——估算后要用乘法回验。"}, {"type": "pure", "level": "进阶", "stem": "某数据连续两年分别增长 12% 和 9%，两年累计增长率最接近下列哪一项？", "options": ["22.1%", "20.1%", "23.1%", "26.1%"], "answer": ["A"], "method": "两年累计＝(1＋12%)×(1＋9%)－1＝12%＋9%＋12%×9%＝21%＋1.08%≈22.1%。", "explain": "12%＋9%＝21%，再加上两者的乘积 1.08%，合计约 22.1%，选 A。", "tip": "不能简单相加：相加是 21%，漏掉了交叉项 1.08%，差别正好落在选项之间。", "hard": "这是最常见的“间隔增长率”陷阱，乘积项看似很小，但选项设计得只差一个百分点左右。"}, {"type": "pure", "level": "进阶", "stem": "下列四个分数中，数值最大的是？", "options": ["3/7", "4/9", "5/11", "6/13"], "answer": ["D"], "method": "四个分数都是“分子＋2、分母＋2”的形式（n/(2n－1)）：分子分母同时加同一个正数时，分数趋近 1/2，且原值越小、增幅越大？\n正确思路：写成 1/2 的形式看差距 —— 3/7＝1/2－1/14，4/9＝1/2－1/18，5/11＝1/2－1/22，6/13＝1/2－1/26，差越小值越大 → 6/13 最大。", "explain": "3/7≈0.429，4/9≈0.444，5/11≈0.455，6/13≈0.462，最大的是 6/13，选 D。", "tip": "不要一上来就通分。凡是分子分母差相同的分数，用“与 1/2 的差距”比较最快。", "hard": "这类题的规律是：分子越大越接近 1/2，容易误以为“小分数更小但更保险”而选反。"}, {"type": "pure", "level": "基础", "stem": "57.1% 最接近下列哪个分数？", "options": ["3/5", "4/7", "5/9", "7/12"], "answer": ["B"], "method": "记住常用换算：1/7≈14.3%、2/7≈28.6%、3/7≈42.9%、4/7≈57.1%。", "explain": "4/7＝0.5714→57.1%，故选 B。其余：3/5＝60%，5/9≈55.6%，7/12≈58.3%。", "tip": "资料分析里 1/7 到 6/7 的百分数是必背表，考到比重、增速换算时能省大量时间。", "hard": "7/12≈58.3% 与 57.1% 只差 1.2 个百分点，不背表很容易误选。"}, {"type": "pure", "level": "基础", "stem": "计算 1374 × 1.38，结果最接近下列哪一项？", "options": ["1450", "1690", "1890", "2100"], "answer": ["C"], "method": "1374×1.38＝1374＋1374×0.38；1374×0.38＝1374×(0.4－0.02)＝549.6－27.5≈522 → 合计 1896。", "explain": "1374×1.38≈1896，最接近 1890，选 C。", "tip": "乘 1.x 时拆成“原数＋增量”比整体乘更快；0.38 拆成 0.4－0.02 可避免进位错。", "hard": "增量部分 522 和选项差距有关：若把 0.38 当 0.4 算，会得到 1924，接近 1890 与 2100 中间，容易犹豫。"}, {"type": "pure", "level": "基础", "stem": "五个数据 38、42、51、47、62 的平均数是多少？", "options": ["44", "46", "47", "48"], "answer": ["D"], "method": "取基准 50：偏差为 －12、－8、＋1、－3、＋12，合计 －10；平均值＝50＋(－10÷5)＝50－2＝48。", "explain": "总和 38＋42＋51＋47＋62＝240，240÷5＝48，选 D。", "tip": "平均数题用“基准＋偏差”法最快，尤其数据都围绕某个整数时；直接竖加容易出错。", "hard": "差值总和是 －10，别忘记要除以个数 5，再回到基准上，最后一步方向容易搞反。"}, {"type": "pure", "level": "基础", "stem": "计算 9832 － 4177，结果最接近下列哪一项？", "options": ["5655", "5505", "5805", "6005"], "answer": ["A"], "method": "先整算：9800－4200＝5600，再补零头：＋32＋23＝55 → 5655。", "explain": "9832－4177＝5655，选 A。", "tip": "减法用“凑整后再加回零头”，比逐位借位稳，也不容易在借位上丢 1。", "hard": "零头是“＋32＋23”而不是“－32＋23”，方向看错就会得到 5591 之类的结果。"}, {"type": "applied", "level": "基础", "stem": "问：该市 2023 年地区生产总值同比增长约多少？", "data": "【材料】某市地区生产总值：\n2022 年 12480 亿元；2023 年 13602 亿元。", "options": ["7.0%", "8.0%", "9.0%", "10.0%"], "answer": ["C"], "method": "增长率＝(现期－基期)÷基期＝(13602－12480)÷12480＝1122÷12480。\n速算：12480×9%＝1123.2，与 1122 几乎相等 → 正好约 9%。", "explain": "增量 1122 亿元，1122÷12480≈8.99%，故选 9.0%（C）。", "tip": "基期一定是 12480（去年），不是 13602。反向用“现期×增速”验证：12480×9%＝1123≈1122。", "hard": "选项间距只有 1 个百分点，必须做一次乘法验证，光靠“约 9%”的直觉很容易选成 8%。"}, {"type": "applied", "level": "基础", "stem": "问：2023 年该县税收收入占财政收入的比重约为多少？", "data": "【材料】2023 年某县财政收入 86.4 亿元，其中税收收入 65.7 亿元。", "options": ["71%", "76%", "81%", "86%"], "answer": ["B"], "method": "先找基准：86.4×3/4＝64.8，略小于 65.7 → 比重比 75% 稍高，约 76%。", "explain": "65.7÷86.4≈0.7604→76%，选 B。", "tip": "用 3/4 作锚点最省事；若用 4/5＝80% 去比，会误判成 81%。", "hard": "余数法验证：86.4×76%＝65.7，正好对上，说明答案误差在 0.1 个百分点内。"}, {"type": "applied", "level": "进阶", "stem": "问：2019—2023 年，该市快递业务量年均增长量约为多少？", "data": "【材料】2019 年某市快递业务量 12.5 亿件；2023 年 24.6 亿件。", "options": ["3.0 亿件", "2.4 亿件", "3.6 亿件", "4.2 亿件"], "answer": ["A"], "method": "年均增长量＝(末期值－初期值)÷间隔年数＝(24.6－12.5)÷(2023－2019)＝12.1÷4≈3.03。", "explain": "总增量 12.1 亿件，间隔 4 年，12.1÷4≈3.0 亿件，选 A。", "tip": "间隔年数是 4 不是 5（2023－2019）！这是“年均增长量”最高频的坑。", "hard": "如果误用“年数＝5”会得到 2.4 亿件，正好是干扰项 B，出题人就是冲这个来的。"}, {"type": "applied", "level": "进阶", "stem": "问：2021—2023 年该园区产值的年均增长率约为多少？", "data": "【材料】某园区产值：2021 年 25 亿元；2023 年 36 亿元。", "options": ["12%", "15%", "20%", "25%"], "answer": ["C"], "method": "两年年均增长率 r 满足 (1＋r)²＝末期÷初期＝36÷25＝1.44。\n常用平方数：1.2²＝1.44 → r＝20%。", "explain": "36÷25＝1.44，开平方得 1.2，即年均增长 20%，选 C。", "tip": "两年年均增长率用开平方（1.44 的开方是 1.2，一定要背 1.1²=1.21、1.2²=1.44、1.3²=1.69）。", "hard": "别把“总增长率 44%”直接除以 2 得 22%（无此选项），也不能选 25%（那是把 44% 当单年）。"}, {"type": "applied", "level": "进阶", "stem": "问：2023 年该市第三产业增加值占 GDP 的比重与上年相比约：", "data": "【材料】2023 年某市第三产业增加值 8320 亿元，同比增长 6.2%；全市地区生产总值 15600 亿元，同比增长 4.8%。", "options": ["下降 0.7 个百分点", "上升 0.7 个百分点", "上升 2.1 个百分点", "下降 2.1 个百分点"], "answer": ["B"], "method": "① 现期比重：8320÷15600≈53.3%。\n② 基期比重：(8320÷1.062)÷(15600÷1.048)＝7834÷14885≈52.6%。\n③ 两者相减：53.3%－52.6%＝＋0.7 个百分点。\n口诀：部分增速(6.2%)＞整体增速(4.8%) → 比重上升。", "explain": "部分增速高于整体增速，比重必然上升；用两期比重差公式验证：比重差≈现期比重×(部分增速－整体增速)÷(1＋部分增速)≈53.3%×1.4%÷1.062≈0.70 个百分点，选 B。", "tip": "先判方向（部分增速＞整体增速 → 上升），只在“上升”的选项里挑，能直接排除一半选项。", "hard": "两期比重差的公式里分母是 (1＋部分增速)，不是 (1＋整体增速)；用错方向或数量级会得到 2.1 那个干扰值。"}, {"type": "applied", "level": "进阶", "stem": "问：2023 年该市研发投入总额约为多少？", "data": "【材料】2023 年某市高新技术企业研发投入 246 亿元，占全市研发投入总额的 61.5%。", "options": ["340 亿元", "360 亿元", "380 亿元", "400 亿元"], "answer": ["D"], "method": "整体＝部分÷比重＝246÷61.5%。\n速算：61.5%≈5/8 → 246×8÷5＝393.6≈400 亿元。", "explain": "246÷0.615＝400（亿元），选 D。", "tip": "“已知部分求整体”要用除法；把 61.5% 看成 5/8 后计算量骤减。", "hard": "常见错法：246×61.5%≈151（乘错了）。看到“占……的 X%”先想清楚是求整体还是求部分。"}, {"type": "applied", "level": "基础", "stem": "问：2023 年 A 省粮食产量约是 B 省的多少倍？", "data": "【材料】2023 年 A 省粮食产量 4250 万吨，B 省 1062.5 万吨。", "options": ["2 倍", "3 倍", "4 倍", "5 倍"], "answer": ["C"], "method": "验证法：1062.5×4＝4250，正好相等 → 4 倍。", "explain": "4250÷1062.5＝4，选 C。", "tip": "倍数题用“乘回去”验证最快：拿干扰选项各乘一次，谁正好等于分子就是答案。", "hard": "选项都是整数倍，说明出题人想让你用“凑数法”而不是硬除，别浪费时间去算小数部分。"}, {"type": "applied", "level": "进阶", "stem": "问：2022 年全国实物商品网上零售额约为多少？", "data": "【材料】2023 年全国实物商品网上零售额 13.0 万亿元，同比增长 8.4%。", "options": ["11.0 万亿元", "12.0 万亿元", "13.0 万亿元", "14.0 万亿元"], "answer": ["B"], "method": "求基期：基期＝现期÷(1＋增长率)＝13.0÷1.084≈12.0。\n速算：1.084≈1.1 → 13.0÷1.1≈11.8，说明答案在 12 附近（用 1.084 精算刚好 12.0）。", "explain": "13.0÷1.084＝11.99≈12.0 万亿元，选 B。", "tip": "求基期是除法，求增长量是乘法——13.0×8.4% 得到的是增量，不是基期。", "hard": "简算时把 1.084 当 1.1 会低估基期（得 11.8），正好滑向干扰项 11.0 一侧，需要用“略小于 1.1”修正回 12.0。"}]}, {"set": 2, "date": "2026-09-29", "session": "day", "title": "资料分析速算训练 · 第 2 批（直除估算 / 增长率 / 间隔增长 / 年均增长 / 两期比重）", "difficulty": "基础+中等", "items": [{"type": "pure", "level": "基础", "stem": "3417 ÷ 47.3 的结果最接近（　）", "data": "", "options": ["68.5", "72.2", "76.4", "80.1"], "answer": ["B"], "method": "首数法（直除）：\n① 先看首数：47.3×7=331.1，3417 里能放 7 个 47.3；\n② 再补一位：47.3×72=3405.6，余 11.4；\n③ 个位再补：11.4÷47.3≈0.24，合计约 72.2。", "explain": "47.3×72=3405.6，3417-3405.6=11.4，11.4÷47.3≈0.24，所以 3417÷47.3≈72.2，选 B。", "tip": "不要一上来就精确长除。先定“首位商 7”，把选项按首位筛掉 68.5 以下；再用尾数定 72.2。", "hard": "选项 68.5 与 72.2 相差不到 5%，若只估到“70 左右”就会左右摇摆，必须算到小数点后一位。"}, {"type": "pure", "level": "基础", "stem": "1234.5 × 12.5% 约等于（　）", "data": "", "options": ["148.1", "154.3", "162.5", "171.2"], "answer": ["B"], "method": "化分数（最省力的一招）：\n① 12.5% = 1/8；\n② 1234.5 ÷ 8 = 154.3。", "explain": "12.5% 化为 1/8，1234.5÷8=154.3125≈154.3，选 B。", "tip": "记住常用化分数：12.5%=1/8、25%=1/4、37.5%=3/8、62.5%=5/8、16.7%≈1/6、14.3%≈1/7。", "hard": "选项 148.1 是把 12% 当成 12.5% 算出的结果（1234.5×0.12=148.1），速度一快就容易掉进去。"}, {"type": "pure", "level": "基础", "stem": "把 6/7 化为百分数（保留一位小数），约为（　）", "data": "", "options": ["78.6%", "82.4%", "85.7%", "88.9%"], "answer": ["C"], "method": "化分数直记：\n① 1/7≈14.3%，6/7＝1-1/7；\n② 1-14.3%＝85.7%。", "explain": "1/7≈14.3%，故 6/7≈85.7%，选 C。也可直除 6÷7=0.857。", "tip": "先记 1/7≈14.3%，再推 2/7≈28.6%、3/7≈42.9%、5/7≈71.4%，比现算快得多。", "hard": "选项 82.4% 是 1/7×… 记反（把 5/7=71.4% 记成 14.3% 再乘错）时出现的结果，务必用 1-1/7 反推核对。"}, {"type": "pure", "level": "基础", "stem": "今年某指标为 1680，去年为 1400，则同比增长（　）", "data": "", "options": ["16.7%", "20.0%", "22.4%", "25.0%"], "answer": ["B"], "method": "增长率＝（今-去）÷去：\n① 增量 1680-1400=280；\n② 280÷1400=0.2=20%。", "explain": "(1680-1400)÷1400=280÷1400=20.0%，选 B。", "tip": "分母必须是“去年的量”（基期）。用今年的量做分母就掉进干扰项。", "hard": "干扰项 16.7% 就是把分母换成今年算的：280÷1680=16.7%。"}, {"type": "pure", "level": "进阶", "stem": "今年某指标为 2460，同比增长 15%，则同比增长量约为（　）", "data": "", "options": ["276", "321", "369", "398"], "answer": ["B"], "method": "已知“现期+增长率”求增长量：\n① 先求基期：2460÷1.15≈2139；\n② 增长量＝2460-2139≈321。\n（速算式：增长量＝现期×r/(1+r)＝2460×0.15/1.15）", "explain": "基期＝2460÷1.15≈2139.1，增长量＝2460-2139.1≈320.9≈321，选 B。", "tip": "绝不能直接 2460×15%=369！那个数是以“基期”为底的，本题给的是现期。", "hard": "干扰项 369 就是“现期×增长率”的错算，也是最常见的失分点。"}, {"type": "pure", "level": "进阶", "stem": "2026 年比 2024 年增长多少？已知 2025 年同比增长 20%，2026 年同比增长 25%。", "data": "", "options": ["45.0%", "47.5%", "50.0%", "55.0%"], "answer": ["C"], "method": "间隔增长率：\n① 公式 r＝r1+r2+r1×r2；\n② 20%+25%+20%×25%=45%+5%＝50%。", "explain": "1.2×1.25=1.50，即增长 50%，选 C。", "tip": "千万别把两个增长率直接相加得 45%（漏掉乘积项 5%）。", "hard": "干扰项 45% 就是漏乘 r1×r2 的结果；间隔越久、数值越大，漏乘误差越明显。"}, {"type": "pure", "level": "基础", "stem": "2019 年某产量为 1200，2024 年为 2400，则这期间年均增长量约为（　）", "data": "", "options": ["200", "240", "300", "400"], "answer": ["B"], "method": "年均增长量＝（末期-初期）÷（年份差）：\n① 年份差＝2024-2019=5；\n② (2400-1200)÷5=240。", "explain": "(2400-1200)÷5=240，选 B。", "tip": "年份差是 5 不是 6（2019→2024 跨 5 年）。这个“差一年”的坑每年都有人踩。", "hard": "干扰项 200 是用 6 年算的（1200÷6=200），务必数清“间隔年数”。"}, {"type": "pure", "level": "进阶", "stem": "某量从 1000 增长到 1600，历时 4 年，则年均增长率约为（　）", "data": "", "options": ["9.8%", "12.5%", "15.0%", "18.6%"], "answer": ["B"], "method": "年均增长率（开平方思路）：\n① 倍数关系：(1+r)^4=1.6；\n② 两边开两次平方：1.6^0.5≈1.265，再开平方≈1.125；\n③ r≈12.5%。", "explain": "1.6^(1/4)≈1.125，故年均增长率≈12.5%，选 B。", "tip": "绝不能把总增长率 60% 除以 4 得 15%！年均增长率是“几何平均”，一定小于算术平均。", "hard": "干扰项 15.0% 就是 60%÷4 的错算；真正的结果必然更小，可据此排除。"}, {"type": "pure", "level": "进阶", "stem": "总体今年为 5000（同比+10%），其中某部分今年为 1200（同比+20%），则该部分占比比去年（　）", "data": "", "options": ["提高约 1.0 个百分点", "提高约 2.0 个百分点", "下降约 2.0 个百分点", "基本持平"], "answer": ["B"], "method": "两期比重差：\n① 今年占比＝1200÷5000=24%；\n② 去年占比＝(1200÷1.2)÷(5000÷1.1)=1000÷4545.5≈22%；\n③ 差＝24%-22%＝+2 个百分点。", "explain": "部分增速(20%)>总体增速(10%)，占比必然上升；具体由 22% 升至 24%，提高约 2.0 个百分点，选 B。", "tip": "先判方向再算数值：部分增速快于总体，占比就上升，可先排除“下降”。", "hard": "干扰项 1.0 是只算“增量比”的粗估；要注意两期比重差＝今占比-去占比，不能只用增速差相减。"}, {"type": "pure", "level": "基础", "stem": "12345 是 2058 的多少倍（保留一位小数）？", "data": "", "options": ["5.0 倍", "5.6 倍", "6.0 倍", "6.5 倍"], "answer": ["C"], "method": "倍数＝A÷B：\n① 2058×6=12348；\n② 12345 略小于 12348，故≈6.0。", "explain": "12345÷2058≈5.999≈6.0 倍，选 C。", "tip": "倍数问题先试整数倍：×6 正好贴近，一步定位。", "hard": "选项 5.6 是“差值÷分母”之类错算的口径；记住倍数＝除法，不是减法比较。"}, {"type": "pure", "level": "基础", "stem": "已知 5 个数的平均数为 42.6，其中 4 个是 38、45、41、44，则第 5 个数是（　）", "data": "", "options": ["43", "44", "45", "46"], "answer": ["C"], "method": "用总量倒推：\n① 总数＝42.6×5=213；\n② 前四个之和＝38+45+41+44=168；\n③ 第 5 个＝213-168=45。", "explain": "42.6×5=213，213-168=45，选 C。", "tip": "平均数的题一律“先求总量、再做减法”，比逐个凑数稳。", "hard": "本题干扰项 43/44/46 都紧贴答案，必须精确算总量，不能靠目测平均。"}, {"type": "pure", "level": "进阶", "stem": "某数先上涨 20%，再下跌 10%，则最终比原数（　）", "data": "", "options": ["上涨 8%", "上涨 10%", "上涨 12%", "上涨 30%"], "answer": ["A"], "method": "连续变化用乘法：\n① 1×1.2×0.9=1.08；\n② 比原数上涨 8%。", "explain": "1.2×0.9=1.08，即上涨 8%，选 A。", "tip": "涨跌不能直接相减（20%-10%≠10%）：先涨后跌的“底数”变了。", "hard": "干扰项 10% 就是 20%-10% 的错算；只有“先跌后涨”同比例才会回到原点，本题不是。"}, {"type": "applied", "level": "进阶", "stem": "2024 年小麦产量占粮食总产量的比重约为（　）", "data": "【材料】2025 年某省粮食总产量 3200 万吨，比上年增长 4.0%；其中小麦产量 1200 万吨，比上年增长 2.0%。", "options": ["34.5%", "36.1%", "38.2%", "40.6%"], "answer": ["C"], "method": "求“基期比重”，用两期数据各自还原：\n① 2024 年总产量＝3200÷1.04≈3076.9；\n② 2024 年小麦＝1200÷1.02≈1176.5；\n③ 比重＝1176.5÷3076.9≈38.2%。", "explain": "3076.9 与 1176.5 相除得 38.2%，选 C。", "tip": "求“去年的比重”必须把分子分母都还原到去年，不能拿今年的 1200÷3200=37.5% 交差。", "hard": "干扰项 37.5% 正是“今年比重”的错用；注意题干问的是 2024 年。"}, {"type": "applied", "level": "基础", "stem": "2025 年该市社会消费品零售总额比上年增长约多少亿元（　）", "data": "【材料】2025 年某市社会消费品零售总额 4800 亿元，同比增长 6.5%。", "options": ["265 亿元", "293 亿元", "312 亿元", "330 亿元"], "answer": ["B"], "method": "已知现期+增长率求增长量：\n① 基期＝4800÷1.065≈4507；\n② 增长量＝4800-4507≈293。\n也可用 4800×6.5%/1.065≈293。", "explain": "4800÷1.065≈4507.0，4800-4507.0=293，选 B。", "tip": "不能直接 4800×6.5%=312（那是拿现期当基期）。", "hard": "干扰项 312 是典型的“现期×增长率”错算，本题问增长量必须除 (1+r)。"}, {"type": "applied", "level": "进阶", "stem": "2026 年营收比 2024 年增长约（　）", "data": "【材料】某企业 2024 年营收为 50 亿元，2025 年同比增长 12%，2026 年同比增长 15%。", "options": ["25.0%", "27.0%", "28.8%", "30.5%"], "answer": ["C"], "method": "间隔（复合）增长率：\n① r＝12%+15%+12%×15%；\n② ＝27%+1.8%＝28.8%。", "explain": "1.12×1.15=1.288，即增长 28.8%，选 C。", "tip": "两个增长率相加得 27% 是漏掉了乘积项 1.8%。", "hard": "干扰项 27.0% 就是漏乘 r1×r2；间隔增长率必须加乘积项。"}, {"type": "applied", "level": "基础", "stem": "2019—2024 年该省新能源汽车产量的年均增长量约为（　）", "data": "【材料】2019 年某省新能源汽车产量为 25.0 万辆，2024 年增至 62.5 万辆。", "options": ["6.3 万辆", "7.5 万辆", "9.4 万辆", "12.5 万辆"], "answer": ["B"], "method": "年均增长量＝（末期-初期）÷年份差：\n① 年份差＝5；\n② (62.5-25.0)÷5=7.5。", "explain": "(62.5-25.0)÷5=37.5÷5=7.5 万辆，选 B。", "tip": "年份差是 5 不是 6；除以 6 会得到 6.25（贴近干扰项 6.3）。", "hard": "干扰项 6.3 就是“除以 6 年”的错算；数年份差时别把 2019 本身也算一年。"}, {"type": "applied", "level": "进阶", "stem": "2025 年出口交货值占主营业务收入的比重，比上年约（　）", "data": "【材料】2025 年某行业主营业务收入 8000 亿元，同比增长 8%；其中出口交货值 2000 亿元，同比增长 16%。", "options": ["提高 0.8 个百分点", "提高 1.7 个百分点", "提高 2.6 个百分点", "下降 1.7 个百分点"], "answer": ["B"], "method": "两期比重差：\n① 今年占比＝2000÷8000=25.0%；\n② 去年占比＝(2000÷1.16)÷(8000÷1.08)≈1724.1÷7407.4≈23.3%；\n③ 差＝25.0%-23.3%＝+1.7 个百分点。", "explain": "部分增速(16%)>总体增速(8%)，比重上升；由 23.3% 升到 25.0%，提高约 1.7 个百分点，选 B。", "tip": "先看增速大小即可定方向：部分增速快则比重升，可直接排除“下降”。", "hard": "干扰项 0.8 是“增速差 8%×占比”类型的粗估；两期比重差要按占比相减算，不能只比增速。"}, {"type": "applied", "level": "进阶", "stem": "2024 年 1—8 月该市基础设施投资占固定资产投资的比重约为（　）", "data": "【材料】某市 2025 年 1—8 月完成固定资产投资 3456 亿元，同比增长 5%；其中基础设施投资 1382 亿元，同比增长 3%。", "options": ["33.4%", "36.2%", "40.8%", "45.1%"], "answer": ["C"], "method": "基期比重（分子分母各自还原）：\n① 2024 年总投资＝3456÷1.05≈3291.4；\n② 2024 年基础设施＝1382÷1.03≈1341.7；\n③ 比重＝1341.7÷3291.4≈40.8%。", "explain": "1341.7÷3291.4≈40.8%，选 C。", "tip": "别用今年的 1382÷3456=40.0% 直接答；问的是 2024 年，须还原基期。", "hard": "今年比重 40.0% 与正确答案 40.8% 很接近，只有还原基期才能分辨。"}, {"type": "applied", "level": "进阶", "stem": "某地区快递业务量从 2020 年到 2025 年的年均增长率约为（　）", "data": "【材料】2025 年某地区快递业务量 120 亿件，2020 年为 60 亿件。", "options": ["10.0%", "12.5%", "14.9%", "20.0%"], "answer": ["C"], "method": "年均增长率（倍数法）：\n① 倍数＝120÷60=2，即 (1+r)^5=2；\n② 2 开 5 次方≈1.149；\n③ r≈14.9%。", "explain": "2^(1/5)≈1.149，年均增长率≈14.9%，选 C。", "tip": "不能把总增长率 100% 除以 5 得 20%——几何平均必小于算术平均。", "hard": "干扰项 20.0% 就是 100%÷5 的错算；“5 年翻一番”，记住对应年均约 15%（72 法则：72÷5≈14.4）。"}, {"type": "applied", "level": "进阶", "stem": "2025 年该省居民消费支出占人均可支配收入的比重，与上年相比约（　）", "data": "【材料】2025 年某省居民人均可支配收入 42000 元，同比增长 5.5%；居民人均消费支出 28000 元，同比增长 6.0%。", "options": ["下降 0.3 个百分点", "提高 0.3 个百分点", "提高 1.2 个百分点", "提高 2.4 个百分点"], "answer": ["B"], "method": "两期比重差：\n① 今年占比＝28000÷42000≈66.67%；\n② 去年占比＝(28000÷1.06)÷(42000÷1.055)=26415.1÷39810.4≈66.35%；\n③ 差＝66.67%-66.35%≈+0.3 个百分点。", "explain": "消费支出增速(6.0%)略快于收入增速(5.5%)，占比小幅上升约 0.3 个百分点，选 B。", "tip": "增速接近时，两期比重差往往很小（零点几个百分点），要精算，不能凭感觉估成 1~2 个百分点。", "hard": "干扰项 1.2/2.4 是把分子分母做错位相减的产物；增速只差 0.5 个百分点，比重要变化应远小于 1 个百分点。"}]}, {"set": 3, "date": "2026-09-30", "session": "day", "title": "资料分析速算训练 · 第 3 批（首数直除 / 增长率与增长量 / 间隔增长 / 年均增长 / 比重与两期比重差 / 倍数与平均数）", "difficulty": "基础+中等", "items": [{"type": "pure", "level": "基础", "stem": "5638 ÷ 62.5 的结果最接近（　）", "data": "", "options": ["90.2", "84.6", "96.4", "78.9"], "answer": ["A"], "method": "首数直除：\n① 定首位：62.5×9＝562.5，5638 里能放 90 个 62.5；\n② 精确一位：62.5×90＝5625，余 13；\n③ 补小数：13÷62.5≈0.21，合计约 90.2。", "explain": "62.5×90＝5625，5638−5625＝13，13÷62.5≈0.21，所以 5638÷62.5≈90.2，选 A。", "tip": "先定“商的首位是 9”，把 84.6、78.9 这类首位为 8 的选项直接排除，再用余数定到小数点后一位。", "hard": "90.2 与 96.4 相差约 7%，只估到“九十多”会摇摆，必须算到小数点后一位。"}, {"type": "pure", "level": "基础", "stem": "247 × 38.2% 的结果最接近（　）", "data": "", "options": ["84.4", "94.4", "103.7", "114.8"], "answer": ["B"], "method": "百分数化小数再乘：\n① 38.2%≈0.382；\n② 247×0.382＝247×0.38＋247×0.002＝93.86＋0.49≈94.4。", "explain": "247×38.2%＝247×0.382≈94.35，最接近 94.4，选 B。", "tip": "把 38.2% 拆成 38%＋0.2% 更好算；直接用 40% 会得到 98.8，容易误选 103.7 附近的项。", "hard": "选项间隔约 10，若把 38.2% 当成 42% 就会滑到 103.7，注意别四舍五入过头。"}, {"type": "pure", "level": "基础", "stem": "某指标由 3200 增长到 4160，增长率约为（　）", "data": "", "options": ["22%", "26%", "30%", "34%"], "answer": ["C"], "method": "增长率＝（现期−基期）÷基期：\n① 增长量＝4160−3200＝960；\n② 960÷3200＝0.3＝30%。", "explain": "（4160−3200）÷3200＝960÷3200＝30%，选 C。", "tip": "分母必须是基期（3200），不能用现期（4160）当分母，否则会得到约 23% 的错值。", "hard": "干扰项 22% 正是“960÷4160≈23%”的错算结果，方向一错就掉进去。"}, {"type": "pure", "level": "基础", "stem": "某量连续两年分别增长 20% 和 25%，两年合计增长约为（　）", "data": "", "options": ["40%", "45%", "48%", "50%"], "answer": ["D"], "method": "间隔（复合）增长率：\n① 用（1＋r1）（1＋r2）−1；\n② 1.2×1.25＝1.5；\n③ 1.5−1＝0.5＝50%。", "explain": "1.2×1.25＝1.5，两年合计增长 50%，选 D。", "tip": "不能直接相加（20%＋25%＝45%），复合增长要相乘，第二年的增长是在“已经涨过”的基数上发生的。", "hard": "干扰项 45% 就是“直接相加”的经典错法，凡是问“两年合计/间隔增长”，一律用乘法。"}, {"type": "pure", "level": "基础", "stem": "某市 GDP 由 2019 年的 480 亿元增至 2024 年的 780 亿元，年均增长量约为（　）", "data": "", "options": ["60 亿元", "50 亿元", "75 亿元", "300 亿元"], "answer": ["A"], "method": "年均增长量＝（末期−初期）÷年数差：\n① 增长总量＝780−480＝300；\n② 年数＝2024−2019＝5；\n③ 300÷5＝60。", "explain": "（780−480）÷（2024−2019）＝300÷5＝60 亿元，选 A。", "tip": "年数是“年份差”（5 年），不是“年份个数”（6 个）。用 6 会得到 50，正好是干扰项。", "hard": "选项里同时放了 50（年数算成 6）和 300（把总量当年均量），两个坑都要防。"}, {"type": "pure", "level": "进阶", "stem": "某指标 4 年间从 100 增至 146.41，年均增长率约为（　）", "data": "", "options": ["8%", "10%", "12%", "14%"], "answer": ["B"], "method": "年均增长率＝（末期÷初期）^(1÷年数)−1：\n① 146.41÷100＝1.4641；\n② 1.4641 开 4 次方：1.1^4＝1.4641；\n③ 1.1−1＝10%。", "explain": "因为 1.1^4＝1.4641，所以年均增长率＝10%，选 B。", "tip": "开平方开不出整数时，用代入法：把选项的 1+r 试乘 4 次，看哪个接近 1.4641。", "hard": "年均增长率不能用“总增长÷年数”。总增长 46.41%÷4＝11.6%，会误选 12%。"}, {"type": "pure", "level": "基础", "stem": "某年 A 项为 840，总体为 3500，A 占总体比重约为（　）", "data": "", "options": ["18%", "21%", "24%", "27%"], "answer": ["C"], "method": "比重＝部分÷总体：\n① 840÷3500；\n② 3500×24%＝840；\n③ 故比重为 24%。", "explain": "840÷3500＝0.24＝24%，选 C。", "tip": "用“乘回去验算”最快：3500×24%＝840，正好对上，直接选定。", "hard": "若把分母看成 3200 或分子看成 940，都会偏到 21% 或 27%，注意抄数。"}, {"type": "pure", "level": "进阶", "stem": "某部分占总体的比重为 40%，若总体增长 10%、该部分增长 20%，则新的比重约为（　）", "data": "", "options": ["40.0%", "42.0%", "43.0%", "43.6%"], "answer": ["D"], "method": "两期比重：新比重＝旧比重×（1＋部分增速）÷（1＋总体增速）：\n① 0.40×1.2＝0.48；\n② 0.48÷1.1≈0.4364；\n③ 即约 43.6%。", "explain": "0.40×1.2÷1.1＝0.48÷1.1≈43.6%，选 D。", "tip": "部分增速快于总体，比重必上升；但升幅不是 20%−10%＝10 个百分点，要用乘法算。", "hard": "干扰项 42.0% 是“0.40×（1＋0.2−0.1）”的错算；两期比重必须用除法，不能加减。"}, {"type": "pure", "level": "进阶", "stem": "甲是乙的 3.6 倍。若甲增长 10%、乙增长 20%，则现在甲是乙的多少倍（　）", "data": "", "options": ["3.3", "3.0", "3.6", "3.9"], "answer": ["A"], "method": "倍数变化＝原倍数×（1＋甲增速）÷（1＋乙增速）：\n① 3.6×1.1＝3.96；\n② 3.96÷1.2＝3.3。", "explain": "3.6×1.1÷1.2＝3.3，选 A。", "tip": "分母增速快于分子时倍数下降；3.6 不会保持不变（除非两者增速相同）。", "hard": "干扰项 3.9 是“3.6×1.1”后忘了除 1.2 的结果，别漏掉分母的增长。"}, {"type": "pure", "level": "基础", "stem": "某地区粮食总产 1245 万吨，播种面积 830 万公顷，平均单产约为多少吨/公顷（　）", "data": "", "options": ["1.2", "1.5", "1.8", "2.1"], "answer": ["B"], "method": "平均数＝总量÷份数：\n① 1245÷830；\n② 830×1.5＝1245；\n③ 故为 1.5 吨/公顷。", "explain": "1245÷830＝1.5，选 B。", "tip": "平均数题先看单位对不对（吨/公顷），再用“份数×选项”反验。", "hard": "若把 1245 看成 1245÷0.83 之类，会偏到 1.8 以上，注意单位都是“万”，可约掉。"}, {"type": "pure", "level": "基础", "stem": "480 的 12.5% 是（　）", "data": "", "options": ["48", "54", "60", "72"], "answer": ["C"], "method": "化分数：\n① 12.5%＝1/8；\n② 480÷8＝60。", "explain": "480×12.5%＝480÷8＝60，选 C。", "tip": "常用化分数背熟：1/8＝12.5%、1/6≈16.7%、1/7≈14.3%、1/9≈11.1%。", "hard": "干扰项 48 是“480×10%”的错算，把 12.5% 当 10% 就会错。"}, {"type": "pure", "level": "进阶", "stem": "（1＋15%）×（1−10%）−1 的结果是（　）", "data": "", "options": ["2.5%", "3.0%", "3.2%", "3.5%"], "answer": ["D"], "method": "先涨后跌的复合变化：\n① 1.15×0.90＝1.035；\n② 1.035−1＝0.035＝3.5%。", "explain": "1.15×0.9＝1.035，净变化 3.5%，选 D。", "tip": "“涨 15% 再跌 10%”不等于涨 5%。跌是在涨过之后的基数上算的，复合结果一定小于直接相减。", "hard": "干扰项 2.5% 与 3.5% 只差 1 个百分点，必须老实相乘，靠感觉估很容易错。"}, {"type": "applied", "level": "基础", "stem": "2025 年该市高新技术产业产值比上年增长约多少亿元（　）", "data": "【材料】2025 年某市高新技术产业产值 5600 亿元，比上年增长 12%。", "options": ["560 亿元", "600 亿元", "672 亿元", "700 亿元"], "answer": ["B"], "method": "已知现期求增长量：\n① 基期＝5600÷1.12＝5000；\n② 增长量＝5600−5000＝600。\n也可用 5600×12%÷1.12≈600。", "explain": "5600÷1.12＝5000，5600−5000＝600 亿元，选 B。", "tip": "不能直接 5600×12%＝672（那是拿现期当基期）。问“增长量”必须先用 1＋r 还原基期。", "hard": "干扰项 672 是典型错算；560 是“5000×12% 但基期抄错”的近似错值，两个都要防。"}, {"type": "applied", "level": "基础", "stem": "2024 年该县旅游收入约为（　）", "data": "【材料】2025 年某县实现旅游收入 86.4 亿元，同比增长 8%。", "options": ["80.0 亿元", "82.4 亿元", "78.0 亿元", "86.4 亿元"], "answer": ["A"], "method": "求基期量：\n① 基期＝现期÷（1＋r）；\n② 86.4÷1.08；\n③ 1.08×80＝86.4，故为 80.0 亿元。", "explain": "86.4÷1.08＝80.0，选 A。", "tip": "求基期一定要除（1＋r），不能用“现期×（1−r）”或“现期−现期×r”草草相减。", "hard": "干扰项 82.4 来自 86.4×（1−0.08）附近的错算，数值很接近，务必用除法。"}, {"type": "applied", "level": "基础", "stem": "2025 年该省第三产业增加值占 GDP 的比重约为（　）", "data": "【材料】2025 年某省 GDP 为 62000 亿元，其中第三产业增加值 34100 亿元。", "options": ["50%", "53%", "55%", "58%"], "answer": ["C"], "method": "比重＝部分÷总体：\n① 34100÷62000；\n② 62000×55%＝34100；\n③ 故为 55%。", "explain": "34100÷62000＝0.55＝55%，选 C。", "tip": "用“总体×选项”反验最快：62000×55%＝34100，一步到位。", "hard": "选项间隔 2—3 个百分点，若把 34100 抄成 33100 就会偏到 53%，抄数要仔细。"}, {"type": "applied", "level": "进阶", "stem": "2025 年高新技术产业增加值占规上工业比重比上年提高约（　）", "data": "【材料】2024 年某市高新技术产业增加值占规上工业增加值比重为 32%。2025 年该市规上工业增加值增长 6%，高新技术产业增加值增长 14%。", "options": ["1.6 个百分点", "2.0 个百分点", "2.2 个百分点", "2.4 个百分点"], "answer": ["D"], "method": "两期比重差：\n① 新比重＝0.32×1.14÷1.06；\n② 0.32×1.14＝0.3648，0.3648÷1.06≈0.3442；\n③ 提高＝34.42%−32%≈2.4 个百分点。", "explain": "0.32×1.14÷1.06≈34.4%，比 32% 提高约 2.4 个百分点，选 D。", "tip": "部分增速（14%）快于总体（6%），比重上升；升幅要用“新比重−旧比重”，不是两者增速相减。", "hard": "干扰项 2.0 来自“8%×32%≈2.6 再凭感觉取整”，正确算法只走两期比重公式。"}, {"type": "applied", "level": "基础", "stem": "该市地铁运营里程的年均增长量约为（　）", "data": "【材料】某市地铁运营里程 2019 年为 360 公里，2024 年为 860 公里。", "options": ["80 公里", "90 公里", "100 公里", "120 公里"], "answer": ["C"], "method": "年均增长量＝（末期−初期）÷年数差：\n① 860−360＝500；\n② 年数＝2024−2019＝5；\n③ 500÷5＝100。", "explain": "（860−360）÷5＝100 公里，选 C。", "tip": "年数用年份差 5，别用 6；分子是总增量 500，别直接用末期 860。", "hard": "选项 80/90/100/120 都在同一量级，年数或分子抄错就会串位。"}, {"type": "applied", "level": "基础", "stem": "2025 年 A 产品出口额约是 B 产品的（　）", "data": "【材料】2025 年某市 A 产品出口额为 240 亿美元，B 产品出口额为 75 亿美元。", "options": ["3.2 倍", "2.8 倍", "3.0 倍", "3.6 倍"], "answer": ["A"], "method": "倍数＝A÷B：\n① 240÷75；\n② 75×3＝225，余 15；\n③ 15÷75＝0.2，合计 3.2 倍。", "explain": "240÷75＝3.2，选 A。", "tip": "问“A 是 B 的几倍”用 A÷B；“A 比 B 多几倍”才要再减 1。", "hard": "干扰项 2.8 与 3.2 相差不大，若把 240 看成 225 就会偏到 3.0，先算整数部分再补小数。"}, {"type": "applied", "level": "基础", "stem": "该市平均每个公园新增绿化面积约为（　）", "data": "【材料】2025 年某市新增绿化面积 960 公顷，涉及 24 个新建公园。", "options": ["28 公顷", "32 公顷", "36 公顷", "40 公顷"], "answer": ["D"], "method": "平均数＝总量÷份数：\n① 960÷24；\n② 24×40＝960；\n③ 故为 40 公顷。", "explain": "960÷24＝40 公顷，选 D。", "tip": "平均数题先确认“份数”是公园数 24，别把面积当份数。", "hard": "960÷24 可以先把两边都约 24：960÷24＝40，一步到位；硬除容易把 36 当答案。"}, {"type": "applied", "level": "基础", "stem": "2023 年该市快递业务量约为（　）", "data": "【材料】某市 2025 年快递业务量为 12.6 亿件，比 2023 年增长 40%。", "options": ["9.0 亿件", "8.4 亿件", "7.6 亿件", "10.2 亿件"], "answer": ["A"], "method": "跨期求基期：\n① 基期＝现期÷（1＋总增速）；\n② 12.6÷1.4；\n③ 1.4×9＝12.6，故为 9.0 亿件。", "explain": "12.6÷1.4＝9.0 亿件，选 A。", "tip": "题目给的是“比 2023 年增长 40%”，直接除 1.4 即可，不必逐年拆算。", "hard": "干扰项 10.2 来自 12.6×0.8 附近的错算；记住基期＝现期÷（1＋r）。"}]}, {"set": 4, "date": "2026-10-01", "session": "day", "title": "资料分析速算训练 · 第 4 批（首数直除 / 增长率与增长量 / 间隔增长 / 年均增长 / 两期比重差 / 倍数与平均数 / 化分数）", "difficulty": "基础+中等", "items": [{"type": "pure", "level": "基础", "stem": "估算 4862 ÷ 1.24，结果最接近（　）", "options": ["3920", "4350", "3610", "4120"], "answer": ["A"], "method": "首数直除：48÷1.24≈38~39，量级约 3900；或用 1/1.24≈0.806，4862×0.806≈3920。", "explain": "4862÷1.24≈3920.97，取 3920，选 A。", "tip": "除法别做成乘法（4862×1.24≈6029 是常见错算）。", "hard": "结果应略小于 4862；4350 是错算干扰项。"}, {"type": "pure", "level": "基础", "stem": "4200 的 3.7% 约为（　）", "options": ["155", "15.5", "1550", "1.55"], "answer": ["A"], "method": "3.7%=0.037，4200×0.037=4200×37÷1000=155.4。", "explain": "约 155.4，取 155，选 A。", "tip": "百分号换算别漏一位：3.7% 是 0.037。", "hard": "15.5 是漏一位小数的结果；先定量级再选。"}, {"type": "pure", "level": "基础", "stem": "5/7 约等于（　）", "options": ["57.1%", "71.4%", "66.7%", "77.8%"], "answer": ["B"], "method": "1/7≈14.3%，5/7≈5×14.3%≈71.4%。", "explain": "5÷7≈0.7143，即 71.4%，选 B。", "tip": "常用化分数：1/7≈14.3%、1/6≈16.7%、1/9≈11.1%、1/8=12.5%。", "hard": "57.1% 是 4/7，易与 5/7 混。"}, {"type": "pure", "level": "基础", "stem": "某指标由 240 增长到 300，增长率为（　）", "options": ["25%", "20%", "30%", "12.5%"], "answer": ["A"], "method": "增长率=(现期−基期)÷基期=(300−240)÷240=60÷240=25%。", "explain": "60÷240=25%，选 A。", "tip": "分母一定是基期（240）。", "hard": "20% 是用 60÷300 的错算（分母用成现期）。"}, {"type": "pure", "level": "进阶", "stem": "某量第一年增长 20%，第二年增长 25%，两年合计增长（　）", "options": ["45%", "20%", "50%", "55%"], "answer": ["C"], "method": "间隔增长率 r=r₁+r₂+r₁×r₂=20%+25%+20%×25%=45%+5%=50%。", "explain": "1.20×1.25=1.50，两年共增长 50%，选 C。", "tip": "两年增长不能简单相加，要补乘积项。", "hard": "45% 是漏掉乘积项 5% 的干扰项。"}, {"type": "pure", "level": "进阶", "stem": "某量两年共增长 69%，其中第一年增长 30%，第二年增长（　）", "options": ["30%", "39%", "25%", "33%"], "answer": ["A"], "method": "倍数法：1+r₂=(1+69%)÷(1+30%)=1.69÷1.30=1.30，故 r₂=30%。", "explain": "1.69÷1.3=1.3，第二年增长 30%，选 A。", "tip": "用“1+总增长”除“1+已知年增长”。", "hard": "39% 是 69%−30% 直接相减的错算。"}, {"type": "pure", "level": "基础", "stem": "某量 2019 年 120，2024 年 270，2019—2024 年年均增长量为（　）", "options": ["30", "25", "37.5", "50"], "answer": ["A"], "method": "年均增长量=(270−120)÷(2024−2019)=150÷5=30。", "explain": "150÷5=30，选 A。", "tip": "年份差=末年−首年=5。", "hard": "37.5 是 150÷4 的错算。"}, {"type": "pure", "level": "进阶", "stem": "某部分占比由 25% 上升到 30%，则占比变化（　）", "options": ["上升 35%", "下降 5 个百分点", "上升 3 个百分点", "上升 5 个百分点"], "answer": ["D"], "method": "比重变化用百分点：30%−25%=+5 个百分点。", "explain": "上升 5 个百分点，选 D。", "tip": "比重变化量用“百分点”，是两个比重相减。", "hard": "“上升 35%”把百分点当成增长率（实为 +20%）。"}, {"type": "pure", "level": "基础", "stem": "A=1.26 万，B=0.42 万，A 是 B 的（　）倍", "options": ["2", "3", "4", "0.33"], "answer": ["B"], "method": "单位相同直接相除：1.26÷0.42=3。", "explain": "1.26÷0.42=3，选 B。", "tip": "“A 是 B 的几倍”=A÷B。", "hard": "0.33 是 B÷A 的倒算。"}, {"type": "pure", "level": "基础", "stem": "五个数据 82、91、78、85、94 的平均数为（　）", "options": ["86", "85", "87", "88"], "answer": ["A"], "method": "先求和 430，再除以项数 5：430÷5=86。", "explain": "430÷5=86，选 A。", "tip": "平均数=总量÷项数。", "hard": "误用 430÷4 会明显偏离。"}, {"type": "pure", "level": "进阶", "stem": "某项指标由 1.05 调整为 1.10，增幅约为（　）", "options": ["4.5%", "4.8%", "3.3%", "5.0%"], "answer": ["B"], "method": "增幅=(1.10−1.05)÷1.05=0.05÷1.05≈4.76%≈4.8%。", "explain": "约 4.8%，选 B。", "tip": "分母是原来的 1.05。", "hard": "4.5% 是 0.05÷1.10 的错算（分母用错）。"}, {"type": "pure", "level": "进阶", "stem": "某量 4 年翻了一番（共增长 100%），年均增长率约为（　）", "options": ["15%", "25%", "19%", "20%"], "answer": ["C"], "method": "4 年后变为 2 倍，年均=2^(1/4)−1≈1.189−1=18.9%≈19%。", "explain": "约 18.9%，选 C。", "tip": "年均增长率要“开方”，不能总增长除以年数。", "hard": "25% 是 100%÷4 的错算。"}, {"type": "applied", "level": "基础", "stem": "2025 年该市新能源汽车产量同比增长（　）", "data": "【材料】2024 年某市新能源汽车产量 40 万辆，2025 年增至 48 万辆。", "options": ["16.7%", "20%", "8%", "120%"], "answer": ["B"], "method": "增长率=(48−40)÷40=8÷40=20%。", "explain": "8÷40=20%，选 B。", "tip": "分母用基期（40 万辆）。", "hard": "16.7% 是 8÷48 的错算。"}, {"type": "applied", "level": "基础", "stem": "2019—2024 年该市常住人口年均增长量为（　）", "data": "【材料】某市常住人口 2019 年 620 万人，2024 年 680 万人。", "options": ["10 万", "12 万", "15 万", "60 万"], "answer": ["B"], "method": "年均增长量=(680−620)÷(2024−2019)=60÷5=12（万人/年）。", "explain": "60÷5=12 万，选 B。", "tip": "年份差为 5。", "hard": "15 万是 60÷4 的错算。"}, {"type": "applied", "level": "基础", "stem": "该公司线上渠道销售额占比约为（　）", "data": "【材料】某公司全年销售额 5000 万元，其中线上渠道 1800 万元。", "options": ["24%", "28%", "36%", "64%"], "answer": ["C"], "method": "占比=部分÷整体=1800÷5000=0.36=36%。", "explain": "36%，选 C。", "tip": "求占比用“部分÷整体”。", "hard": "64% 是线下占比（1−36%）。"}, {"type": "applied", "level": "进阶", "stem": "2025 年该产品销量比 2023 年增长（　）", "data": "【材料】某产品 2023 年销量 100 万件；2024 年比 2023 年增长 20%；2025 年比 2024 年增长 15%。", "options": ["35%", "38%", "40%", "5%"], "answer": ["B"], "method": "1.20×1.15=1.38，即增长 38%。", "explain": "1.38−1=38%，选 B。", "tip": "间隔增长率=r₁+r₂+r₁r₂。", "hard": "35% 是简单相加，漏了 20%×15%=3%。"}, {"type": "applied", "level": "进阶", "stem": "2025 年该市数字经济增加值占 GDP 比重比上年（　）", "data": "【材料】某市 2024 年 GDP 8000 亿元，其中数字经济 2000 亿元；2025 年 GDP 9000 亿元，其中数字经济 2700 亿元。", "options": ["上升 5 个百分点", "上升 3 个百分点", "上升 35%", "下降 5 个百分点"], "answer": ["A"], "method": "新比重 2700÷9000=30%，旧比重 2000÷8000=25%，差 +5 个百分点。", "explain": "上升 5 个百分点，选 A。", "tip": "比重变化用“百分点”表示。", "hard": "“上升 35%”是把比重值当成了增长率。"}, {"type": "applied", "level": "基础", "stem": "该企业上半年月均产量为（　）", "data": "【材料】某企业 1—6 月产量依次为 22、25、28、24、26、25（万台）。", "options": ["24 万台", "26 万台", "27 万台", "25 万台"], "answer": ["D"], "method": "求和 150，月均=150÷6=25 万台。", "explain": "150÷6=25 万台，选 D。", "tip": "平均数=总量÷月数。", "hard": "按 5 个月除可得 30，属漏项错算。"}, {"type": "applied", "level": "基础", "stem": "使用该功能的用户约为（　）", "data": "【材料】某平台年度活跃用户约 3.5 亿人，调查显示约七分之一的用户使用过某项新功能。", "options": ["3500 万", "5000 万", "7000 万", "2500 万"], "answer": ["B"], "method": "3.5 亿×1/7=0.5 亿=5000 万。", "explain": "5000 万，选 B。", "tip": "1/7≈14.3%，3.5 亿的 1/7 即 5000 万。", "hard": "3500 万是 3.5 亿×1/10 的错算。"}, {"type": "applied", "level": "进阶", "stem": "2021—2025 年该县农村居民人均可支配收入年均增长率约为（　）", "data": "【材料】某县农村居民人均可支配收入 2021 年 1.6 万元，2025 年 2.56 万元（共 4 年）。", "options": ["10%", "16%", "25%", "12.5%"], "answer": ["D"], "method": "倍数=2.56÷1.6=1.6，4 年年均=1.6^(1/4)−1≈1.125−1≈12.5%。", "explain": "约 12.5%，选 D。", "tip": "年均增长率=（末年/首年）^(1/年数)−1。", "hard": "16% 混淆倍数与增速；25% 是 1÷4 的错算。"}]}, {"set": 5, "date": "2026-10-02", "session": "am", "title": "资料分析速算训练 · 第 5 批（首数直除 / 估算范围 / 增长率与增长量 / 间隔增长率 / 年均增长量 / 年均增长率 / 两期比重差 / 倍数与平均数 / 化分数 / 百分数加减）", "difficulty": "基础+中等", "items": [{"type": "pure", "level": "基础", "stem": "4128 ÷ 1.37 ≈（　）", "options": ["2810", "3013", "3210", "3510"], "answer": ["B"], "method": "首数直除：1.37 × 3000 = 4110，略小于 4128，故结果略大于 3000。", "explain": "1.37×3000=4110＜4128，商约 3013，选 B。", "tip": "先定“整数档”，再用首数微调。", "hard": "3510 是 4128÷1.18 之类的错算。"}, {"type": "pure", "level": "中等", "stem": "7382 ÷ 0.842 ≈（　）", "options": ["7967", "8367", "8767", "9167"], "answer": ["C"], "method": "0.842 × 8760 = 7375.9，接近 7382，故商约 8767。", "explain": "7382÷0.842≈8767，选 C。", "tip": "除以小于 1 的数，结果比原数大。", "hard": "7967 是 7382÷0.926 的错算。"}, {"type": "pure", "level": "基础", "stem": "2160 的 1/7 约为（　）", "options": ["289", "299", "309", "319"], "answer": ["C"], "method": "化分数：1/7≈14.3%，2160÷7≈308.6。", "explain": "2160÷7≈308.6，取 309，选 C。", "tip": "记牢 1/7≈14.3%、1/8=12.5%、1/9≈11.1%。", "hard": "319 是 2160÷6.77 之类的错算。"}, {"type": "pure", "level": "中等", "stem": "某商品单价先上涨 20%，后又下降 20%，则最终价格与原价比（　）", "options": ["不变", "下降 4%", "上涨 4%", "下降 2%"], "answer": ["B"], "method": "1×(1+20%)×(1−20%)=1×1.2×0.8=0.96，即下降 4%。", "explain": "1.2×0.8=0.96，比原价少 4%，选 B。", "tip": "先涨后降同一比例，最终必低于原价（乘数 1−x²）。", "hard": "误以为“一涨一降正好抵消”。"}, {"type": "pure", "level": "基础", "stem": "某市 GDP 由 2019 年的 800 亿元增至 2024 年的 1200 亿元，年均增长量约为（　）亿元", "options": ["60", "80", "100", "120"], "answer": ["A"], "method": "年均增长量=(末期−初期)÷年数差=(1200−800)÷(2024−2019)=400÷5=80。", "explain": "400÷5=80 亿元，选 A。", "tip": "年数差用“末年−首年”，不是“年份个数”。", "hard": "误用 400÷6≈66.7。"}, {"type": "pure", "level": "基础", "stem": "3840 约是 1280 的（　）倍", "options": ["2.8", "3", "3.2", "4"], "answer": ["B"], "method": "3840÷1280=3。", "explain": "3840÷1280=3，选 B。", "tip": "倍数＝前者÷后者，注意谁比谁。", "hard": "4 是把 1280×3≈3840 与“约 4 倍”混。"}, {"type": "pure", "level": "基础", "stem": "某企业 5 个部门人数分别为 48、52、45、55、50 人，则平均人数为（　）", "options": ["48", "49", "50", "51"], "answer": ["C"], "method": "总数=48+52+45+55+50=250，平均=250÷5=50。", "explain": "250÷5=50，选 C。", "tip": "平均数=总数÷个数。", "hard": "以最大最小取中值易误判。"}, {"type": "pure", "level": "中等", "stem": "5936 ÷ 7.9 ≈（　）", "options": ["651", "701", "751", "801"], "answer": ["C"], "method": "7.9 × 750 = 5925，接近 5936，故商约 751。", "explain": "5936÷7.9≈751，选 C。", "tip": "用 8×750=6000 快速框定范围。", "hard": "801 是 5936÷7.4 的错算。"}, {"type": "pure", "level": "基础", "stem": "39.8 × 5.12 ≈（　）", "options": ["164", "184", "204", "224"], "answer": ["C"], "method": "估算范围：40×5=200，40×5.12=204.8，故约 204。", "explain": "≈40×5.12=204.8，取 204，选 C。", "tip": "把 39.8 近似为 40，误差极小。", "hard": "224 是把 5.12 当成 5.6 的错算。"}, {"type": "pure", "level": "中等", "stem": "某地游客人数 2023 年比 2022 年增长 10%，2024 年比 2023 年增长 20%，则 2024 年比 2022 年增长约（　）", "options": ["22%", "30%", "32%", "34%"], "answer": ["C"], "method": "间隔增长率：1.1 × 1.2 = 1.32，即增长 32%。", "explain": "1.1×1.2=1.32，增长 32%，选 C。", "tip": "间隔增长率≠两期增长率相加（10%+20%=30% 是干扰项）。", "hard": "30% 是把两期增长率直接相加的错算。"}, {"type": "pure", "level": "基础", "stem": "3/8 用百分数表示约为（　）", "options": ["33.3%", "35.0%", "37.5%", "42.9%"], "answer": ["C"], "method": "化分数：1/8=12.5%，故 3/8=37.5%。", "explain": "3÷8=0.375=37.5%，选 C。", "tip": "1/8=12.5% 是常用分数记忆点。", "hard": "33.3% 是 1/3 的值。"}, {"type": "pure", "level": "中等", "stem": "某指标由 100 增长到 121，这两年的年均增长率约为（　）", "options": ["9.5%", "10%", "11%", "21%"], "answer": ["B"], "method": "年均增长率：1×(1+r)²=1.21，则 (1+r)²=1.21，1+r=1.1，r=10%。", "explain": "开平方：√1.21=1.1，故年均增长 10%，选 B。", "tip": "两年翻成 1.21，年均即 10%（1.1²=1.21）。", "hard": "21% 是把总增长率直接当成年均增长率。"}, {"type": "applied", "level": "基础", "stem": "2025 年该市快递业务量同比增长（　）", "data": "【材料】2024 年某市快递业务量 12.5 亿件，2025 年增至 15 亿件。", "options": ["16.7%", "20%", "25%", "120%"], "answer": ["B"], "method": "增长率=(15−12.5)÷12.5=2.5÷12.5=20%。", "explain": "2.5÷12.5=20%，选 B。", "tip": "分母用基期（12.5 亿件）。", "hard": "16.7% 是 2.5÷15 的错算。"}, {"type": "applied", "level": "基础", "stem": "2025 年该地财政收入比上年增加（　）亿元", "data": "【材料】某地 2024 年财政收入 320 亿元，2025 年增至 368 亿元。", "options": ["38", "44", "48", "52"], "answer": ["C"], "method": "增长量=368−320=48 亿元。", "explain": "368−320=48，选 C。", "tip": "“增加多少”求的是增长量（减法），不是增长率。", "hard": "误用 368×15%≈55。"}, {"type": "applied", "level": "基础", "stem": "该校女生人数约占全校学生的（　）", "data": "【材料】某校共有学生 1200 人，其中女生 450 人。", "options": ["33.3%", "35.0%", "37.5%", "40.0%"], "answer": ["C"], "method": "占比=450÷1200=0.375=37.5%。", "explain": "450÷1200=37.5%，选 C。", "tip": "“占比”用部分÷总体。", "hard": "33.3% 是 400÷1200 的值。"}, {"type": "applied", "level": "基础", "stem": "该公司人均创收约为（　）万元", "data": "【材料】某公司全年营业收入 9600 万元，共有员工 120 人。", "options": ["60", "70", "80", "90"], "answer": ["C"], "method": "平均数=9600÷120=80 万元。", "explain": "9600÷120=80，选 C。", "tip": "人均＝总量÷人数。", "hard": "90 是 9600÷107 之类的错算。"}, {"type": "applied", "level": "基础", "stem": "甲地旅游收入约是乙地的（　）倍", "data": "【材料】甲地年旅游收入 45 亿元，乙地年旅游收入 9 亿元。", "options": ["4", "4.5", "5", "5.5"], "answer": ["C"], "method": "倍数=45÷9=5。", "explain": "45÷9=5，选 C。", "tip": "倍数＝前者÷后者。", "hard": "4 是 36÷9 的错算。"}, {"type": "applied", "level": "中等", "stem": "该市常住人口 2020—2025 年的年均增长量约为（　）万人", "data": "【材料】某市常住人口 2020 年为 500 万人，2025 年为 550 万人。", "options": ["8", "10", "12", "15"], "answer": ["B"], "method": "年均增长量=(550−500)÷(2025−2020)=50÷5=10 万人。", "explain": "50÷5=10，选 B。", "tip": "年数差为 5，不要用 6。", "hard": "8 是把 50÷6 四舍五入的错算。"}, {"type": "applied", "level": "中等", "stem": "2025 年该市第三产业占比比上年（　）", "data": "【材料】2024 年某市 GDP 1000 亿元，其中第三产业 550 亿元；2025 年 GDP 1100 亿元，其中第三产业 638 亿元。", "options": ["提高 2 个百分点", "提高 3 个百分点", "下降 3 个百分点", "提高 5 个百分点"], "answer": ["B"], "method": "2024 年占比=550÷1000=55%；2025 年占比=638÷1100=58%；提高 58%−55%=3 个百分点。", "explain": "55%→58%，提高 3 个百分点，选 B。", "tip": "比重变化用“百分点”表述，先分别算出两期比重再相减。", "hard": "“5 个百分点”是把 550 与 638 的差直接当成比重差。"}, {"type": "applied", "level": "中等", "stem": "该县 2024 年茶叶产量比 2022 年增长约（　）", "data": "【材料】某县茶叶产量 2023 年比 2022 年增长 25%，2024 年比 2023 年增长 20%。", "options": ["45%", "48%", "50%", "55%"], "answer": ["C"], "method": "间隔增长率：1.25 × 1.2 = 1.5，即增长 50%。", "explain": "1.25×1.2=1.5，增长 50%，选 C。", "tip": "间隔两年用乘法相乘，不是相加（25%+20%=45% 是干扰项）。", "hard": "45% 是把两期增长率相加的错算。"}]}, {"set": 6, "date": "2026-10-03", "session": "day", "title": "资料分析速算训练 · 第 6 批（首数直除 / 估算与范围 / 增长率与增长量 / 间隔增长率 / 年均增长量 / 年均增长率 / 两期比重差 / 倍数与平均数 / 化分数 / 百分数加减）", "difficulty": "基础+中等", "items": [{"type": "pure", "level": "基础", "stem": "5236 ÷ 1.28 ≈（　）", "options": ["3890", "4091", "4290", "4520"], "answer": ["B"], "method": "首数直除：1.28 × 4000 = 5120，略小于 5236，故结果略大于 4000。再试 1.28×4090=5235.2，几乎相等。", "explain": "1.28×4090=5235.2，接近 5236，商约 4091，选 B。", "tip": "先定“整数档”（4000），再用首数微调，不必精确长除。", "hard": "4520 是用 1.16 之类除数算出的，注意别把除数看错。"}, {"type": "pure", "level": "基础", "stem": "7189 ÷ 0.923 ≈（　）", "options": ["7490", "7790", "8090", "8390"], "answer": ["B"], "method": "0.923 × 7800 = 7199.4，略大于 7189，故商略小于 7800，约 7790。", "explain": "0.923×7790≈7189，选 B。", "tip": "除以小于 1 的数，结果比原数大，可先排除 7490 以下的项。", "hard": "7490 是把结果算小了（误按 ÷1.0 估）。"}, {"type": "pure", "level": "中等", "stem": "某地 2024 年财政收入 268 亿元，2025 年为 321 亿元，2025 年增长率约为（　）", "options": ["16.5%", "19.8%", "23.1%", "26.4%"], "answer": ["B"], "method": "增长率 =（现期−基期）÷基期 =（321−268）÷268 = 53÷268。53÷268≈0.198（把 268 看成 265，53÷265≈20%）。", "explain": "(321−268)/268=53/268≈19.8%，选 B。", "tip": "分母永远是“基期（去年）”而不是现期，这是最常见的错。", "hard": "53÷321≈16.5% 就是错把分母当成现期，恰好对应 A，别上当。"}, {"type": "pure", "level": "中等", "stem": "某市 2025 年快递业务量 4.86 亿件，同比增长 8%，则比上年约增加（　）亿件", "options": ["0.30", "0.36", "0.42", "0.48"], "answer": ["B"], "method": "增长量 = 现期÷(1+r) × r。4.86÷1.08 = 4.5；4.5×8% = 0.36。", "explain": "4.86÷1.08=4.5，再乘 8% 得 0.36 亿件，选 B。", "tip": "增长量要用“基期×增长率”，不能拿现期直接乘 8%（4.86×8%=0.389，会滑向干扰项）。", "hard": "4.86×8%≈0.39 是常见错算，对应 C 附近。"}, {"type": "pure", "level": "中等", "stem": "某指标 2023 年比 2022 年增长 10%，2024 年比 2023 年增长 20%，则 2024 年比 2022 年增长约（　）", "options": ["28%", "30%", "32%", "34%"], "answer": ["C"], "method": "间隔增长率 =（1+r₁)(1+r₂)−1 = 1.1×1.2−1 = 1.32−1 = 0.32。", "explain": "1.1×1.2=1.32，即增长 32%，选 C。", "tip": "两段增速不能直接相加（10%+20%=30% 是错的），必须“乘起来”。", "hard": "30% 是“直接相加”的错算，是最常见干扰项。"}, {"type": "pure", "level": "基础", "stem": "某市 GDP 由 2019 年的 520 亿元增至 2024 年的 895 亿元，年均增长量约为（　）亿元", "options": ["65", "70", "75", "80"], "answer": ["C"], "method": "年均增长量 =（末期−初期）÷年数差 =（895−520）÷(2024−2019) = 375÷5 = 75。", "explain": "375÷5=75 亿元，选 C。", "tip": "年数差用“末年−首年”（5 年），不是年份个数（2024−2019 有 6 个年份）。", "hard": "375÷6≈62.5 是错用“年份个数”的典型。"}, {"type": "pure", "level": "进阶", "stem": "某地 GDP 由 2020 年的 100 亿元增至 2024 年的 146.4 亿元，年均增长率约为（　）", "options": ["8%", "10%", "12%", "14%"], "answer": ["B"], "method": "年均增长率 =(末期/初期)^(1/n)−1。146.4/100=1.464，n=4。用熟值：1.1⁴=1.4641≈1.464。", "explain": "1.1⁴=1.4641，故年均增长约 10%，选 B。", "tip": "记牢 1.1²=1.21、1.1³=1.331、1.1⁴=1.4641，很多题可直接“认出来”。", "hard": "用“总增速÷年数”（46.4%/4≈11.6%）会滑向 12%。"}, {"type": "pure", "level": "进阶", "stem": "某部分增速为 15%，整体增速为 10%，则该部分占整体的比重与上年相比（　）", "options": ["上升，且变化不足 5 个百分点", "上升，且变化超过 5 个百分点", "下降，且变化不足 5 个百分点", "下降，且变化超过 5 个百分点"], "answer": ["A"], "method": "两期比重差：部分增速 a > 整体增速 b → 比重上升；变化幅度一定小于 |a−b| = 5 个百分点。", "explain": "a=15%>b=10%，比重上升；变化量小于 5 个百分点，选 A。", "tip": "口诀：部分比整体快，比重就上升；且升降幅度必小于增速之差。", "hard": "“超过 5 个百分点”永远错——这是个可直接秒杀的结论。"}, {"type": "pure", "level": "基础", "stem": "3840 约是 1280 的（　）倍", "options": ["2.5", "2.8", "3", "3.2"], "answer": ["C"], "method": "3840÷1280 = 3（1280×3=3840）。", "explain": "1280×3=3840，故是 3 倍，选 C。", "tip": "倍数问题先看能否“整数倍”，一眼可定。", "hard": "3.2 是把 3840 看成 4096 之类的错算。"}, {"type": "pure", "level": "基础", "stem": "某市 2025 年完成投资 1260 亿元，涉及项目 350 个，平均每个项目投资约（　）亿元", "options": ["3.2", "3.6", "4.0", "4.4"], "answer": ["B"], "method": "平均数 = 总量÷个数 = 1260÷350。350×3.6=1260。", "explain": "1260÷350=3.6 亿元，选 B。", "tip": "350×3=1050，还差 210，210÷350=0.6，所以是 3.6。", "hard": "4.0 是 1400÷350 的错算。"}, {"type": "pure", "level": "基础", "stem": "3648 的 1/7 约为（　）", "options": ["501", "521", "541", "561"], "answer": ["B"], "method": "化分数：1/7≈14.3%，3648÷7≈521.1。", "explain": "3648÷7≈521，选 B。", "tip": "记牢 1/7≈14.3%、1/8=12.5%、1/9≈11.1%。", "hard": "501 是 3507÷7 的错算。"}, {"type": "pure", "level": "基础", "stem": "某厂上半年产值 480 万元，下半年比上半年多 25%，全年产值约为（　）万元", "options": ["1020", "1080", "1140", "1200"], "answer": ["B"], "method": "下半年 = 480×(1+25%) = 600；全年 = 480+600 = 1080。", "explain": "480+600=1080 万元，选 B。", "tip": "“多 25%”是乘 1.25，不是加 25 万。", "hard": "1020 是漏算了下半年的高出部分。"}, {"type": "applied", "level": "中等", "data": "【材料】2025 年某省规模以上工业增加值 1.86 万亿元，同比增长 6.2%。", "stem": "该省 2024 年规模以上工业增加值约为（　）万亿元", "options": ["1.68", "1.75", "1.82", "1.89"], "answer": ["B"], "method": "基期 = 现期÷(1+r) = 1.86÷1.062。1.86÷1.06≈1.755。", "explain": "1.86÷1.062≈1.75 万亿元，选 B。", "tip": "“已知现期和增速，求基期”用除法，别用 1.86×(1−6.2%)（那会偏小）。", "hard": "1.86×0.938≈1.745 与正确答案相近，但严格说是错式；正确解更稳。"}, {"type": "applied", "level": "基础", "data": "【材料】某市 2025 年接待游客 3800 万人次，比 2020 年增长 90%。", "stem": "该市 2020 年接待游客约为（　）万人次", "options": ["1900", "2000", "2100", "2200"], "answer": ["B"], "method": "基期 = 现期÷(1+r) = 3800÷1.9 = 2000。", "explain": "3800÷1.9=2000 万人次，选 B。", "tip": "“比……增长 90%”即现期是基期的 1.9 倍。", "hard": "3800×0.9=3420 是把“增长率”当“现期占比”的错算。"}, {"type": "applied", "level": "基础", "data": "【材料】2025 年某企业营业收入 5.4 亿元，净利润 0.648 亿元。", "stem": "该企业 2025 年净利率约为（　）", "options": ["10%", "11%", "12%", "13%"], "answer": ["C"], "method": "净利率 = 净利润÷营业收入 = 0.648÷5.4。5.4×0.12=0.648。", "explain": "0.648÷5.4=0.12=12%，选 C。", "tip": "“率”类问题：部分÷整体，注意分子分母别颠倒。", "hard": "5.4÷0.648≈8.33 是分子分母颠倒的错算。"}, {"type": "applied", "level": "基础", "data": "【材料】2025 年某地区 A 项收入 320 亿元，B 项收入 480 亿元。", "stem": "A 项收入占 A、B 两项合计的比重约为（　）", "options": ["36%", "40%", "44%", "48%"], "answer": ["B"], "method": "比重 = A÷(A+B) = 320÷800 = 0.4。", "explain": "320÷(320+480)=320÷800=40%，选 B。", "tip": "“占……合计的比重”，分母是合计，不是另一项。", "hard": "320÷480≈66.7% 是只拿 B 当分母的错算。"}, {"type": "applied", "level": "中等", "data": "【材料】2025 年某国货物出口 2.4 万亿元，进口 1.9 万亿元。", "stem": "该国 2025 年货物贸易顺差占出口额的比重约为（　）", "options": ["18.5%", "20.8%", "23.2%", "25.6%"], "answer": ["B"], "method": "顺差 = 出口−进口 = 2.4−1.9 = 0.5；占出口比重 = 0.5÷2.4≈20.8%。", "explain": "0.5÷2.4≈0.208=20.8%，选 B。", "tip": "先算顺差（0.5），再除以“出口额”2.4，别除以进口额。", "hard": "0.5÷1.9≈26.3% 是把分母当成进口额的错算。"}, {"type": "applied", "level": "中等", "data": "【材料】某地 2025 年建成 5G 基站 12.5 万个，2020 年为 4 万个。", "stem": "2025 年该地基站数量比 2020 年增长约（　）", "options": ["180%", "212.5%", "240%", "280%"], "answer": ["B"], "method": "增长率 =（现期−基期）÷基期 =（12.5−4）÷4 = 8.5÷4 = 2.125。", "explain": "8.5÷4=2.125=212.5%，选 B。", "tip": "“增长百分之几”是相对基期，不是相对现期。", "hard": "8.5÷12.5=68% 是把分母当成现期的错算。"}, {"type": "applied", "level": "中等", "data": "【材料】2025 年某市一般公共预算收入 920 亿元，其中税收收入 736 亿元，财政总收入同比增长 4%。", "stem": "2025 年该市税收收入占一般公共预算收入的比重约为（　）", "options": ["72%", "76%", "80%", "84%"], "answer": ["C"], "method": "比重 = 736÷920。920×0.8 = 736。", "explain": "736÷920=0.8=80%，选 C。", "tip": "同比增长 4% 是干扰信息；求“占比”与增速无关。", "hard": "若误用 (1+4%) 调整分子或分母，就会滑向 76% 或 84%。"}, {"type": "applied", "level": "进阶", "data": "【材料】2025 年前三季度某省社会消费品零售总额 1.2 万亿元，同比增长 5%；第四季度 0.5 万亿元，同比增长 8%。", "stem": "该省 2025 年全年社会消费品零售总额同比增速约为（　）", "options": ["5.0%", "5.9%", "6.5%", "7.0%"], "answer": ["B"], "method": "基期总量 = 1.2÷1.05 + 0.5÷1.08 ≈ 1.1429 + 0.4630 = 1.6059；现期 = 1.7。增速 = 1.7÷1.6059 − 1 ≈ 5.86%。", "explain": "1.7÷1.6059≈1.0586，即增长约 5.9%，选 B。", "tip": "混合增速不能简单取平均（(5%+8%)/2=6.5% 是错的），要在基期口径下加权。", "hard": "6.5% 恰是“直接平均”的错算，对应 C，是本题最大陷阱。"}]}, {"set": 7, "date": "2026-10-04", "session": "day", "title": "资料分析速算训练 · 第 7 批（首数直除 / 估算与范围 / 增长率与增长量 / 间隔增长率 / 年均增长量 / 年均增长率 / 两期比重差 / 倍数与平均数 / 化分数 / 百分数加减）", "difficulty": "基础+中等", "items": [{"type": "pure", "level": "基础", "stem": "6384 ÷ 1.28 ≈（　）", "options": ["4780", "4988", "5190", "5390"], "answer": ["B"], "method": "首数直除：1.28 × 5000 = 6400，略大于 6384，故商略小于 5000。再试 1.28×4988=6384.6，几乎相等。", "explain": "1.28×4988≈6384，商约 4988，选 B。", "tip": "先定“整数档”（5000），再往回收一点点，不必精确长除。", "hard": "5190 是把除数看成 1.23 之类算出的，注意除数别抄错。"}, {"type": "pure", "level": "基础", "stem": "8426 ÷ 0.917 ≈（　）", "options": ["8790", "8980", "9189", "9390"], "answer": ["C"], "method": "0.917 × 9200 = 8436.4，略大于 8426，故商略小于 9200，约 9189。", "explain": "0.917×9189≈8427，选 C。", "tip": "除以小于 1 的数，结果比原数大，可先排除 8790 以下的项。", "hard": "8790 是把结果算小了（误按 ÷1.0 估），是本题最大干扰项。"}, {"type": "pure", "level": "中等", "stem": "某市 2025 年 GDP 为 4270 亿元，2024 年为 3850 亿元，2025 年 GDP 增长率约为（　）", "options": ["8.9%", "10.9%", "12.9%", "14.9%"], "answer": ["B"], "method": "增长率 =（现期−基期）÷基期 =（4270−3850）÷3850 = 420÷3850。420÷3850≈0.109（把 3850 看成 3850，420÷3850≈10.9%）。", "explain": "(4270−3850)/3850=420/3850≈10.9%，选 B。", "tip": "分母永远是“基期（去年）”3850，而不是现期 4270，这是最常见的错。", "hard": "420÷4270≈9.8% 就是错把分母当成现期，恰好接近 A，别上当。"}, {"type": "pure", "level": "中等", "stem": "某县 2025 年电商交易额 6.72 亿元，同比增长 12%，则比上年约增加（　）亿元", "options": ["0.60", "0.72", "0.81", "0.90"], "answer": ["B"], "method": "增长量 = 现期÷(1+r) × r。6.72÷1.12 = 6.0；6.0×12% = 0.72。", "explain": "6.72÷1.12=6.0，再乘 12% 得 0.72 亿元，选 B。", "tip": "增长量要用“基期×增长率”，不能拿现期直接乘 12%（6.72×12%=0.806）。", "hard": "6.72×12%≈0.81 是常见错算，恰好对应 C，注意避坑。"}, {"type": "pure", "level": "中等", "stem": "某指标 2023 年比 2022 年增长 15%，2024 年比 2023 年增长 20%，则 2024 年比 2022 年增长约（　）", "options": ["35%", "38%", "41%", "44%"], "answer": ["B"], "method": "间隔增长率 =（1+r₁)(1+r₂)−1 = 1.15×1.20−1 = 1.38−1 = 0.38。", "explain": "1.15×1.20=1.38，即增长 38%，选 B。", "tip": "两段增速不能直接相加（15%+20%=35% 是错的），必须“乘起来”。", "hard": "35% 是“直接相加”的错算，是最常见干扰项，对应 A。"}, {"type": "pure", "level": "基础", "stem": "某地 GDP 由 2020 年的 380 亿元增至 2025 年的 680 亿元，年均增长量约为（　）亿元", "options": ["50", "60", "65", "75"], "answer": ["B"], "method": "年均增长量 =（末期−初期）÷年数差 =（680−380）÷(2025−2020) = 300÷5 = 60。", "explain": "300÷5=60 亿元，选 B。", "tip": "年数差用“末年−首年”（5 年），不是年份个数（2020—2025 有 6 个年份）。", "hard": "300÷6=50 是错用“年份个数”的典型，恰好对应 A。"}, {"type": "pure", "level": "进阶", "stem": "某市 GDP 由 2020 年的 100 亿元增至 2023 年的 172.8 亿元，年均增长率约为（　）", "options": ["15%", "18%", "20%", "22%"], "answer": ["C"], "method": "年均增长率 =(末期/初期)^(1/n)−1。172.8/100=1.728，n=3。用熟值：1.2³=1.728。", "explain": "1.2³=1.728，故年均增长约 20%，选 C。", "tip": "记牢 1.2²=1.44、1.2³=1.728、1.1⁴=1.4641，很多题可直接“认出来”。", "hard": "用“总增速÷年数”（72.8%/3≈24.3%）会滑向 22% 甚至更高，别用简单平均。"}, {"type": "pure", "level": "进阶", "stem": "某部分增速为 20%，整体增速为 8%，则该部分占整体的比重与上年相比（　）", "options": ["上升，且变化不足 12 个百分点", "上升，且变化超过 12 个百分点", "下降，且变化不足 12 个百分点", "下降，且变化超过 12 个百分点"], "answer": ["A"], "method": "两期比重差：部分增速 a > 整体增速 b → 比重上升；变化幅度一定小于 |a−b| = 12 个百分点。", "explain": "a=20%>b=8%，比重上升；变化量小于 12 个百分点，选 A。", "tip": "口诀：部分比整体快，比重就上升；且升降幅度必小于增速之差。", "hard": "“超过 12 个百分点”永远错——这是可直接秒杀的结论。"}, {"type": "pure", "level": "基础", "stem": "5820 约是 1455 的（　）倍", "options": ["3.5", "4", "4.5", "5"], "answer": ["B"], "method": "5820÷1455 = 4（1455×4=5820）。", "explain": "1455×4=5820，故是 4 倍，选 B。", "tip": "倍数问题先看能否“整数倍”，一眼可定。", "hard": "4.5 是把 5820 看成 6548 之类的错算。"}, {"type": "pure", "level": "基础", "stem": "某市 2025 年完成进出口 3360 亿元，涉及企业 840 家，平均每家企业进出口约（　）亿元", "options": ["3.2", "3.6", "4.0", "4.4"], "answer": ["C"], "method": "平均数 = 总量÷个数 = 3360÷840。840×4=3360。", "explain": "3360÷840=4.0 亿元，选 C。", "tip": "840×3=2520，还差 840，840÷840=1，所以是 4。", "hard": "4.4 是 3696÷840 的错算。"}, {"type": "pure", "level": "基础", "stem": "4032 的 1/8 约为（　）", "options": ["404", "454", "504", "554"], "answer": ["C"], "method": "化分数：1/8 = 12.5%，4032÷8 = 504。", "explain": "4032÷8=504，选 C。", "tip": "记牢 1/8=12.5%、1/7≈14.3%、1/9≈11.1%，能秒算。", "hard": "454 是 3632÷8 的错算，别把被除数看错。"}, {"type": "pure", "level": "基础", "stem": "某厂一季度产值 260 万元，二季度比一季度少 15%，上半年产值约为（　）万元", "options": ["441", "461", "481", "501"], "answer": ["C"], "method": "二季度 = 260×(1−15%) = 221；上半年 = 260+221 = 481。", "explain": "260+221=481 万元，选 C。", "tip": "“少 15%”是乘 0.85，不是减 15 万。", "hard": "441 是漏加了二季度那部分（只算了 260×1.7 之类的错式）。"}, {"type": "applied", "level": "中等", "data": "【材料】2025 年某市接待游客 4500 万人次，同比增长 20%。", "stem": "该市 2024 年接待游客约为（　）万人次", "options": ["3600", "3750", "3900", "4050"], "answer": ["B"], "method": "基期 = 现期÷(1+r) = 4500÷1.2 = 3750。", "explain": "4500÷1.2=3750 万人次，选 B。", "tip": "“同比增长 20%”即现期是基期的 1.2 倍，求基期用除法。", "hard": "4500×(1−20%)=3600 是错用减法，恰好对应 A，是本题最大陷阱。"}, {"type": "applied", "level": "基础", "data": "【材料】某市 2025 年快递业务收入 960 亿元，比 2020 年增长 60%。", "stem": "该市 2020 年快递业务收入约为（　）亿元", "options": ["540", "570", "600", "630"], "answer": ["C"], "method": "基期 = 现期÷(1+r) = 960÷1.6 = 600。", "explain": "960÷1.6=600 亿元，选 C。", "tip": "“比 2020 年增长 60%”即现期是基期的 1.6 倍。", "hard": "960×0.6=576 是把“增长率”当“现期占比”的错算，落在 B 附近。"}, {"type": "applied", "level": "基础", "data": "【材料】2025 年某企业营业收入 7.2 亿元，净利润 0.9 亿元。", "stem": "该企业 2025 年净利率约为（　）", "options": ["10.0%", "11.5%", "12.5%", "13.5%"], "answer": ["C"], "method": "净利率 = 净利润÷营业收入 = 0.9÷7.2。7.2×0.125=0.9。", "explain": "0.9÷7.2=0.125=12.5%，选 C。", "tip": "“率”类问题：部分÷整体，分子分母别颠倒。", "hard": "7.2÷0.9=8（倍）是分子分母颠倒的错算，别当成率。"}, {"type": "applied", "level": "基础", "data": "【材料】2025 年某地区 A 项收入 360 亿元，B 项收入 540 亿元。", "stem": "A 项收入占 A、B 两项合计的比重约为（　）", "options": ["33%", "36%", "40%", "44%"], "answer": ["C"], "method": "比重 = A÷(A+B) = 360÷900 = 0.4。", "explain": "360÷(360+540)=360÷900=40%，选 C。", "tip": "“占……合计的比重”，分母是合计，不是另一项。", "hard": "360÷540≈66.7% 是只拿 B 当分母的错算。"}, {"type": "applied", "level": "中等", "data": "【材料】2025 年某国货物出口 3.2 万亿美元，进口 2.6 万亿美元。", "stem": "该国 2025 年货物贸易顺差占出口额的比重约为（　）", "options": ["15.6%", "18.8%", "20.2%", "23.1%"], "answer": ["B"], "method": "顺差 = 出口−进口 = 3.2−2.6 = 0.6；占出口比重 = 0.6÷3.2≈18.75%。", "explain": "0.6÷3.2≈0.188=18.8%，选 B。", "tip": "先算顺差（0.6），再除以“出口额”3.2，别除以进口额。", "hard": "0.6÷2.6≈23.1% 是把分母当成进口额的错算，对应 D。"}, {"type": "applied", "level": "中等", "data": "【材料】某地 2025 年建成 5G 基站 18.4 万个，2020 年为 6.4 万个。", "stem": "2025 年该地基站数量比 2020 年增长约（　）", "options": ["150%", "167.5%", "187.5%", "210%"], "answer": ["C"], "method": "增长率 =（现期−基期）÷基期 =（18.4−6.4）÷6.4 = 12÷6.4 = 1.875。", "explain": "12÷6.4=1.875=187.5%，选 C。", "tip": "“增长百分之几”是相对基期，不是相对现期。", "hard": "12÷18.4≈65.2% 是把分母当成现期的错算；167.5% 是分子分母都用错的干扰项。"}, {"type": "applied", "level": "中等", "data": "【材料】2025 年某市一般公共预算收入 850 亿元，其中税收收入 680 亿元，财政总收入同比增长 5%。", "stem": "2025 年该市税收收入占一般公共预算收入的比重约为（　）", "options": ["76%", "80%", "84%", "88%"], "answer": ["B"], "method": "比重 = 680÷850。850×0.8 = 680。", "explain": "680÷850=0.8=80%，选 B。", "tip": "同比增长 5% 是干扰信息；求“占比”与增速无关。", "hard": "若误用 (1+5%) 调整分子或分母，就会滑向 76% 或 84%。"}, {"type": "applied", "level": "进阶", "data": "【材料】2025 年前三季度某省社会消费品零售总额 1.5 万亿元，同比增长 4%；第四季度 0.6 万亿元，同比增长 9%。", "stem": "该省 2025 年全年社会消费品零售总额同比增速约为（　）", "options": ["4.5%", "5.4%", "6.5%", "7.0%"], "answer": ["B"], "method": "基期总量 = 1.5÷1.04 + 0.6÷1.09 ≈ 1.4423 + 0.5505 = 1.9928；现期 = 2.1。增速 = 2.1÷1.9928 − 1 ≈ 5.4%。", "explain": "2.1÷1.9928≈1.054，即增长约 5.4%，选 B。", "tip": "混合增速不能简单取平均（(4%+9%)/2=6.5% 是错的），要在基期口径下加权。", "hard": "6.5% 恰是“直接平均”的错算，对应 C，是本题最大陷阱。"}]}, {"set": 8, "date": "2026-10-05", "session": "day", "title": "资料分析速算训练 · 第 8 批（首数直除 / 增长率与增长量 / 间隔增长率 / 年均增长 / 两期比重差 / 倍数与平均数 / 化分数）", "difficulty": "基础+中等", "items": [{"type": "pure", "level": "基础", "stem": "4.27 ÷ 1.18 的商约为：", "options": ["3.0", "3.3", "3.6", "3.9"], "answer": ["C"], "method": "①先估：4.27÷1.18≈4.3÷1.2≈3.58；②用分母夹：1.18×3＝3.54，1.18×3.6＝4.248，1.18×3.7＝4.366；③被除数 4.27 落在 3.6 与 3.7 之间、更靠 3.6。", "explain": "1.18×3.6＝4.248，4.27－4.248＝0.022，0.022÷1.18≈0.019，故商≈3.619，取 3.6，选 C。", "tip": "别一上来就硬除；先确定商的整数部分（3），再用 3.6 和 3.7 夹住被除数。", "hard": "3.3 与 3.9 是常见的“估歪”结果，用分母乘 3 与 4 先定位区间可避开。"}, {"type": "pure", "level": "基础", "stem": "某指标由 250 增长到 320，增长率约为：", "options": ["28.0%", "21.9%", "12.5%", "35.2%"], "answer": ["A"], "method": "增长率＝（现期－基期）÷基期＝（320－250）÷250＝70÷250。", "explain": "70÷250＝0.28＝28.0%，选 A。", "tip": "分母一定要用“基期”（250），别用现期 320，否则会算成 21.9%（干扰项 B）。", "hard": "21.9% 正是“除以现期”的错算结果，看到选项里有它就说明命题人埋了分母坑。"}, {"type": "pure", "level": "基础", "stem": "某指标 2025 年为 480，同比增长 12.5%，则比上年增加约多少？", "options": ["60", "53", "48", "42"], "answer": ["B"], "method": "增长量＝基期×增长率＝[现期÷(1＋增长率)]×增长率。12.5%＝1/8，用“现期÷(n＋1)”速算：n＝8，增长量＝480÷9。", "explain": "480÷9≈53.3，取 53，选 B。（严格算：基期＝480÷1.125≈426.7，增长量＝426.7×0.125≈53.3。）", "tip": "增长率化分数后再算：12.5%＝1/8，增长量＝现期÷9，比先求基期再乘更快。", "hard": "干扰项 60＝480×12.5%（用现期当基期）；48＝480÷10（把 n＋1 当成 10）。"}, {"type": "pure", "level": "进阶", "stem": "某地 GDP 2024 年比 2023 年增长 8%，2025 年比 2024 年增长 5%，则 2025 年比 2023 年增长约：", "options": ["13.0%", "13.4%", "12.6%", "14.0%"], "answer": ["B"], "method": "间隔（复合）增长率 r＝r₁＋r₂＋r₁×r₂。", "explain": "r＝8%＋5%＋8%×5%＝13%＋0.4%＝13.4%，选 B。", "tip": "不能把两段增长率简单相加（8%＋5%＝13%），漏掉乘积项 r₁r₂＝0.4%。", "hard": "13.0%（干扰 A）就是漏乘的错算；增长率越大，漏乘越吃亏。"}, {"type": "pure", "level": "基础", "stem": "某指标 2019 年为 120，2024 年为 220，则 2019—2024 年的年均增长量为：", "options": ["16.7", "25", "20", "50"], "answer": ["C"], "method": "年均增长量＝（末期值－初期值）÷年份差。", "explain": "（220－120）÷（2024－2019）＝100÷5＝20，选 C。", "tip": "年份差＝2024－2019＝5，别算成 4（年份个数）或 6。", "hard": "干扰项 25＝100÷4（把年份差当年份个数），16.7＝100÷6，都是日期口径陷阱。"}, {"type": "pure", "level": "进阶", "stem": "某指标从 100 增长到 144，历时 4 年，年均增长率约为：", "options": ["9.5%", "11.0%", "12.5%", "44.0%"], "answer": ["A"], "method": "设年均增长率为 r，则 (1＋r)⁴＝144÷100＝1.44，即 1＋r＝1.44^(1/4)（开四次方）。", "explain": "1.44^(1/4)≈1.095，故 r≈9.5%，选 A。", "tip": "年均增长率要开方，不是 44%÷4＝11%；也别把总增长率直接除以年数。", "hard": "11.0%（＝44%÷4）是最典型错算；开方类题目的错项往往就卡在“除以年数”这一步。"}, {"type": "pure", "level": "进阶", "stem": "2025 年第三产业占 GDP 的比重比上年提高约多少个百分点？", "options": ["1.8", "1.2", "2.4", "3.0"], "answer": ["A"], "method": "两期比重差≈现期比重×(部分增长率－整体增长率)÷(1＋部分增长率)。", "explain": "现期比重＝2600÷5000＝52%，代入：52%×(14%－10%)÷(1＋14%)＝52%×4%÷1.14≈1.82%，选 A。（精确算：上年比重＝(2600÷1.14)÷(5000÷1.1)≈50.2%，差≈1.8 个百分点，一致。）", "tip": "只有“部分增速＞整体增速”，比重才上升；先看差值正负再定加减。", "hard": "干扰项 2.0 是把 52%×4%＝2.08% 直接当选、忘了除以 (1＋14%)。"}, {"type": "pure", "level": "基础", "stem": "A 为 3.6，B 为 0.9，则 A 是 B 的多少倍？", "options": ["2.7", "3.3", "4.0", "4.5"], "answer": ["C"], "method": "“A 是 B 的几倍”＝A÷B。", "explain": "3.6÷0.9＝4.0，选 C。", "tip": "区分“是几倍”与“多几倍”：是 4 倍，多 3 倍。", "hard": "干扰项 4.5＝3.6÷0.8（看错除数），要盯紧 B 的值。"}, {"type": "pure", "level": "基础", "stem": "某企业 2025 年产值 8.4 亿元，共有员工 3200 人，人均产值约为：", "options": ["24.5 万元", "28.1 万元", "31.2 万元", "26.3 万元"], "answer": ["D"], "method": "人均产值＝总产值÷员工数，注意单位换算：8.4 亿元＝84000 万元。", "explain": "84000÷3200＝26.25≈26.3 万元，选 D。", "tip": "亿元换算成万元要乘 10000，单位不换会差出量级。", "hard": "选项都在 25~32 万元之间，恰是“忘了单位换算”的常见区间，务必先统一单位。"}, {"type": "pure", "level": "基础", "stem": "1780 × 14.3% 的积约为：", "options": ["240", "265", "254", "278"], "answer": ["C"], "method": "化分数：14.3%≈1/7，所以原式≈1780÷7。", "explain": "1780÷7≈254.3，取 254，选 C。", "tip": "记住常用化分数：1/7≈14.3%、1/6≈16.7%、1/8＝12.5%、1/9≈11.1%。", "hard": "14.3% 若换成 1/6（16.7%）会得到 297，明显偏大；换分数要换对。"}, {"type": "pure", "level": "进阶", "stem": "某值先增长 15%，再下降 10%，最终比原值变化约：", "options": ["＋3.5%", "＋5.0%", "－5.0%", "＋25.0%"], "answer": ["A"], "method": "复合计算：1×(1＋15%)×(1－10%)＝1×1.15×0.90。", "explain": "1.15×0.90＝1.035，即最终比原值高 3.5%，选 A。", "tip": "“先涨后跌”不能直接相减（15%－10%＝5%），必须乘起来。", "hard": "干扰项 ＋5.0% 正是直接相减的结果；涨跌幅接近时，差得不多但方向可能相反。"}, {"type": "pure", "level": "基础", "stem": "3.14 × 6.28 的积约为：", "options": ["15.8", "17.5", "19.7", "21.2"], "answer": ["C"], "method": "估算夹逼：3.14×6＝18.84，3.14×6.3≈19.78。", "explain": "3.14×6.28≈19.72，取 19.7，选 C。", "tip": "先用整数部分卡范围，再取中间值，比硬算快。", "hard": "17.5 是“把 6.28 当成 5.6”的错算，21.2 是“当成 6.8”，都要靠夹逼排除。"}, {"type": "applied", "level": "基础", "stem": "2024 年该市规模以上工业增加值约为多少亿元？", "data": "【材料】2025 年某市规模以上工业增加值 2450 亿元，比上年增长 9.2%。", "options": ["2244", "2210", "2270", "2300"], "answer": ["A"], "method": "基期量＝现期量÷(1＋增长率)。", "explain": "2450÷(1＋9.2%)＝2450÷1.092≈2243.6，取 2244，选 A。", "tip": "求基期用“除以 (1＋增长率)”，别用“现期×(1－9.2%)”，那是错的。", "hard": "2450×(1－9.2%)≈2225，会滑向 2210 附近；记住求基期只能除不能减。"}, {"type": "applied", "level": "基础", "stem": "2025 年该省游客人均旅游消费约为多少元？", "data": "【材料】2025 年某省接待游客 3.6 亿人次，同比增长 18.5%；实现旅游收入 4200 亿元，同比增长 22.4%。", "options": ["1050", "1280", "980", "1167"], "answer": ["D"], "method": "人均消费＝旅游收入÷游客人次，注意单位：亿元÷亿人次＝元/人次。", "explain": "4200÷3.6≈1166.7，取 1167，选 D。", "tip": "两个量都以“亿”为单位，可先约掉“亿”再算，避免单位出错。", "hard": "用上年数据反算会跑偏；题目问的是“2025 年人均消费”，直接取现期相除。"}, {"type": "applied", "level": "基础", "stem": "2024 年 1—9 月该公司营业收入约为多少亿元？", "data": "【材料】2025 年 1—9 月，某公司营业收入 186 亿元，同比增长 12%；其中第三季度营业收入 70 亿元，同比增长 16%。", "options": ["156", "166", "164", "178"], "answer": ["B"], "method": "本问的“1—9 月”整体只对应总量 186 亿元、增速 12%，用基期公式即可。", "explain": "186÷1.12≈166.1，取 166，选 B。", "tip": "“其中第三季度……”是干扰信息，与本问无关；先看清问的是“1—9 月”。", "hard": "用 16% 或把 70 亿元混进来算，都会滑向错误选项；要锁定“总量＋对应增速”。"}, {"type": "applied", "level": "基础", "stem": "2025 年某县农村居民人均可支配收入比 2024 年增长约百分之几？", "data": "【材料】2024 年某县农村居民人均可支配收入 18500 元，2025 年为 20800 元。", "options": ["10.8%", "11.1%", "12.4%", "13.5%"], "answer": ["C"], "method": "增长率＝(现期－基期)÷基期。", "explain": "(20800－18500)÷18500＝2300÷18500≈12.4%，选 C。", "tip": "分母用基期 18500，别除以 20800。", "hard": "2300÷20800≈11.1%（干扰 B）就是“除以现期”的错算，要看清分母。"}, {"type": "applied", "level": "进阶", "stem": "2025 年该地区进出口总额比上年增长约百分之几？", "data": "【材料】某地区 2025 年货物进口额 3200 亿美元，同比下降 8%；出口额 4500 亿美元，同比增长 6%。", "options": ["－0.3%", "＋1.0%", "－1.5%", "＋2.5%"], "answer": ["A"], "method": "先分别求上年进出口额，再加总求增长率。上年进口＝3200÷0.92，上年出口＝4500÷1.06。", "explain": "上年进口≈3478.3、上年出口≈4245.3，合计≈7723.6；今年合计＝3200＋4500＝7700。(7700－7723.6)÷7723.6≈－0.31%，选 A。", "tip": "进出口一增一减，要先把基期分别还原再加总，不能把 ＋6% 与 －8% 直接平均。", "hard": "两段方向相反时，总额增速可能很小甚至为负，容易被“大概在中间”的直觉带偏。"}, {"type": "applied", "level": "进阶", "stem": "2019—2025 年该市快递业务量的年均增长率约为多少？", "data": "【材料】2025 年某市快递业务量 12.6 亿件，同比增长 25%；2019 年为 5.6 亿件。", "options": ["12.0%", "18.0%", "14.5%", "22.5%"], "answer": ["C"], "method": "倍数＝12.6÷5.6＝2.25，年份差＝2025－2019＝6，令 (1＋r)⁶＝2.25，开六次方。", "explain": "1＋r＝2.25^(1/6)≈1.145，故 r≈14.5%，选 C。", "tip": "只用到初期、末期值，中间的 25% 是干扰；年均增长率一定要开方。", "hard": "6 年翻 2.25 倍，年均约 14.5%；若误除以年数会得到 20% 以上，滑向 22.5%。"}, {"type": "applied", "level": "进阶", "stem": "2024 年该省规模以上工业总产值约为多少亿元？", "data": "【材料】2025 年某省高新技术产业产值 5600 亿元，占规模以上工业总产值的 32%，同比增长 12%；2024 年该比重为 29%。", "options": ["17500", "17241", "17000", "16800"], "answer": ["B"], "method": "①先求 2024 年高新技术产业产值：5600÷1.12；②再用 2024 年的比重 29% 反推总产值。", "explain": "5600÷1.12＝5000；5000÷0.29≈17241，选 B。", "tip": "反推总产值要用“对应年份的比重”：2024 年产值配 29%，不能拿 2025 年的 32% 去除 2024 年的产值。", "hard": "5600÷0.32＝17500（干扰 A）是“用现期产值除现期比重”，错在年份错配。"}, {"type": "applied", "level": "基础", "stem": "2025 年该市社会消费品零售总额约为多少亿元？", "data": "【材料】2025 年某市限额以上单位网上零售额 860 亿元，占社会消费品零售总额的 21.5%；2024 年网上零售额为 700 亿元，占比 19.2%。", "options": ["4000", "4050", "3900", "3800"], "answer": ["A"], "method": "整体量＝部分量÷部分所占比重，取现期数据：860÷21.5%。", "explain": "860÷0.215＝4000，选 A。", "tip": "用现期（2025 年）的网上零售额配现期比重 21.5%，不要误用 2024 年的 19.2%。", "hard": "860÷0.192≈4479（不在选项）会把人绕晕；先锁定“年份—数据”对应关系再算。"}]}, {"set": 9, "date": "2026-10-06", "session": "day", "title": "资料分析速算训练 · 第 9 批（首数直除 / 估算与范围 / 增长率与增长量 / 间隔增长率 / 年均增长量 / 年均增长率 / 两期比重差 / 倍数与平均数 / 化分数 / 百分数加减）", "difficulty": "基础+中等", "items": [{"type": "pure", "level": "基础", "stem": "6.52 ÷ 1.24 的商约为：", "options": ["4.8", "5.0", "5.3", "5.6"], "answer": ["C"], "method": "①首数直除：6.52÷1.24≈6.5÷1.25＝5.2，先定整数部分为 5；②用分母夹：1.24×5.2＝6.448，1.24×5.3＝6.572；③被除数 6.52 落在 5.2 与 5.3 之间、更靠 5.3。", "explain": "1.24×5.2＝6.448，6.52−6.448＝0.072，0.072÷1.24≈0.058，故商≈5.258，取 5.3，选 C。", "tip": "别一上来就硬除；先定整数部分（5），再用 5.2 和 5.3 夹住被除数。", "hard": "4.8、5.0、5.6 都是常见的“估歪”结果，用分母乘 5 与 6 先定位区间可避开。"}, {"type": "pure", "level": "基础", "stem": "243 × 37.5% 的值约为：", "options": ["81", "91", "101", "111"], "answer": ["B"], "method": "①化分数：37.5%＝3/8；②243×3＝729；③729÷8≈91.1。", "explain": "37.5%＝3/8，243×3÷8＝729÷8≈91.1，最接近 91，选 B。", "tip": "记住常用化分数：37.5%＝3/8、12.5%＝1/8、62.5%＝5/8，比按小数相乘快得多。", "hard": "把 37.5% 记成 3/8 是关键；若误记成 3/7 会算到约 104，滑向干扰项。"}, {"type": "pure", "level": "基础", "stem": "某量从 480 增长到 552，增长率约为：", "options": ["12%", "13%", "15%", "18%"], "answer": ["C"], "method": "①增长量＝552−480＝72；②增长率＝增长量÷基期＝72÷480。", "explain": "72÷480＝0.15＝15%，选 C。", "tip": "增长率的分母是基期（480），不是现期。", "hard": "72÷552≈13.0% 是“拿现期作分母”的典型错算，13% 就摆在选项里。"}, {"type": "pure", "level": "基础", "stem": "某市去年 GDP 为 3600 亿元，今年增长 8.5%，今年 GDP 约为多少亿元？", "options": ["3840", "3906", "3924", "4000"], "answer": ["B"], "method": "①“增长 8.5%”→ 现期＝基期×(1+8.5%)；②3600×8.5%＝306；③3600＋306＝3906。", "explain": "3600×(1＋8.5%)＝3600＋306＝3906，选 B。", "tip": "分清“增长了 r”（乘 1+r）与“增长到 r 倍”（直接乘 r）。", "hard": "3840、4000 都是把百分数估歪的结果。"}, {"type": "pure", "level": "进阶", "stem": "某地旅游收入 2023 年同比增长 12%，2024 年同比增长 10%，2024 年比 2022 年约增长：", "options": ["22%", "23.2%", "24%", "20%"], "answer": ["B"], "method": "①间隔增长率 r＝r₁＋r₂＋r₁×r₂；②r＝12%＋10%＋12%×10%＝22%＋1.2%＝23.2%。", "explain": "(1+12%)×(1+10%)＝1.232，故增长 23.2%，选 B。", "tip": "间隔（复合）增长率一定要加两个增长率的乘积项。", "hard": "22%＝12%＋10%，是漏掉乘积项的坑。"}, {"type": "pure", "level": "进阶", "stem": "2019 年某地常住人口 850 万，2024 年为 1000 万，2019—2024 年年均增长量约为（万人/年）：", "options": ["25", "30", "37.5", "150"], "answer": ["B"], "method": "①年均增长量＝(末期−基期)÷年份差；②年份差＝2024−2019＝5；③(1000−850)÷5＝150÷5＝30。", "explain": "150÷5＝30（万人/年），选 B。", "tip": "年份差是“末年份−初年份”，不是年数加 1。", "hard": "37.5＝150÷4，是把年份差错算成 4；150 是总增长量，忘了除以年数。"}, {"type": "pure", "level": "进阶", "stem": "某指标 2022 年为 100，2024 年为 144，2022—2024 年年均增长率约为：", "options": ["15%", "20%", "22%", "44%"], "answer": ["B"], "method": "①两年年均增长→开平方：√(末期÷基期)；②√(144÷100)＝√1.44＝1.2；③1.2−1＝20%。", "explain": "年均增长率＝√(144/100)−1＝1.2−1＝20%，选 B。", "tip": "只有 2 年就开平方、3 年开立方，年份差 n 决定开几次方。", "hard": "44%＝144/100−1，是总增长却忘了开方，最常见的坑。"}, {"type": "pure", "level": "进阶", "stem": "某部分量增速 a＝20%，整体量增速 b＝10%，现期该部分占整体的比重为 30%，则比重比上年约上升多少个百分点？", "options": ["2.0", "2.5", "3.0", "1.5"], "answer": ["B"], "method": "①两期比重差＝现期比重×(a−b)/(1+a)；②＝30%×(20%−10%)/(1+20%)；③＝30%×10%÷1.2＝2.5%。", "explain": "30%×0.1÷1.2＝2.5%，选 B。方向：a＞b，比重上升。", "tip": "判断升降看 a 与 b 的大小；算幅度别忘除以 (1+a)。", "hard": "3.0＝30%×10%，是漏掉 (1+a) 分母的坑。"}, {"type": "pure", "level": "基础", "stem": "甲数为 240，乙数为 60，甲数是乙数的多少倍？", "options": ["0.25", "3", "4", "5"], "answer": ["C"], "method": "①“A 是 B 的几倍”＝A÷B；②240÷60＝4。", "explain": "240÷60＝4，选 C。", "tip": "“是几倍”用除法；“比…多几倍”要再减 1。", "hard": "0.25＝60÷240，是把分子分母写反。"}, {"type": "pure", "level": "基础", "stem": "5 个数的总和是 82.5，它们的平均数是：", "options": ["15.5", "16.5", "17.5", "8.25"], "answer": ["B"], "method": "①平均数＝总和÷个数；②82.5÷5。", "explain": "82.5÷5＝16.5，选 B。", "tip": "直接直除即可，注意小数点位置。", "hard": "8.25 是 82.5÷10，误当成 10 个数。"}, {"type": "pure", "level": "进阶", "stem": "已知 1/7≈14.3%，则 3/7 约为：", "options": ["33.3%", "37.5%", "42.9%", "45%"], "answer": ["C"], "method": "①3/7＝3×(1/7)；②3×14.3%＝42.9%。", "explain": "3/7≈3×14.3%＝42.9%，选 C。", "tip": "常用化分数要背熟：1/7≈14.3%、3/7≈42.9%、1/8＝12.5%、1/9≈11.1%。", "hard": "37.5%＝3/8、33.3%＝1/3，都是“分数对应记混”的坑。"}, {"type": "pure", "level": "进阶", "stem": "某指标先增长 20%，再下降 20%，最终比原来：", "options": ["持平", "下降 4%", "上升 4%", "下降 20%"], "answer": ["B"], "method": "①设原值 100；②100×1.2×0.8＝96；③(96−100)÷100＝−4%，即下降 4%。", "explain": "1×(1+20%)×(1−20%)＝0.96，比原来下降 4%，选 B。", "tip": "先增后降同幅度，基数变了，结果不等于回到原位。", "hard": "“持平”是直觉错误；先乘 1.2 再加、后乘 0.8，缩减的基数更大。"}, {"type": "applied", "level": "基础", "stem": "2023 年该市蔬菜产量约为多少万吨？", "data": "【材料】2024 年某市蔬菜产量 128 万吨，比上年增长 12.5%。", "options": ["112", "113.8", "115", "144"], "answer": ["B"], "method": "①求基期：基期＝现期÷(1+增长率)＝128÷1.125；②12.5%＝1/8，1.125＝9/8；③128÷(9/8)＝128×8/9。", "explain": "128×8÷9＝1024÷9≈113.8（万吨），选 B。", "tip": "“比上年增长 r%”→ 现期＝基期×(1+r)，故基期＝现期÷(1+r)。", "hard": "144＝128×1.125，是求“增长后”的错算，方向正好相反。"}, {"type": "applied", "level": "基础", "stem": "2024 年该省社会消费品零售总额比 2023 年约增加多少亿元？", "data": "【材料】某省 2024 年社会消费品零售总额 24000 亿元，同比增长 6%。", "options": ["1200", "1360", "1440", "1500"], "answer": ["B"], "method": "①给现期和增长率求增长量：增长量＝现期×r/(1+r)；②＝24000×6%/(1+6%)；③＝1440÷1.06。", "explain": "1440÷1.06≈1358.5≈1360（亿元），选 B。", "tip": "增长量不是现期×r；只有用基期×r 才对，而这里的 24000 是现期。", "hard": "1440＝24000×6%，是拿现期当基期算增长量的经典坑。"}, {"type": "applied", "level": "基础", "stem": "2018—2024 年该地区常住人口年均增长约多少万人？", "data": "【材料】2018 年某地区常住人口 620 万人，2024 年为 806 万人。", "options": ["26", "31", "37.2", "186"], "answer": ["B"], "method": "①年均增长量＝(末期−基期)÷年份差；②年份差＝2024−2018＝6；③(806−620)÷6＝186÷6＝31。", "explain": "186÷6＝31（万人/年），选 B。", "tip": "年份差＝2018 到 2024，共 6 年。", "hard": "37.2＝186÷5，是把年份差错算成 5；186 是总增长量，忘了除以年数。"}, {"type": "applied", "level": "进阶", "stem": "2024 年该市快递业务量约比上年增长百分之几？", "data": "【材料】2023 年某市快递业务量 8 亿件，2024 年为 10 亿件。", "options": ["20%", "22.2%", "25%", "125%"], "answer": ["C"], "method": "①增长率＝(现期−基期)÷基期；②(10−8)÷8＝2÷8。", "explain": "2÷8＝0.25＝25%，选 C。", "tip": "增长率的分母永远是基期（8）。", "hard": "20%＝2÷10，是拿现期作分母的坑；125%＝10÷8，是“倍数”而非“增长率”。"}, {"type": "applied", "level": "进阶", "stem": "2024 年该企业营业收入比 2022 年约增长百分之几？", "data": "【材料】某企业 2022 年营业收入 2.5 亿元，2023 年 3 亿元，2024 年 3.6 亿元。", "options": ["20%", "24%", "40%", "44%"], "answer": ["D"], "method": "①2023 年增速＝(3−2.5)/2.5＝20%；②2024 年增速＝(3.6−3)/3＝20%；③间隔增长率＝20%＋20%＋20%×20%＝44%。", "explain": "3.6÷2.5＝1.44，即比 2022 年增长 44%，选 D。", "tip": "给三期数据求“末期比初期”，可直接算 3.6÷2.5，也可套间隔增长率公式。", "hard": "40%＝20%＋20%，是漏掉乘积项的坑。"}, {"type": "applied", "level": "进阶", "stem": "2024 年该市第三产业增加值占 GDP 的比重比上年上升约多少个百分点？", "data": "【材料】某市 2024 年第三产业增加值 3150 亿元，占 GDP 比重 45%；2023 年占 GDP 比重 43%。", "options": ["1", "2", "2.5", "4.5"], "answer": ["B"], "method": "①两期比重差＝现期比重−基期比重；②45%−43%＝2。", "explain": "45%−43%＝2 个百分点，选 B。", "tip": "比重变化的单位是“百分点”，给定时直接两期相减。", "hard": "2.5 是照搬“两期比重差公式”却多算一步的坑；给定时不必再乘 (a−b)/(1+a)。"}, {"type": "applied", "level": "进阶", "stem": "2024 年该省规模以上工业企业利润率（利润总额÷营业收入）约为：", "data": "【材料】2024 年某省规模以上工业企业营业收入 42000 亿元，同比增长 8%；其中利润总额 2520 亿元，同比增长 12%。", "options": ["5.4%", "6%", "6.4%", "7%"], "answer": ["B"], "method": "①利润率＝利润总额÷营业收入；②2520÷42000＝0.06。", "explain": "2520÷42000＝6%，选 B。", "tip": "问“现期利润率”就用现期两数相除，不必先求基期。", "hard": "5.4%=2520/(42000×1.11) 之类的错算；注意 8%、12% 是增长率，不是比重变化。"}, {"type": "applied", "level": "进阶", "stem": "2024 年该地居民人均可支配收入实际增长约百分之几？", "data": "【材料】2024 年某地居民人均可支配收入 36000 元，同比增长 5%；同期 CPI 上涨 2%。", "options": ["2.9%", "4.0%", "5.0%", "7.0%"], "answer": ["A"], "method": "①实际增长率≈名义增长率−通胀率＝5%−2%＝3%（近似）；②更精确：1.05÷1.02−1≈2.9%。", "explain": "1.05÷1.02−1≈0.0294，即实际增长约 2.9%，选 A。", "tip": "“实际增长”要扣除物价因素：粗略相减、精确相除。", "hard": "用相减得 3% 是近似值；如果选项里同时有更精确的值，应选精确值。"}]}, {"set": 10, "date": "2026-10-06", "session": "day", "title": "资料分析速算训练 · 第 10 批 · 分数速算专项（分子分母同乘除 / 同加减 / 化同法 / 差分法 / 比大小 / 特征分数）", "difficulty": "基础+中等", "items": [{"type": "pure", "level": "基础", "topic": "分子分母同乘·化除为乘", "stem": "3.75 ÷ 0.125 ＝（　）", "options": ["3", "30", "300", "0.3"], "answer": ["B"], "method": "① 看除数：0.125＝1/8；\n② 被除数和除数同时乘 8（分子分母同乘一个数，商不变）：3.75×8＝30，0.125×8＝1；\n③ 30÷1＝30。", "explain": "3.75÷0.125＝3.75×8＝30，选 B。", "tip": "除数是 1/8 这类特征数时，一律「除以它＝乘 8」，比列竖式快得多。", "hard": "A 项 3 是把除数当成 1.25 算的（3.75÷1.25＝3），这是最常见的错算，选项里专门放了它。"}, {"type": "pure", "level": "基础", "topic": "分子分母同除·约分", "stem": "156/208 约分成最简分数是（　）", "options": ["39/52", "3/4", "4/5", "13/16"], "answer": ["B"], "method": "① 分子分母同除 4：156÷4＝39，208÷4＝52，得 39/52；\n② 还没到最简，再同除 13：39÷13＝3，52÷13＝4；\n③ 得 3/4。（一步到位也可以：分子分母同除 52。）", "explain": "156÷52＝3，208÷52＝4，所以 156/208＝3/4，选 B。", "tip": "约分要「一次除到底」，只除一次就停容易留下还能再约的假最简。", "hard": "A 项 39/52 就是只除了 4 的中间结果；D 项 13/16 是把 156÷12、208÷13 混着除出来的，看着挺像。"}, {"type": "pure", "level": "基础", "topic": "分子分母同除·约分", "stem": "96/144 化成最简分数是（　）", "options": ["3/4", "2/3", "8/12", "4/6"], "answer": ["B"], "method": "① 找最大公因数：96＝2⁵×3，144＝2⁴×3²，公因数是 2⁴×3＝48；\n② 分子分母同除 48：96÷48＝2，144÷48＝3；\n③ 得 2/3。", "explain": "96/144＝2/3，选 B。", "tip": "记熟 2⁴×3＝48 这类公因数，同除一次就到底。", "hard": "C 项 8/12、D 项 4/6 都还能再约，不是最简；A 项 3/4 是凭感觉凑的（96:144 实际是 2:3）。"}, {"type": "pure", "level": "基础", "topic": "分子分母同加·比大小", "stem": "7/11 的分子和分母同时加上 5，得到 12/16。12/16 与 7/11 相比（　）", "options": ["12/16 更大", "7/11 更大", "一样大", "无法确定"], "answer": ["A"], "method": "① 真分数（比 1 小）分子分母同时加上同一个正数，分数值变大（离 1 更近）；\n② 验算：12/16＝0.75，7/11≈0.636；\n③ 0.75＞0.636，所以 12/16 更大。", "explain": "12/16＝0.75＞7/11≈0.64，同加同一个正数后变大，选 A。", "tip": "记结论：真分数「同加变大、同减变小」；假分数（＞1）反过来。", "hard": "C 项「一样大」最容易被误选——只有「同乘同一个数」才不变，同加同减是会变的。"}, {"type": "pure", "level": "基础", "topic": "分子分母同减·比大小", "stem": "9/10 的分子和分母同时减 4，得到 5/6。5/6 与 9/10 相比（　）", "options": ["9/10 更大", "5/6 更大", "一样大", "无法确定"], "answer": ["A"], "method": "① 真分数分子分母同时减去同一个正数，分数值变小；\n② 验算：5/6≈0.833，9/10＝0.9；\n③ 0.9＞0.833，所以原来的 9/10 更大。", "explain": "9/10＝0.9＞5/6≈0.833，同减同一个正数后变小，选 A。", "tip": "同加同减先看原分数比 1 大还是小：比 1 小就「同加变大、同减变小」。", "hard": "把「同减变小」硬套到假分数上就判反了：如 4/3 同减 2 得 2/1，反而变大。"}, {"type": "pure", "level": "基础", "topic": "错位加减·分数值不变", "stem": "要使 3/8 的分数值不变，分子加上 6，分母应加上（　）", "options": ["16", "12", "18", "24"], "answer": ["A"], "method": "① 分子 3 加 6 变 9，是原来的 3 倍；\n② 「值不变」就要分母同乘 3：8×3＝24；\n③ 分母要加的是 24－8＝16。", "explain": "3/8＝9/24，分子加了 6，分母要加 16，选 A。", "tip": "分数值不变靠的是「同乘同除同一个数」，加了就按倍数把另一边补齐。", "hard": "D 项 24 是「加完以后的新分母」，不是「加上的数」，这是最典型的看错问法。"}, {"type": "pure", "level": "中等", "topic": "化同法·分子化同", "stem": "用化同法比较 47/89 与 48/91 的大小（　）", "options": ["47/89 更大", "48/91 更大", "一样大", "无法确定"], "answer": ["A"], "method": "① 把两个分数的分子化成相同：47/89 的分子要变 48，需乘 48/47，分母同样乘 48/47 → 47/89＝48/(89×48/47)≈48/90.9；\n② 现在分子都是 48，比较分母：分母小的分数大，90.9＜91；\n③ 所以 47/89＞48/91。", "explain": "47/89≈0.5281，48/91≈0.5275，前者大，选 A。", "tip": "两个分数很接近时，把分子（或分母）化成相同再比另一边，是资料分析比大小的标准套路。", "hard": "两者只差约 0.06 个百分点，肉眼根本看不出来，硬除还容易算错，必须用化同法或交叉相乘。"}, {"type": "pure", "level": "中等", "topic": "化同法·分子化同", "stem": "用化同法比较 23/59 与 25/63 的大小（　）", "options": ["25/63 更大", "23/59 更大", "一样大", "无法确定"], "answer": ["A"], "method": "① 把分子化成相同：23/59 的分子要变 25，乘 25/23，分母同乘 → 23/59＝25/(59×25/23)≈25/64.1；\n② 分子同为 25，分母小的值大：63＜64.1；\n③ 所以 25/63＞23/59。", "explain": "23/59≈0.3898，25/63≈0.3968，后者大，选 A。", "tip": "化同法「化分子」或「化分母」都行，挑好算的那边；两个分数都大于 1/2 时，化分母往往更直观。", "hard": "别去比「分子分母的差值」（这里差 2 和差 4），差值法在这种同向变化里会判错。"}, {"type": "pure", "level": "中等", "topic": "差分法", "stem": "用差分法比较 123/456 与 121/449 的大小（　）", "options": ["123/456 更大", "121/449 更大", "一样大", "无法确定"], "answer": ["A"], "method": "① 分子分母都大的是 123/456，都用它减小分数 121/449：\n② 差分数＝(123－121)/(456－449)＝2/7≈0.286；\n③ 差分数与小分数比：0.286＞121/449≈0.269，差分数更大；\n④ 结论（差分法）：差分数大于小分数，则大分数大于小分数 → 123/456 更大。", "explain": "123/456≈0.26974＞121/449≈0.26949，选 A。", "tip": "差分法口诀：差分数与小分数比，同向得答案——差分数大则大分数大。", "hard": "两个数只差万分之几，直接相除看不出来；B 项就是把 2/7 与 121/449 的大小方向弄反了。"}, {"type": "pure", "level": "中等", "topic": "比大小·交叉相乘", "stem": "用交叉相乘比较 37/52 与 45/63 的大小（　）", "options": ["45/63 更大", "37/52 更大", "一样大", "无法确定"], "answer": ["A"], "method": "① 交叉相乘：37×63＝2331，45×52＝2340；\n② 乘积大的那边，和它同向的分数就大（45 与 52 相乘得 2340，更大）；\n③ 所以 45/63＞37/52。", "explain": "37/52≈0.7115，45/63≈0.7143，45/63 更大，选 A。", "tip": "交叉相乘只适用于正分数，记住「谁大跟谁同向」，别把方向搞反。", "hard": "两个乘积只差 9（2331 与 2340），按错一位就会选反，所以一定要写全两位数再比。"}, {"type": "pure", "level": "中等", "topic": "比大小·与 1 比", "stem": "下列分数中最小的是（　）", "options": ["7/9", "5/6", "11/13", "8/11"], "answer": ["D"], "method": "① 四个分数都大于 1/2，改比「与 1 的差距」（差距越大，分数越小）：\n② 1－7/9＝2/9≈0.222，1－5/6≈0.167，1－11/13≈0.154，1－8/11≈0.273；\n③ 8/11 的差距最大 → 8/11 最小。", "explain": "7/9≈0.778，5/6≈0.833，11/13≈0.846，8/11≈0.727，最小的是 8/11，选 D。", "tip": "一群分数都比 1/2 大时，看与 1 的差距；都比 1/2 小时，看与 1/2 的差距——差距越大越小。", "hard": "别按「分子分母都大就大」的直觉排，8/11 分子分母都不突出，却恰好最小。"}, {"type": "pure", "level": "基础", "topic": "特征分数互换", "stem": "160 × 37.5% ＝（　）", "options": ["48", "60", "62.5", "64"], "answer": ["B"], "method": "① 37.5% 就是 3/8（1/8＝12.5%，3 个 1/8 是 37.5%）；\n② 160×3/8＝160÷8×3＝20×3；\n③ ＝60。", "explain": "160×0.375＝60，选 B。", "tip": "特征分数背牢：1/8＝12.5%、3/8＝37.5%、5/8＝62.5%、7/8＝87.5%。", "hard": "A 项 48 是误按 30% 算的；C 项 62.5 是「把 5/8 的值直接搬过来」的数字搬家干扰。"}, {"type": "pure", "level": "中等", "topic": "特征分数互换·比大小", "stem": "下列各数中最大的是（　）", "options": ["5/8", "62.5%", "0.626", "3/5"], "answer": ["C"], "method": "① 先把能互换的都转成小数：5/8＝0.625，62.5%＝0.625，3/5＝0.6；\n② 四个数分别是 0.625、0.625、0.626、0.6；\n③ 0.626 最大。", "explain": "5/8＝0.625＝62.5%，只剩 0.626＞0.625，所以最大的是 0.626，选 C。", "tip": "看到 62.5% 立刻想到 5/8，先化同再比，避免被「形式不同」骗过去。", "hard": "A 项和 B 项数值完全一样（0.625），这就是设的陷阱——它会让你以为「两个都对」，其实是让你漏掉 0.626。"}, {"type": "pure", "level": "基础", "topic": "分子分母同乘·化除为整", "stem": "4.8 ÷ 0.16 ＝（　）", "options": ["3", "30", "300", "0.3"], "answer": ["B"], "method": "① 被除数和除数同时乘 100，变成整数除法：480÷16；\n② 480÷16＝30（16×30＝480）。", "explain": "4.8÷0.16＝480÷16＝30，选 B。", "tip": "小数除法先把除数和被除数「同乘」成整数，商不变但好算。", "hard": "A 项 3 是 0.48÷0.16 的结果，属小数点挪错一位的典型错选。"}, {"type": "applied", "level": "中等", "topic": "化同法·比重比大小", "stem": "哪个部门的营业收入占本市的比重更高？（　）", "data": "【材料】2024 年甲部门营业收入 47 亿元，其所在市合计 89 亿元；乙部门营业收入 48 亿元，其所在市合计 91 亿元。", "options": ["甲部门（47/89）", "乙部门（48/91）", "一样高", "无法确定"], "answer": ["A"], "method": "① 比重＝部分÷整体，即要比 47/89 与 48/91；\n② 化同法：把分子化成 48，47/89＝48/(89×48/47)≈48/90.9；\n③ 分子相同，分母小的值大：90.9＜91 → 47/89 更大；\n④ 所以甲部门占比更高。", "explain": "47÷89≈52.81%，48÷91≈52.75%，甲部门略高，选 A。", "tip": "比重比较不要急着除，先化同（分子或分母化同）再看另一边，能省一大截时间。", "hard": "两者只差约 0.06 个百分点，直接估会看成「差不多」，B、C 两项就是为这种粗糙估算准备的。"}, {"type": "applied", "level": "中等", "topic": "比大小·交叉相乘（增速）", "stem": "甲、乙两市 2024 年 GDP 的同比增速谁更快？（　）", "data": "【材料】甲市 GDP 由 2023 年的 1230 亿元增至 2024 年的 1300 亿元；乙市由 1210 亿元增至 1281 亿元。", "options": ["甲市", "乙市", "一样快", "无法判断"], "answer": ["B"], "method": "① 增速＝增长量÷基期量：甲＝70/1230，乙＝71/1210；\n② 交叉相乘：70×1210＝84700，71×1230＝87330；\n③ 乙市的乘积更大，与它同向 → 71/1210 更大；\n④ 所以乙市增速更快。", "explain": "甲：70÷1230≈5.69%；乙：71÷1210≈5.87%，乙市更快，选 B。", "tip": "比增速就是比两个分数，交叉相乘最稳；别只看「增长量 70 比 71 少」就下结论。", "hard": "增长量甲是 70、乙是 71，只看绝对量容易误判成「差不多」甚至选甲；关键看基数。"}, {"type": "applied", "level": "基础", "topic": "分子分母同除·倍数", "stem": "2024 年该地区 GDP 是 2020 年的多少倍？（　）", "data": "【材料】某地区 GDP：2020 年 1.28 万亿元，2024 年 3.84 万亿元。", "options": ["2.8 倍", "3 倍", "3.2 倍", "4 倍"], "answer": ["B"], "method": "① 倍数＝2024 年÷2020 年＝3.84/1.28；\n② 分子分母同除 1.28：3.84÷1.28＝3，1.28÷1.28＝1；\n③ 所以是 3 倍。", "explain": "3.84÷1.28＝3，选 B。", "tip": "求「A 是 B 的几倍」直接相除；若两数有公约数，同除一次就把答案除出来了。", "hard": "D 项 4 倍是「把 3.84 看成 4、1.28 看成 1」粗估出来的，粗估在这种题上会直接翻车。"}, {"type": "applied", "level": "中等", "topic": "特征分数·求基期", "stem": "2023 年该企业的利润约为多少亿元？（　）", "data": "【材料】2024 年某企业实现利润 8.5 亿元，比上年增长 6.25%。", "options": ["7.5", "8.0", "8.5", "9.1"], "answer": ["B"], "method": "① 材料给的是现期 8.5 亿元和增速 6.25%；\n② 6.25%＝1/16，所以现期＝基期×(1＋1/16)＝基期×17/16；\n③ 基期＝现期×16/17＝8.5×16/17＝8.0；\n④ 即 2023 年利润约 8.0 亿元。", "explain": "8.5÷(1＋6.25%)＝8.5÷1.0625＝8.0（亿元），选 B。", "tip": "求基期＝现期÷(1＋增速)；遇到 6.25%、12.5%、14.3% 这类特征数，先化成分数再算。", "hard": "C 项 8.5 是现期值原样搬过来；D 项 9.06 是「8.5×(1＋6.25%)」把方向做反了。"}, {"type": "applied", "level": "中等", "topic": "分子分母同加减·比重升降", "stem": "2024 年该市服务业增加值占 GDP 的比重与 2023 年相比（　）", "data": "【材料】2024 年某市服务业增加值 1280 亿元，同比增长 7.5%；全市 GDP 3000 亿元，同比增长 5%。", "options": ["上升", "下降", "不变", "无法判断"], "answer": ["A"], "method": "① 比重＝部分÷整体，写成两个时期的分数比：现期 1280/3000，基期 1280/(1＋7.5%) ÷ 3000/(1＋5%)；\n② 化同思路：把两期的分母都看成「总体」，比较分子的相对变化——部分增速 7.5%＞总体增速 5%；\n③ 部分比整体涨得快，占比就上升；\n④ 所以 2024 年占比上升。", "explain": "部分涨 7.5%、整体涨 5%，部分涨得更快 → 比重上升，选 A。", "tip": "判断比重升降不用真算，只比「部分增速」和「总体增速」：部分快则比重升。", "hard": "C 项「不变」是把「增速都为正」误当成「比重不动」；两个增速不同就一定升降。"}, {"type": "applied", "level": "中等", "topic": "分子分母同乘·凑整求总量", "stem": "2024 年该省规模以上工业总产值约为多少万亿元？（　）", "data": "【材料】2024 年某省高新技术产业产值 3.75 万亿元，占全省规模以上工业总产值的 12.5%。", "options": ["4.7", "24", "30", "46.9"], "answer": ["C"], "method": "① 已知部分 3.75 万亿元、占比 12.5%，求整体＝部分÷占比；\n② 12.5%＝1/8，所以除以 12.5% 就是乘 8；\n③ 3.75×8＝30（万亿元）。", "explain": "3.75÷12.5%＝3.75×8＝30（万亿元），选 C。", "tip": "求整体＝部分÷占比；占比是 12.5%、20%、25% 这类特征数时，直接换成「乘几」比除小数快。", "hard": "A 项 4.7 是「3.75÷0.8」之类的错算；D 项 46.9 是把 3.75÷8% 算成的结果（占比看错）。"}]}, {"set": 11, "date": "2026-10-06", "session": "day", "title": "资料分析速算训练 · 第 11 批 · 增长率与增长量专项（r/(1+r) 型：现期量÷(1＋r)×r）", "difficulty": "基础+中等", "items": [{"type": "pure", "level": "进阶", "topic": "增长量·化除为乘（r 非特征分数）", "stem": "148 ÷ (1＋21.5%) × 21.5% ≈（　）", "options": ["24.7", "26.2", "26.9", "31.8"], "answer": ["B"], "method": "① 认型：分子和后面相乘的都是 21.5% → 这是求增长量＝现期量×r/(1+r)；\n② 化除为乘：r/(1+r)＝1－1/(1+r)，先算 148÷1.215：1.215×120＝145.8，剩 2.2，2.2÷1.215≈1.8 → 商≈121.8；\n③ 148－121.8＝26.2。\n（也可百化分：21.5%≈1/4.65 → 148÷5.65≈26.2。）", "explain": "148÷1.215×0.215＝31.82÷1.215≈26.2，选 B。", "tip": "最大的坑是直接 148×21.5%＝31.8（忘除分母）——那是现期量×增长率，多了一层 (1+r)。", "hard": "A 24.7 是按 20%（1/5）不修正算的（148÷6），C 26.9 是按 22.2%（1/4.5）不修正算的（148÷5.5）：一左一右夹住答案，21.5% 正落在中间，只能靠修正或精确估。"}, {"type": "pure", "level": "进阶", "topic": "增长量·百化分＋修正（29%）", "stem": "120 ÷ (1＋29%) × 29% ≈（　）", "options": ["27.0", "27.7", "34.8", "93.0"], "answer": ["A"], "method": "① 百化分：29%≈1/3.45 → 增长量≈120÷(3.45＋1)＝120÷4.45≈27.0；\n② 或化除为乘：120－120÷1.29＝120－93.0＝27.0；\n③ 或先凑 30%：30%＝3/10 → r/(1+r)＝3/13，120×3/13＝27.7，再把 r 从 30% 收回 1 个百分点（约 −0.7）→ 27.0。", "explain": "120÷1.29×0.29＝34.8÷1.29≈27.0，选 A。", "tip": "别写 120×29%＝34.8（忘除分母）；也别把 120÷1.29＝93.0 当答案（那是基期量）。", "hard": "B 27.7 是用 30% 算、没往回收的结果，只差 1 个百分点就差 0.7；选项间距小，必须会修正。"}, {"type": "pure", "level": "基础", "topic": "增长量·化分数（24%＝6/25）", "stem": "248 ÷ (1＋24%) × 24% ＝（　）", "options": ["48.0", "49.6", "59.5", "200.0"], "answer": ["A"], "method": "① 24%＝6/25 → r/(1+r)＝6/31；\n② 248÷31＝8，8×6＝48。\n（估算版：按 25% 得 248÷5＝49.6，24% 比 25% 小一点 → 结果略低于 49.6。）", "explain": "248÷1.24×0.24＝59.52÷1.24＝48.0，选 A。", "tip": "别直接写 248×24%＝59.5（忘除分母）。", "hard": "B 49.6 是按 25%（1/4）算的；D 200.0 是 248÷1.24 的基期量。"}, {"type": "pure", "level": "基础", "topic": "增长量·百化分（10%＝1/10）", "stem": "660 ÷ (1＋10%) × 10% ＝（　）", "options": ["55.0", "60.0", "66.0", "600.0"], "answer": ["B"], "method": "① 10%＝1/10 → r/(1+r)＝1/11；\n② 660÷11＝60。", "explain": "660÷1.1×0.1＝66÷1.1＝60.0，选 B。", "tip": "r＝1/n 时直接「现期量÷(n＋1)」：10% 就是 ÷11，别去算 0.1÷1.1。", "hard": "C 66.0 是忘除分母；D 600.0 是基期量；A 55.0 是把 n＋1 记成了 12。"}, {"type": "pure", "level": "基础", "topic": "增长量·百化分（12.5%＝1/8）", "stem": "360 ÷ (1＋12.5%) × 12.5% ＝（　）", "options": ["40.0", "45.0", "51.4", "320.0"], "answer": ["A"], "method": "① 12.5%＝1/8 → 增长量＝360÷(8＋1)＝40；\n② 验算：360÷1.125＝320（基期量），360−320＝40。", "explain": "360÷1.125×0.125＝45÷1.125＝40.0，选 A。", "tip": "12.5%＝1/8、6.25%＝1/16、25%＝1/4、37.5%＝3/8，这几个特征分数要条件反射。", "hard": "B 45.0 是 360×12.5%（忘除）；C 51.4 是把分母错用成 1−12.5%＝0.875；D 320.0 是基期量。"}, {"type": "pure", "level": "进阶", "topic": "增长量·化分数（37.5%＝3/8）", "stem": "275 ÷ (1＋37.5%) × 37.5% ＝（　）", "options": ["68.8", "75.0", "103.1", "200.0"], "answer": ["B"], "method": "① 37.5%＝3/8 → r/(1+r)＝3/11；\n② 275÷11＝25，25×3＝75。", "explain": "275÷1.375×0.375＝103.125÷1.375＝75.0，选 B。", "tip": "分子不是 1 的特征分数（3/8、5/8、5/6）要「先约分母、再乘分子」。", "hard": "C 103.1 是 275×37.5%（忘除）；A 68.8 是把 3/11 记成 1/4（275÷4）；D 200.0 是基期量。"}, {"type": "pure", "level": "进阶", "topic": "增长量·化分数（15%＝3/20）", "stem": "1495 ÷ (1＋15%) × 15% ＝（　）", "options": ["195.0", "224.3", "249.2", "1300.0"], "answer": ["A"], "method": "① 15%＝3/20 → r/(1+r)＝3/23；\n② 1495÷23＝65，65×3＝195。", "explain": "1495÷1.15×0.15＝224.25÷1.15＝195.0，选 A。", "tip": "15% 不要硬算 0.15÷1.15，直接走 3/23。", "hard": "B 224.3 是忘除分母；C 249.2 是按 20%（1/5）估的；D 1300.0 是基期量。"}, {"type": "pure", "level": "基础", "topic": "增长量·化分数（8%＝2/25）", "stem": "1296 ÷ (1＋8%) × 8% ＝（　）", "options": ["96.0", "103.7", "108.0", "1200.0"], "answer": ["A"], "method": "① 8%＝2/25 → r/(1+r)＝2/27；\n② 1296÷27＝48，48×2＝96。", "explain": "1296÷1.08×0.08＝103.68÷1.08＝96.0，选 A。", "tip": "小增长率（≤10%）用化分数最稳：先约分母再乘分子。", "hard": "B 103.7 是忘除；C 108.0 是按 8.3% 粗估；D 1200.0 是基期量。"}, {"type": "pure", "level": "进阶", "topic": "增长量·化分数（6.5%＝13/200）", "stem": "1065 ÷ (1＋6.5%) × 6.5% ＝（　）", "options": ["65.0", "69.2", "163.8", "1000.0"], "answer": ["A"], "method": "① 6.5%＝13/200 → r/(1+r)＝13/213；\n② 1065÷213＝5，5×13＝65。", "explain": "1065÷1.065×0.065＝69.225÷1.065＝65.0，选 A。", "tip": "带小数的增长率（6.5%、8.5%、4.5%）先写成分数再算，别硬除。", "hard": "B 69.2 是忘除；C 163.8 是把「现期量÷增长率」算反了；D 1000.0 是基期量。"}, {"type": "pure", "level": "进阶", "topic": "增长量·化分数（9% 先约分母）", "stem": "436 ÷ (1＋9%) × 9% ＝（　）", "options": ["36.0", "39.2", "43.1", "400.0"], "answer": ["A"], "method": "① 9% → r/(1+r)＝9/109；\n② 436÷109＝4，4×9＝36。", "explain": "436÷1.09×0.09＝39.24÷1.09＝36.0，选 A。", "tip": "先把「1＋r%」的分母约掉（436÷109＝4），比先乘再除快得多。", "hard": "B 39.2 是忘除；C 43.1 是把分母写成 1−9%＝0.91；D 400.0 是基期量。"}, {"type": "pure", "level": "基础", "topic": "基期量·化除为乘", "stem": "148 ÷ (1＋21.5%) ≈（　）", "options": ["116.2", "121.8", "179.8", "188.5"], "answer": ["B"], "method": "① 基期量＝现期量÷(1＋r)＝148÷1.215；\n② 估算：1.215×120＝145.8，差 2.2，2.2÷1.215≈1.8 → 121.8。", "explain": "148÷1.215≈121.8，选 B。", "tip": "同比增长时基期量一定比现期量小；别再乘一次 1.215（那是推下一年）。", "hard": "A 116.2 是 148×(1−21.5%)，用减法代替除法，错得最像；C 179.8 是 148×1.215；D 188.5 是 148÷0.785。"}, {"type": "pure", "level": "进阶", "topic": "减少量·下降时用 (1−r) 做分母", "stem": "850 ÷ (1 − 15%) × 15% ＝（　）", "options": ["127.5", "150.0", "977.5", "1000.0"], "answer": ["B"], "method": "① 下降率时基期量＝现期量÷(1−r)＝850÷0.85＝1000；\n② 减少量＝1000−850＝150（等价于 850×0.15÷0.85）。", "explain": "850÷0.85×0.15＝1000×0.15＝150.0，选 B。", "tip": "下降类题分母是 (1−r)，千万别照抄 (1＋r)；850×15%＝127.5 就是忘除分母的错算。", "hard": "D 1000.0 是基期量（很多人算到这就选）；C 977.5＝850×1.15，把下降当成增长了。"}, {"type": "applied", "level": "基础", "topic": "增长量·化分数（24%＝6/25）", "data": "【材料】2025年某省新能源汽车产量 310 万辆，比上年增长 24%。", "stem": "2025年该省新能源汽车产量比上年约增加（　）万辆", "options": ["60.0", "62.0", "74.4", "250.0"], "answer": ["A"], "method": "① 增长量＝现期量×r/(1+r)＝310×0.24÷1.24；\n② 24%＝6/25 → r/(1+r)＝6/31：310÷31＝10，10×6＝60。", "explain": "310÷1.24×0.24＝74.4÷1.24＝60.0，选 A。", "tip": "问「增加多少」是求增量；别顺手去算 2024 年产量（那是 250）。", "hard": "B 62.0 是按 25% 算的（310÷5）；C 74.4 是 310×24%（忘除）；D 250.0 是基期量。"}, {"type": "applied", "level": "基础", "topic": "增长量·百化分（10%＝1/11）", "data": "【材料】2025年某市规模以上工业增加值 550 亿元，比上年增长 10%。", "stem": "2025年该市规上工业增加值比上年约增加（　）亿元", "options": ["45.8", "50.0", "55.0", "500.0"], "answer": ["B"], "method": "① 10%＝1/10 → 增长量＝550÷(10＋1)＝50；\n② 验算：550÷1.1＝500（基期量），550−500＝50。", "explain": "550÷1.1×0.1＝55÷1.1＝50.0，选 B。", "tip": "「1/10」直接除以 11，一步到位。", "hard": "C 55.0 是 550×10%（忘除）；D 500.0 是基期量；A 45.8 是误按「÷12」算的。"}, {"type": "applied", "level": "基础", "topic": "增长量·百化分（12.5%＝1/8）", "data": "【材料】2025年某快递企业快递业务量 720 亿件，同比增长 12.5%。", "stem": "2025年该企业业务量同比约增加（　）亿件", "options": ["80.0", "90.0", "102.9", "640.0"], "answer": ["A"], "method": "① 12.5%＝1/8 → 增长量＝720÷(8＋1)＝80；\n② 验算：720÷1.125＝640（基期量），720−640＝80。", "explain": "720÷1.125×0.125＝90÷1.125＝80.0，选 A。", "tip": "看到 12.5% 就 ÷9，别去列竖式。", "hard": "B 90.0 是 720×12.5%（忘除）；C 102.9 是把分母写成 1−12.5%＝0.875；D 640.0 是基期量。"}, {"type": "applied", "level": "进阶", "topic": "增长量·化分数（37.5%＝3/8）", "data": "【材料】2025年某市接待游客旅游收入 385 亿元，同比增长 37.5%。", "stem": "2025年该市旅游收入同比约增加（　）亿元", "options": ["105.0", "144.4", "96.3", "280.0"], "answer": ["A"], "method": "① 37.5%＝3/8 → r/(1+r)＝3/11；\n② 385÷11＝35，35×3＝105。", "explain": "385÷1.375×0.375＝144.375÷1.375＝105.0，选 A。", "tip": "分子不为 1 时先约分母（÷11）再乘分子（×3）。", "hard": "B 144.4 是 385×37.5%（忘除）；C 96.3 是把 3/11 误记成 1/4（385÷4）；D 280.0 是基期量。"}, {"type": "applied", "level": "基础", "topic": "增长量·化分数（15%＝3/20）", "data": "【材料】2025年某省粮食总产量 690 万吨，比上年增长 15%。", "stem": "2025年该省粮食总产量比上年约增加（　）万吨", "options": ["86.3", "90.0", "103.5", "600.0"], "answer": ["B"], "method": "① 15%＝3/20 → r/(1+r)＝3/23；\n② 690÷23＝30，30×3＝90。", "explain": "690÷1.15×0.15＝103.5÷1.15＝90.0，选 B。", "tip": "15% 走 3/23；别把 15% 当成 12.5% 用 1/8（那就成了 86.3）。", "hard": "A 86.3 是误按 12.5%（1/8）算的（690÷8）；C 103.5 是忘除；D 600.0 是基期量。"}, {"type": "applied", "level": "进阶", "topic": "增长量·化分数（6.5%＝13/200）", "data": "【材料】2025年某地网上零售额 852 亿元，同比增长 6.5%。", "stem": "2025年该地网上零售额同比约增加（　）亿元", "options": ["52.0", "55.4", "131.1", "800.0"], "answer": ["A"], "method": "① 6.5%＝13/200 → r/(1+r)＝13/213；\n② 852÷213＝4，4×13＝52。", "explain": "852÷1.065×0.065＝55.38÷1.065＝52.0，选 A。", "tip": "小数百分数（6.5%）先化成分数（13/200）再约，硬除最容易出错。", "hard": "B 55.4 是忘除；C 131.1 是「现期量÷增长率」算反了；D 800.0 是基期量。"}, {"type": "applied", "level": "进阶", "topic": "增长量·化分数（6%＝3/50）", "data": "【材料】2025年某省技术合同成交额 848 亿元，同比增长 6%。", "stem": "2025年该省技术合同成交额同比约增加（　）亿元", "options": ["48.0", "50.9", "141.3", "800.0"], "answer": ["A"], "method": "① 6%＝3/50 → r/(1+r)＝3/53；\n② 848÷53＝16，16×3＝48。", "explain": "848÷1.06×0.06＝50.88÷1.06＝48.0，选 A。", "tip": "问「同比增加」求的是增量，不是基期量（800）。", "hard": "B 50.9 是 848×6%（忘除）；C 141.3 是 848÷6% 算反了；D 800.0 是基期量。"}, {"type": "applied", "level": "进阶", "topic": "增长量·化分数（6%＝3/50）", "data": "【材料】2025年某市限额以上单位消费品零售额 1431 亿元，同比增长 6%。", "stem": "2025年该市限上消费品零售额同比约增加（　）亿元", "options": ["81.0", "85.9", "238.5", "1350.0"], "answer": ["A"], "method": "① 6%＝3/50 → r/(1+r)＝3/53；\n② 1431÷53＝27，27×3＝81。", "explain": "1431÷1.06×0.06＝85.86÷1.06＝81.0，选 A。", "tip": "分母是「1＋6%＝1.06」，别用成 1.6 或 0.94。", "hard": "B 85.9 是忘除；C 238.5 是 1431÷6% 算反了；D 1350.0 是基期量。"}]}, {"set": 12, "date": "2026-10-07", "session": "day", "title": "资料分析速算训练 · 第 12 批 · 分数速算与增长量综合（同乘同除 · 比大小 · 化同 · 差分 · 特征分数 + 增长量/基期量）", "difficulty": "基础+中等", "items": [{"type": "pure", "level": "基础", "topic": "特征分数互换（12.5%＝1/8）", "stem": "375 × 12.5% ＝（　）", "options": ["37.5", "46.9", "56.3", "3000"], "answer": ["B"], "method": "① 12.5%＝1/8（特征分数要条件反射）；\n② 375×12.5%＝375÷8；\n③ 375÷8＝46.875 → 46.9。", "explain": "375×0.125＝46.875≈46.9，选 B。", "tip": "12.5%＝1/8、6.25%＝1/16、37.5%＝3/8、62.5%＝5/8，看到就化分数，别去列竖式。", "hard": "A 37.5 是 375×10%（把 12.5% 当 10%）；C 56.3 是 375×15%；D 3000 是 375÷0.125（乘除方向搞反）。"}, {"type": "pure", "level": "基础", "topic": "分子分母同乘同除（÷0.125＝×8）", "stem": "3.6 ÷ 0.125 ＝（　）", "options": ["0.45", "2.88", "28.8", "288"], "answer": ["C"], "method": "① 0.125＝1/8，除以 1/8 等于乘 8；\n② 3.6×8＝28.8。", "explain": "3.6÷0.125＝3.6×8＝28.8，选 C。", "tip": "“小数÷0.125”就是“×8”，比硬算竖式快得多：0.125、0.25、0.5 都有对应的整数倍换算。", "hard": "A 0.45 是 3.6×0.125（方向错）；B 2.88 是 3.6÷1.25；D 288 是 3.6÷0.0125（小数点多数一位）。"}, {"type": "pure", "level": "进阶", "topic": "比大小（交叉相乘＋中间值）", "stem": "下列分数中，数值最大的是（　）", "options": ["7/13", "9/17", "5/9", "11/21"], "answer": ["C"], "method": "① 与中间值 1/2 比：四个分数都略大于 1/2，看“超出 1/2 多少”；\n② 7/13：13÷2＝6.5，分子比 6.5 多 0.5；9/17：多 0.5；5/9：多 0.5；11/21：多 0.5——超出量相同，改看分母（分母越大越接近 1/2）；\n③ 也可两两交叉相乘：5/9 与 7/13 → 5×13＝65＞7×9＝63，故 5/9＞7/13；再比 5/9 与其余同理。", "explain": "四个分数分别约为 0.538、0.529、0.556、0.524，最大的是 5/9，选 C。", "tip": "比大小先找中间值（1/2、1）或取倒数；分子分母都差得不多时，交叉相乘最稳。", "hard": "四个选项都在 0.52～0.56 之间，肉眼几乎看不出差别，必须动笔交叉相乘；凭“数感”很容易选错。"}, {"type": "pure", "level": "进阶", "topic": "化同法（把分子化相同）", "stem": "比较 17/28 和 21/35 的大小，正确的是（　）", "options": ["17/28 ＞ 21/35", "17/28 ＜ 21/35", "17/28 ＝ 21/35", "无法比较"], "answer": ["A"], "method": "① 化同法：把分子凑成接近的数（最小公倍或同乘）；\n② 交叉相乘更直接：17×35＝595，21×28＝588；\n③ 595＞588 → 17/28＞21/35。", "explain": "17/28≈0.607，21/35＝0.600，故 17/28＞21/35，选 A。", "tip": "化同法：把两个分数的分子（或分母）化成相同，再比另一边——分子相同时，分母小的分数大。", "hard": "B 是“想当然”——21/35 分子分母都比 17/28 大，直觉容易觉得它更大，其实化简后 21/35＝3/5＝0.6，反而更小。"}, {"type": "pure", "level": "进阶", "topic": "差分法（差分数与小分数比）", "stem": "比较 76/253 和 78/260 的大小，正确的是（　）", "options": ["76/253 ＞ 78/260", "76/253 ＜ 78/260", "76/253 ＝ 78/260", "无法比较"], "answer": ["A"], "method": "① 分子分母都大一点的是“大分数”78/260，小的是“小分数”76/253；\n② 差分数＝(78−76)/(260−253)＝2/7≈0.286；\n③ 差分数(0.286)＜小分数(76/253≈0.300)，按差分法结论：小分数更大 → 76/253＞78/260。", "explain": "76/253≈0.3004，78/260＝0.3000，故 76/253＞78/260，选 A。", "tip": "差分法口诀：差分数与大分数同向、与小分数比较定结论——差分数小于小分数，则小分数更大。", "hard": "两个分数都约等于 0.30，只差 0.0004，不折算几乎分不出；用差分法一步到位。"}, {"type": "pure", "level": "基础", "topic": "分子分母同加同减（真分数同加变大）", "stem": "把 3/5 的分子、分母同时加上 2，得到 5/7，与原分数相比（　）", "options": ["变大", "变小", "不变", "无法确定"], "answer": ["A"], "method": "① 规律：真分数（小于 1）的分子分母同时加同一个正数，分数值变大；\n② 验算：3/5＝0.6，5/7≈0.714；\n③ 0.714＞0.6，故变大。", "explain": "5/7≈0.714＞3/5＝0.6，选 A。", "tip": "记住两条：真分数“同加变大、同减变小”；假分数（大于 1）反过来。错位加减法（分子分母同加各自的若干倍）则分数值不变。", "hard": "B/C 是凭感觉的常见错选；要养成“化小数验算”的习惯，尤其分数接近 1 时。"}, {"type": "pure", "level": "基础", "topic": "增长量·百化分（10%＝1/10）", "stem": "440 ÷ (1＋10%) × 10% ＝（　）", "options": ["36", "40", "44", "400"], "answer": ["B"], "method": "① 这是求增长量＝现期量×r/(1+r)；\n② 10%＝1/10 → r/(1+r)＝1/11；\n③ 440÷11＝40。", "explain": "440÷1.1×0.1＝44÷1.1＝40，选 B。", "tip": "r＝1/n 时直接“现期量÷(n＋1)”：10% 就是 ÷11，别去算 0.1÷1.1。", "hard": "C 44 是忘除分母（440×10%）；D 400 是基期量（440÷1.1）；A 36 是把 n＋1 记成 12。"}, {"type": "pure", "level": "基础", "topic": "增长量·百化分（12.5%＝1/8）", "stem": "648 ÷ (1＋12.5%) × 12.5% ＝（　）", "options": ["64.8", "72", "81", "576"], "answer": ["B"], "method": "① 12.5%＝1/8 → 增长量＝648÷(8＋1)＝72；\n② 验算：648÷1.125＝576（基期量），648−576＝72。", "explain": "648÷1.125×0.125＝81÷1.125＝72，选 B。", "tip": "12.5% 直接“÷9”，一步到位；别写成 648×12.5%＝81。", "hard": "C 81 是忘除分母；D 576 是基期量；A 64.8 是 648×10%。"}, {"type": "pure", "level": "进阶", "topic": "增长量·化分数（37.5%＝3/8）", "stem": "253 ÷ (1＋37.5%) × 37.5% ＝（　）", "options": ["63", "69", "94.9", "184"], "answer": ["B"], "method": "① 37.5%＝3/8 → r/(1+r)＝3/11；\n② 253÷11＝23，23×3＝69。", "explain": "253÷1.375×0.375＝94.875÷1.375＝69，选 B。", "tip": "分子不是 1 的特征分数（3/8、5/8、5/6）要“先约分母、再乘分子”。", "hard": "C 94.9 是 253×37.5%（忘除）；A 63 是把 3/11 误记成 1/4（253÷4≈63）；D 184 是基期量。"}, {"type": "pure", "level": "基础", "topic": "基期量·化除为乘（15%）", "stem": "690 ÷ (1＋15%) ≈（　）", "options": ["586.5", "600", "793.5", "810"], "answer": ["B"], "method": "① 求基期量＝现期量÷(1＋r)＝690÷1.15；\n② 15%＝3/20，690÷1.15＝690×20/23＝(690÷23)×20＝30×20＝600。", "explain": "690÷1.15＝600，选 B。", "tip": "同比增长时基期量一定比现期量小；别再乘一次 1.15（那是推下一年）。", "hard": "A 586.5 是 690×(1−15%)，用减法代替除法，错得最像；C 793.5 是 690×1.15；D 810 是 690÷0.85（当成了下降）。"}, {"type": "pure", "level": "进阶", "topic": "减少量·下降时用 (1−r) 做分母", "stem": "680 ÷ (1 − 15%) × 15% ＝（　）", "options": ["102", "120", "782", "800"], "answer": ["B"], "method": "① 下降率时基期量＝现期量÷(1−r)＝680÷0.85＝800；\n② 减少量＝800−680＝120。", "explain": "680÷0.85×0.15＝800×0.15＝120，选 B。", "tip": "下降类题分母是 (1−r)，千万别照抄 (1＋r)；680×15%＝102 就是忘除分母的错算。", "hard": "A 102 是忘除分母；D 800 是基期量（很多人算到这就选）；C 782＝680×1.15，把下降当成增长了。"}, {"type": "pure", "level": "基础", "topic": "特征分数互换（6.25%＝1/16）", "stem": "576 × 6.25% ＝（　）", "options": ["32", "34", "36", "38.4"], "answer": ["C"], "method": "① 6.25%＝1/16（可用 12.5%＝1/8 再折半推出）；\n② 576×6.25%＝576÷16；\n③ 576÷16＝36。", "explain": "576×0.0625＝36，选 C。", "tip": "6.25%＝1/16、12.5%＝1/8、25%＝1/4、50%＝1/2——一半再一半的家族要熟。", "hard": "A 32 是 576÷18；B 34 是 576÷17；D 38.4 是 576÷15（把 1/16 记成了 1/15）。"}, {"type": "applied", "level": "基础", "topic": "增长量·化分数（24%＝6/25）", "data": "【材料】2025年某市新能源汽车产量 434 万辆，比上年增长 24%。", "stem": "2025年该市新能源汽车产量比上年约增加（　）万辆", "options": ["84", "87", "104.2", "350"], "answer": ["A"], "method": "① 增长量＝现期量×r/(1+r)＝434×0.24÷1.24；\n② 24%＝6/25 → r/(1+r)＝6/31：434÷31＝14，14×6＝84。", "explain": "434÷1.24×0.24＝104.16÷1.24＝84，选 A。", "tip": "问“增加多少”是求增量；别顺手去算 2024 年产量（那是 350）。", "hard": "C 104.2 是 434×24%（忘除）；D 350 是基期量；B 87 是按 25% 算的（434÷5）。"}, {"type": "applied", "level": "基础", "topic": "增长量·百化分（12.5%＝1/8）", "data": "【材料】2025年某经开区规模以上工业总产值 810 亿元，同比增长 12.5%。", "stem": "2025年该经开区规上工业总产值同比约增加（　）亿元", "options": ["80", "90", "101.3", "720"], "answer": ["B"], "method": "① 12.5%＝1/8 → 增长量＝810÷(8＋1)＝90；\n② 验算：810÷1.125＝720（基期量），810−720＝90。", "explain": "810÷1.125×0.125＝101.25÷1.125＝90，选 B。", "tip": "“同比增长多少”求增量；12.5% 直接 ÷9。", "hard": "C 101.3 是 810×12.5%（忘除）；D 720 是基期量；A 80 是把 1/8 记成 1/9 的近似。"}, {"type": "applied", "level": "基础", "topic": "基期量·化除为乘（15%）", "data": "【材料】2025年某省网上零售额 1380 亿元，同比增长 15%。", "stem": "2024年该省网上零售额约为（　）亿元", "options": ["1173", "1200", "1587", "1600"], "answer": ["B"], "method": "① 求基期量＝现期量÷(1＋r)＝1380÷1.15；\n② 15%＝3/20 → 1380×20/23＝(1380÷23)×20＝60×20＝1200。", "explain": "1380÷1.15＝1200，选 B。", "tip": "问的是“2024 年”（基期），不是“增加多少”；基期量比现期量小。", "hard": "A 1173 是 1380×(1−15%)（用减法代替除法）；C 1587 是 1380×1.15；D 1600 是 1380÷0.8625 之类的乱算。"}, {"type": "applied", "level": "进阶", "topic": "减少量·下降时用 (1−r)", "data": "【材料】2025年某地规模以上工业企业利润 918 亿元，比上年下降 15%。", "stem": "2025年该地规上工业利润比上年约减少（　）亿元", "options": ["137.7", "162", "780", "1080"], "answer": ["B"], "method": "① 下降率时基期量＝现期量÷(1−r)＝918÷0.85＝1080；\n② 减少量＝1080−918＝162。", "explain": "918÷0.85×0.15＝1080×0.15＝162，选 B。", "tip": "分母是 (1−15%)＝0.85，不是 1.15；918×15%＝137.7 就是忘除分母的错算。", "hard": "A 137.7 是忘除分母；D 1080 是基期量；C 780 是 918÷1.15 之类的方向错误。"}, {"type": "applied", "level": "进阶", "topic": "增长量·化分数（6%＝3/50）", "data": "【材料】2025年某市技术合同成交额 1113 亿元，同比增长 6%。", "stem": "2025年该市技术合同成交额同比约增加（　）亿元", "options": ["56", "63", "66.8", "1050"], "answer": ["B"], "method": "① 6%＝3/50 → r/(1+r)＝3/53；\n② 1113÷53＝21，21×3＝63。", "explain": "1113÷1.06×0.06＝66.78÷1.06＝63，选 B。", "tip": "小数百分数先化分数（6%＝3/50）再约分，比硬除稳。", "hard": "C 66.8 是 1113×6%（忘除）；D 1050 是基期量；A 56 是把 3/53 记成 1/20 的粗估。"}, {"type": "applied", "level": "进阶", "topic": "增长量·化分数（37.5%＝3/8）", "data": "【材料】2025年某市接待游客旅游收入 638 亿元，同比增长 37.5%。", "stem": "2025年该市旅游收入同比约增加（　）亿元", "options": ["159.5", "174", "239.3", "464"], "answer": ["B"], "method": "① 37.5%＝3/8 → r/(1+r)＝3/11；\n② 638÷11＝58，58×3＝174。", "explain": "638÷1.375×0.375＝239.25÷1.375＝174，选 B。", "tip": "分子不为 1 时先约分母（÷11）再乘分子（×3）。", "hard": "C 239.3 是 638×37.5%（忘除）；D 464 是基期量；A 159.5 是把 3/11 记成 1/4（638÷4≈159.5）。"}, {"type": "applied", "level": "进阶", "topic": "比重反求·特征分数（62.5%＝5/8）", "data": "【材料】2025年某市第三产业增加值 3910 亿元，占该市地区生产总值的 62.5%。", "stem": "2025年该市地区生产总值约为（　）亿元", "options": ["2444", "5480", "6256", "6900"], "answer": ["C"], "method": "① 部分量＝整体量×比重 → 整体量＝部分量÷比重＝3910÷62.5%；\n② 62.5%＝5/8 → 3910÷(5/8)＝3910×8/5；\n③ 3910÷5＝782，782×8＝6256。", "explain": "3910÷0.625＝6256，选 C。", "tip": "62.5%＝5/8，除以 5/8 等于乘 8/5；先除后乘比直接列竖式快。", "hard": "A 2444 是 3910×0.625（方向反了，把部分当整体算）；B 5480 是 3910÷0.714 之类乱算；D 6900 是用 3910÷0.567 估错。"}, {"type": "applied", "level": "基础", "topic": "增长率（现期÷基期−1）", "data": "【材料】某市快递业务量 2024 年为 5.6 亿件，2025 年为 6.72 亿件。", "stem": "2025年该市快递业务量同比增长率约为（　）", "options": ["12%", "16%", "20%", "24%"], "answer": ["C"], "method": "① 增长率＝现期量÷基期量−1＝6.72÷5.6−1；\n② 6.72÷5.6＝1.2（5.6×1.2＝6.72）；\n③ 1.2−1＝0.2＝20%。", "explain": "6.72÷5.6−1＝20%，选 C。", "tip": "求增长率用“现期÷基期−1”；别用“(现期−基期)÷现期”，那是算增量的占比。", "hard": "A 12% 是 (6.72−5.6)÷… 算错方向；B 16% 用错分母；D 24% 是把 1.2 当成增长率（忘了减 1）。"}]}, {"set": 13, "date": "2026-10-08", "session": "day", "title": "资料分析速算训练 · 第 13 批（分数速算 + 增长量专项）", "difficulty": "基础+中等", "items": [{"type": "pure", "level": "基础", "topic": "特征分数互换", "stem": "12.5% 相当于下列哪个分数？", "options": ["1/6", "1/8", "1/12", "1/16"], "answer": ["B"], "method": "12.5% = 12.5/100 = 1/8。\n特征分数要背熟：1/8＝12.5%。", "explain": "12.5/100 约分得 1/8，故选 B。", "tip": "1/8＝12.5%、1/16＝6.25% 常被记反。", "hard": "选项里放了 1/16，要弄清「再一半」的递推。"}, {"type": "pure", "level": "基础", "topic": "特征分数互换 · 计算", "stem": "计算 840 × 37.5% = ？", "options": ["300", "315", "297", "330"], "answer": ["B"], "method": "37.5% = 3/8。\n840 ÷ 8 = 105，再 × 3 = 315。", "explain": "把百分数化成分数再乘，比硬乘 0.375 更快更准，答案 315。", "tip": "37.5% 就是 3/8。", "hard": "干扰项 297 是错值，注意口径。"}, {"type": "pure", "level": "基础", "topic": "首数直除 · 估算", "stem": "计算 2.46 ÷ 1.35 ≈ ？", "options": ["1.82", "1.62", "2.02", "1.42"], "answer": ["A"], "method": "估算：1.35×1.8＝2.43，差 0.03；0.03÷1.35≈0.02。\n故商约 1.82。", "explain": "先定首位 1.8，再用余数修正得 1.82，选 A。", "tip": "别把 1.35 粗当成 1.3。", "hard": "选项间距约 0.2，需估到小数点后两位。"}, {"type": "pure", "level": "基础", "topic": "百分数加减", "stem": "计算 46.7% + 18.6% − 7.3% = ？", "options": ["58.0%", "55.6%", "60.2%", "57.9%"], "answer": ["A"], "method": "先加后减：46.7 + 18.6 = 65.3；65.3 − 7.3 = 58.0。", "explain": "逐步合并得 58.0%，选 A。", "tip": "小数点对齐，别漏进位。", "hard": "57.9% 与正确值仅差 0.1，必须算准。"}, {"type": "pure", "level": "基础", "topic": "估算 · 范围判断", "stem": "估算 1234.5 ÷ 3.9，下列最接近的是：", "options": ["约 320", "约 260", "约 400", "约 300"], "answer": ["A"], "method": "3.9≈4，1234.5÷4≈309；分母比 4 小，实际值略大，约 316。", "explain": "先按 4 估得 309，再判断略大，落到 320，选 A。", "tip": "分母偏小，商偏大。", "hard": "300 与 320 都可能被选，靠「略大于 309」定夺。"}, {"type": "pure", "level": "基础", "topic": "化分数 · 估算", "stem": "估算 653 ÷ 1.24 ≈ ？", "options": ["约 530", "约 500", "约 560", "约 480"], "answer": ["A"], "method": "1.24≈1.25＝5/4，653×4/5＝522.4；分母实际略小，商略大，约 527。", "explain": "用 1.25 化分数估得 522，再上调一点，选 530。", "tip": "把 1.24 当 1.25 最省事，但记得回调。", "hard": "500 与 530 相差 6%，估不准会滑向 500。"}, {"type": "pure", "level": "进阶", "topic": "比大小 · 交叉相乘", "stem": "比较 a＝123/456 与 b＝234/877 的大小：", "options": ["a＞b", "a＜b", "a＝b", "无法判断"], "answer": ["A"], "method": "交叉相乘：123×877＝107871，234×456＝106704。\n左积大，故 a＞b。", "explain": "107871＞106704，所以 123/456＞234/877，选 A。", "tip": "交叉相乘只适用于正分数比较。", "hard": "两积只差约 1%，可先估 a≈0.270、b≈0.267 验证。"}, {"type": "pure", "level": "进阶", "topic": "差分法 · 比大小", "stem": "用差分法比较 268/1006 与 257/981 的大小：", "options": ["268/1006 大", "257/981 大", "相等", "无法比较"], "answer": ["A"], "method": "大分数 268/1006、小分数 257/981。\n差分数＝(268−257)/(1006−981)＝11/25＝0.44＞257/981≈0.262，故大分数更大。", "explain": "差分数大于小分数 ⇒ 大分数＞小分数，选 A。", "tip": "差分法口诀：差分数与小分数比，同向得结论。", "hard": "若差分数小于小分数，结论相反。"}, {"type": "pure", "level": "进阶", "topic": "化同法 · 比大小", "stem": "比较 47/123 与 51/134 的大小：", "options": ["47/123 大", "51/134 大", "相等", "无法判断"], "answer": ["A"], "method": "交叉相乘：47×134＝6298，51×123＝6273。\n6298＞6273，故 47/123＞51/134。", "explain": "左积大 25，得 47/123 略大，选 A。", "tip": "两分数接近时，交叉相乘最可靠。", "hard": "积只差 0.4%，速算要细心。"}, {"type": "pure", "level": "进阶", "topic": "分子分母同加同减", "stem": "把分数 37/89 的分子、分母同时加上 11，新分数与原分数相比：", "options": ["变大", "变小", "不变", "无法确定"], "answer": ["A"], "method": "新分数＝(37+11)/(89+11)＝48/100＝0.48；原分数 37/89≈0.4157。\n真分数同加变大。", "explain": "0.48＞0.4157，故变大，选 A。", "tip": "真分数同加变大、同减变小；假分数相反。", "hard": "判「真/假」要看清是否小于 1。"}, {"type": "pure", "level": "进阶", "topic": "特征分数互换 · 约分", "stem": "计算 0.125 × 72 = ？", "options": ["8", "9", "7.2", "10.8"], "answer": ["B"], "method": "0.125＝1/8。\n72÷8＝9。", "explain": "把小数化成特征分数再算，得 9，选 B。", "tip": "0.125＝1/8，是高频特征分数。", "hard": "干扰项 7.2 是把 0.125 当 0.1 的错值。"}, {"type": "pure", "level": "进阶", "topic": "化分数 · 估算", "stem": "估算 5.36 ÷ 0.24 ≈ ？", "options": ["约 22.3", "约 13.4", "约 24.5", "约 18.6"], "answer": ["A"], "method": "0.24≈0.25＝1/4，5.36×4＝21.44；分母略小，商略大，约 22.3。", "explain": "用 1/4 估得 21.44，再上调，落到 22.3，选 A。", "tip": "除数接近 0.25 就化 1/4。", "hard": "24.5 是把分母当 0.22 的错值。"}, {"type": "applied", "level": "进阶", "topic": "增长量 · 一般增长率", "stem": "某市 2025 年 GDP 为 5678.9 亿元，比上年增长 6.5%。则 2025 年 GDP 比 2024 年增长约多少亿元？", "data": "【材料】某市 2025 年地区生产总值 5678.9 亿元，同比增长 6.5%。", "options": ["约 347", "约 369", "约 325", "约 402"], "answer": ["A"], "method": "增长量＝现期量×r/(1+r)。\n① 5678.9×6.5%≈369（忘除分母的错值）；\n② 再 ÷1.065 ≈ 347。", "explain": "5678.9×0.065≈369.1，÷1.065≈346.6，约 347 亿元，选 A。", "tip": "干扰项 369 就是「只乘 r 没除 (1+r)」。", "hard": "增长量的分母是 1+r，别各乘各的。"}, {"type": "applied", "level": "进阶", "topic": "增长量 · 百化分", "stem": "2025 年某地高新技术企业营业收入 4287.5 亿元，同比增长 12.5%。则该增长量约为：", "data": "【材料】2025 年某地区高新技术企业实现营业收入 4287.5 亿元，同比增长 12.5%。", "options": ["约 476", "约 536", "约 613", "约 428"], "answer": ["A"], "method": "12.5%＝1/8。\n增长量＝现期量÷(8+1)＝4287.5÷9≈476。", "explain": "百化分：r＝1/n 时增长量＝现期量÷(n+1)，故 4287.5÷9≈476，选 A。", "tip": "干扰 536＝4287.5×12.5%（忘除分母）；613 是分母错用 1−r。", "hard": "r 化成 1/n 后分母是 n+1，不是 n。"}, {"type": "applied", "level": "仿真", "topic": "增长量 · 修正法", "stem": "2025 年某市新能源汽车产量 1284.6 万辆，同比增长 29%。则增长量约为：", "data": "【材料】2025 年某市新能源汽车产量 1284.6 万辆，比上年增长 29%。", "options": ["约 289", "约 373", "约 525", "约 296"], "answer": ["A"], "method": "先按 30% 估：增长量≈1284.6×0.3/1.3≈296.4；实际 r 比 30% 小，要往回收一点，约 289。", "explain": "精算 1284.6×0.29/1.29≈288.8，约 289，选 A。", "tip": "296 是按 30% 不修正的值，373 是忘除分母。", "hard": "修正法要判断「往哪边收」：r 偏小，结果偏小。"}, {"type": "applied", "level": "仿真", "topic": "基期量 · 反向求解", "stem": "2025 年某市社会消费品零售总额 3267.8 亿元，比上年增长 8%。则 2024 年约为：", "data": "【材料】2025 年某市社会消费品零售总额 3267.8 亿元，比上年增长 8%。", "options": ["约 3026", "约 3529", "约 3006", "约 3180"], "answer": ["A"], "method": "基期量＝现期量÷(1+r)＝3267.8÷1.08≈3025.7。", "explain": "3267.8÷1.08≈3026 亿元，选 A。", "tip": "干扰 3529＝3267.8×1.08（错乘）；3006＝3267.8×(1−8%)，也是常见错法。", "hard": "求基期只能除，不能乘 1−r（两者不等）。"}, {"type": "applied", "level": "仿真", "topic": "两期比重差", "stem": "某省 2025 年第三产业增加值同比增长 6.8%，全省 GDP 同比增长 5.2%，2024 年第三产业占 GDP 比重为 53.1%。则 2025 年第三产业占比约为：", "data": "【材料】某省 2024 年第三产业增加值占 GDP 比重 53.1%；2025 年第三产业增加值同比增长 6.8%，全省 GDP 同比增长 5.2%。", "options": ["53.9%", "54.8%", "52.4%", "55.2%"], "answer": ["A"], "method": "本期比重＝基期比重×(1+a)/(1+b)＝53.1%×1.068/1.052。\n1.068/1.052≈1.0152，×53.1%≈53.9%。", "explain": "部分增速(6.8%)快于整体(5.2%)，占比上升约 0.8 个百分点到 53.9%，选 A。", "tip": "别直接用 53.1%×(1+6.8%−5.2%)，那是近似且误差偏大。", "hard": "a、b 用的是增速不是占比，注意区分。"}, {"type": "applied", "level": "仿真", "topic": "年均增长量", "stem": "某市 2020 年常住人口 892.4 万人，2025 年达 1057.6 万人。则 2020—2025 年常住人口年均增长约多少万人？", "data": "【材料】某市 2020 年末常住人口 892.4 万人，2025 年末达 1057.6 万人。", "options": ["约 33.0", "约 165.2", "约 27.5", "约 41.3"], "answer": ["A"], "method": "年均增长量＝(末期−初期)÷年数＝(1057.6−892.4)÷5＝165.2÷5≈33.0。", "explain": "总增量 165.2 万，2020→2025 是 5 年，年均约 33.0 万，选 A。", "tip": "干扰 165.2 是总增量（忘除年数）。", "hard": "年数算法：年份相减（2025−2020＝5），别多算一年。"}, {"type": "applied", "level": "仿真", "topic": "年均增长率 · 开平方", "stem": "某市 2022 年 GDP 为 4523 亿元，2025 年为 5621 亿元。则 2022—2025 年 GDP 的年均增长率约为：", "data": "【材料】某市 2022 年 GDP 4523 亿元，2025 年 GDP 5621 亿元。", "options": ["约 7.5%", "约 8.1%", "约 24.3%", "约 5.4%"], "answer": ["A"], "method": "倍数＝5621÷4523≈1.243，年数 n＝3。\n(1+r)³≈1.243 ⇒ 1+r≈1.075 ⇒ r≈7.5%。", "explain": "开三次方：1.075³≈1.243，故年均增长率约 7.5%，选 A。", "tip": "干扰 24.3% 是把「总增长率」当成了年均增长率（忘开方）。", "hard": "选项 8.1% 是开方后未微调的值，注意 1.075 与 1.081 的差别。"}, {"type": "applied", "level": "仿真", "topic": "平均数 · 单位换算", "stem": "某电商平台 2025 年成交额 2.347 万亿元，活跃买家 8.62 亿人。则人均成交额约为：", "data": "【材料】2025 年某平台成交额（GMV）2.347 万亿元，年度活跃买家 8.62 亿人。", "options": ["约 2723 元", "约 272 元", "约 27227 元", "约 2045 元"], "answer": ["A"], "method": "人均＝总额÷人数。\n2.347 万亿元＝23470 亿元；23470÷8.62≈2723 元。", "explain": "单位先统一到「元/人」，23470 亿÷8.62 亿≈2723 元，选 A。", "tip": "万亿→亿差 10000 倍，是资料分析最大的单位坑。", "hard": "干扰 27227 元正是差了一个数量级的错值。"}]}, {"set": 14, "date": "2026-10-09", "session": "day", "title": "资料分析速算训练 · 第 14 批（特征分数 + 增长量专项 + 估算）", "difficulty": "基础+中等", "items": [{"type": "pure", "level": "基础", "topic": "首数直除", "stem": "计算 4726 ÷ 123 的值（保留一位小数）。", "data": "", "options": ["30.4", "38.4", "42.8", "48.4"], "answer": ["B"], "method": "首数直除：123×38＝4674，余 52；52÷123≈0.4，故 4726÷123≈38.4。", "explain": "123×38＝4674，与 4726 相差 52，52/123 首位是 4，所以商≈38.4。", "tip": "先定商的位数（四位数÷三位数≈两位数），别把商写成 384。", "hard": "选项 30.4、42.8 是位数或估位错误，首数算对即可排除。"}, {"type": "pure", "level": "基础", "topic": "特征分数互换", "stem": "计算 37.5% × 2400 ＝（　）", "data": "", "options": ["800", "900", "960", "1080"], "answer": ["B"], "method": "37.5%＝3/8；2400×3/8＝2400÷8×3＝300×3＝900。", "explain": "把 37.5% 化成 3/8：2400÷8＝300，再×3＝900。", "tip": "37.5%＝3/8（不是 3/7），先化分数再算。", "hard": "把 37.5% 记成 0.357 会滑向干扰项。"}, {"type": "pure", "level": "基础", "topic": "特征分数互换", "stem": "计算 12.5% × 880 ＝（　）", "data": "", "options": ["99", "110", "121", "88"], "answer": ["B"], "method": "12.5%＝1/8；880÷8＝110。", "explain": "12.5% 就是 1/8，880 除以 8 得 110。", "tip": "12.5%、6.25%、25%、62.5% 都是常用特征分数，先记牢。", "hard": "别把 12.5% 老老实实列竖式乘，浪费时间。"}, {"type": "pure", "level": "基础", "topic": "特征分数互换·分子分母同乘", "stem": "计算 2750 ÷ 0.125 ＝（　）", "data": "", "options": ["2200", "22000", "220000", "1100"], "answer": ["B"], "method": "0.125＝1/8；除以 1/8 等于乘 8：2750×8＝22000。", "explain": "2750÷0.125＝2750×8＝22000。", "tip": "『除以 0.125 等于乘 8』，反过来『乘 0.125 等于除以 8』。", "hard": "小数点位数最容易错，先想清楚是乘 8 还是除以 8。"}, {"type": "pure", "level": "进阶", "topic": "分子分母同除·约分", "stem": "计算 (3.15 × 0.4) ÷ 0.9 ＝（　）", "data": "", "options": ["1.2", "1.4", "1.6", "0.7"], "answer": ["B"], "method": "先算分子 3.15×0.4＝1.26；再 1.26÷0.9＝12.6÷9＝1.4。", "explain": "分子分母同乘 10：12.6÷9＝1.4。", "tip": "除以 0.9 约等于乘 1.1，可先估 1.26×1.1≈1.39。", "hard": "把 0.9 当 1 会得 1.26，正好落在干扰项附近。"}, {"type": "pure", "level": "进阶", "topic": "比大小·化同法", "stem": "下列分数中，数值最大的是（　）", "data": "", "options": ["5/13", "7/18", "3/8", "9/23"], "answer": ["D"], "method": "交叉相乘逐一比较：5/13 与 7/18 → 5×18=90＜7×13=91，7/18 大；7/18 与 9/23 → 7×23=161＜9×18=162，9/23 更大。", "explain": "5/13≈0.385、7/18≈0.389、3/8≈0.375、9/23≈0.391，最大为 9/23。", "tip": "分子分母都不同时，交叉相乘比大小最快。", "hard": "几数只差千分之几，必须动笔交叉相乘，光靠估会滑向干扰项。"}, {"type": "pure", "level": "进阶", "topic": "比大小·差分法", "stem": "用差分法比较，下列分数中数值最大的是（　）", "data": "", "options": ["47/123", "53/139", "45/121", "51/137"], "answer": ["A"], "method": "差分法：47/123 与 53/139，差分数＝(53−47)/(139−123)＝6/16＝0.375，小于小分数 47/123≈0.382，故大分数 53/139＜47/123；同法比较其余，47/123 最大。", "explain": "各值：47/123≈0.3821、53/139≈0.3813、45/121≈0.3719、51/137≈0.3723，最大为 47/123。", "tip": "差分数＞小分数 → 大分数＞小分数；差分数＜小分数 → 大分数＜小分数。", "hard": "四个分数只差千分之几，必须用差分法，硬算会超时。"}, {"type": "pure", "level": "进阶", "topic": "估算·首数直除", "stem": "估算 198.7 ÷ 4.03 的值，最接近（　）", "data": "", "options": ["49.3", "45.0", "53.5", "39.5"], "answer": ["A"], "method": "把 4.03 看成 4：198.7÷4＝49.7；除数略大，结果略小于 49.7，取 49.3。", "explain": "198.7÷4≈49.7，实际除数 4.03 略大于 4，商略小，约 49.3。", "tip": "估算时先凑整，再按偏差方向微调。", "hard": "选项间距较大，估到 49 附近即可锁定答案。"}, {"type": "pure", "level": "仿真", "topic": "多步运算·估算", "stem": "计算 (2.35 × 108) ÷ 3.2 ≈ （　）", "data": "", "options": ["79.3", "72.5", "85.1", "66.2"], "answer": ["A"], "method": "先算分子 2.35×108＝253.8；再首数直除：3.2×79＝252.8，余 1，故≈79.3。", "explain": "253.8÷3.2＝79.3。", "tip": "两步题先算整块再除，别中途取整丢精度。", "hard": "把 2.35×108 算成 253.9 也无妨，仍在 A 的范围。"}, {"type": "pure", "level": "仿真", "topic": "估算·百分数拆解", "stem": "估算 6234 × 1.187 ≈ （　）", "data": "", "options": ["7400", "7100", "7800", "8200"], "answer": ["A"], "method": "拆成 6234×(1＋0.187)：6234＋6234×0.187≈6234＋1166＝7400。", "explain": "6234×0.187≈6234×0.2−6234×0.013≈1246.8−81≈1166，加回 6234 得 7400。", "tip": "把百分数拆成『整齐数±零头』，算得又快又稳。", "hard": "0.187 拆成 0.2−0.013，避免直接乘的大误差。"}, {"type": "pure", "level": "进阶", "topic": "百分数加减", "stem": "计算 45.6% ＋ 18.9% − 12.3% ＝ （　）", "data": "", "options": ["52.2%", "51.2%", "53.2%", "50.2%"], "answer": ["A"], "method": "先加后减：45.6＋18.9＝64.5，64.5−12.3＝52.2（%）。", "explain": "45.6%＋18.9%＝64.5%，再减 12.3% 得 52.2%。", "tip": "整数部分与小数部分分开算，避免进位错误。", "hard": "三个数连加带减，注意 45.6＋18.9 的进位。"}, {"type": "pure", "level": "基础", "topic": "平均数·估算", "stem": "估算 3945.6 ÷ 523.4 的值，最接近（　）", "data": "", "options": ["7.5", "6.8", "8.3", "5.9"], "answer": ["A"], "method": "523.4×7＝3663.8，余 3945.6−3663.8＝281.8；281.8÷523.4≈0.54，故≈7.54≈7.5。", "explain": "商在 7 与 8 之间且偏向 7.5，选 7.5。", "tip": "先试乘整数部分，再用余数定小数位。", "hard": "选项 6.8 与 8.3 是整数部分估错，先定 x.5 附近。"}, {"type": "applied", "level": "基础", "topic": "增长率", "stem": "2023年该市地区生产总值同比增长率约为（　）", "data": "【材料】某市2023年地区生产总值1234.5亿元，2022年为1102.3亿元。", "options": ["10.2%", "12.0%", "13.5%", "8.7%"], "answer": ["B"], "method": "增长率＝(现期−基期)÷基期＝(1234.5−1102.3)÷1102.3＝132.2÷1102.3。", "explain": "132.2÷1102.3≈0.120，即约 12.0%。", "tip": "增长率分母是『基期量』，别拿现期量当分母。", "hard": "现期−基期只差 132.2，除以 1102 只有 12% 左右，别被绝对值误导。"}, {"type": "applied", "level": "进阶", "topic": "增长量·百化分", "stem": "2023年该产品产量比上年增长约多少万吨（　）", "data": "【材料】2023年某产品产量2456.8万吨，同比增长12.5%。", "options": ["273.0", "307.1", "2183.8", "245.7"], "answer": ["A"], "method": "12.5%＝1/8，属『百化分』：增长量＝现期量÷(n＋1)＝2456.8÷9≈273.0（万吨）。", "explain": "2456.8÷9≈273.0 万吨。", "tip": "r＝1/n 时增长量＝现期÷(n＋1)；12.5% 就除以 9。", "hard": "干扰项 307.1＝现期×12.5%（忘除分母）最易误选。"}, {"type": "applied", "level": "进阶", "topic": "增长量·化分数", "stem": "2023年该市社会消费品零售总额比上年增长约多少亿元（　）", "data": "【材料】2023年某市社会消费品零售总额8600.0亿元，同比增长24%。", "options": ["1664.5", "2064.0", "6935.5", "1720.0"], "answer": ["A"], "method": "24%＝6/25，增长量＝现期量×6/(25＋6)＝8600×6/31≈1664.5（亿元）。", "explain": "8600×6÷31＝51600÷31≈1664.5 亿元。", "tip": "增长量＝现期×r/(1＋r)；把 r 化成 6/25 更快。", "hard": "干扰项 2064.0＝8600×24%（忘除 1＋r），6935.5 是被错当成基期量。"}, {"type": "applied", "level": "进阶", "topic": "基期量·估算", "stem": "2022年该市快递业务收入约为（　）", "data": "【材料】2023年某市快递业务收入128.6亿元，同比增长7.3%。", "options": ["119.9", "138.0", "121.0", "117.5"], "answer": ["A"], "method": "基期量＝现期量÷(1＋r)＝128.6÷1.073。", "explain": "1.073×119.9≈128.6，故约 119.9 亿元。", "tip": "求基期量是除法，分母是 1＋增长率。", "hard": "干扰项 138.0＝128.6×1.073（把乘法当除法用）。"}, {"type": "applied", "level": "仿真", "topic": "两期比重差", "stem": "2023年该市第三产业增加值占地区生产总值的比重，与2022年相比约（　）", "data": "【材料】某市2023年第三产业增加值3560.2亿元、地区生产总值8520.5亿元；2022年第三产业增加值3210.4亿元、地区生产总值7920.3亿元。", "options": ["上升1.3个百分点", "下降1.3个百分点", "上升4.6个百分点", "上升0.3个百分点"], "answer": ["A"], "method": "2023年比重＝3560.2/8520.5≈41.8%；2022年比重＝3210.4/7920.3≈40.5%；差≈＋1.3 个百分点。", "explain": "41.8%−40.5%＝1.3 个百分点，比重上升。", "tip": "比重差用『百分点』，先分别算两期比重再相减。", "hard": "干扰项 4.6 是分式本身算错（把分母看错）得出的。"}, {"type": "applied", "level": "仿真", "topic": "间隔增长率", "stem": "2023年该地区旅客周转量比2022年约增长（　）", "data": "【材料】某地区旅客周转量：2023年比2021年增长27.2%，2022年比2021年增长8.6%。", "options": ["17.1%", "18.6%", "16.0%", "19.5%"], "answer": ["A"], "method": "设2023年比2022年增长 r，则 (1＋8.6%)(1＋r)＝1＋27.2%，故 1＋r＝1.272÷1.086≈1.171。", "explain": "1.272÷1.086≈1.171，r≈17.1%。", "tip": "间隔增长率用两期增长率相除还原，别直接相减。", "hard": "干扰项 18.6%＝27.2%−8.6%（直接相减的错算）。"}, {"type": "applied", "level": "仿真", "topic": "年均增长率·开方估算", "stem": "2018—2023年该市地区生产总值年均增长率约为（　）", "data": "【材料】某市地区生产总值2018年5620亿元、2023年8215亿元。", "options": ["7.9%", "9.2%", "6.5%", "10.4%"], "answer": ["A"], "method": "年均增长率＝(末年/初年)^(1/n)−1，n＝5；8215/5620≈1.462，(1.462)^0.2≈1.079。", "explain": "1.462 开 5 次方约 1.079，故年均增长约 7.9%。", "tip": "年均增长率是开方，不是总增长率÷年数。", "hard": "干扰项 9.2%≈(1.462−1)/5（总增长率除年数，错算）。"}, {"type": "applied", "level": "仿真", "topic": "增长量·下降型百化分", "stem": "2023年该市新能源汽车保有量比上年减少约多少万辆（　）", "data": "【材料】2023年某市新能源汽车保有量38.6万辆，同比下降12.5%。", "options": ["5.5", "4.8", "6.3", "3.5"], "answer": ["A"], "method": "下降型：12.5%＝1/8，减少量＝现期量÷(n−1)＝38.6÷7≈5.5（万辆）。", "explain": "减少量＝基期−现期＝38.6/(1−12.5%)×12.5%＝38.6÷7≈5.5 万辆。", "tip": "下降时分母用 1−r；r＝1/n 时减少量＝现期÷(n−1)。", "hard": "干扰项 4.8＝38.6×12.5%（忘除以 1−r 的错算）。"}]}, {"set": 15, "date": "2026-10-10", "session": "day", "title": "资料分析速算训练 · 第 15 批（分数速算 + 增长量·基期量专项）", "difficulty": "基础+中等", "items": [{"type": "pure", "level": "基础", "topic": "特征分数互换（37.5%＝3/8）", "stem": "计算 37.5% × 2,368 ＝（　）", "options": ["788", "888", "988", "1,088"], "answer": ["B"], "method": "先把百分数换成特征分数：37.5%＝3/8。\n原式＝2368 ÷ 8 × 3＝296 × 3＝888。", "explain": "37.5%＝3/8，故 2368×37.5%＝2368÷8×3＝888，选 B。", "tip": "37.5% 是高频特征分数，等于 3/8（不是 3/7）；同类的还有 12.5%＝1/8、62.5%＝5/8。", "hard": "把 37.5% 误当 3/7 会得到 1014，正好落在干扰项附近，务必记准分母是 8。"}, {"type": "pure", "level": "基础", "topic": "分数比大小（交叉相乘）", "stem": "下列对 31/67 与 43/91 的大小关系判断正确的是（　）", "options": ["31/67 ＞ 43/91", "31/67 ＜ 43/91", "31/67 ＝ 43/91", "无法比较"], "answer": ["B"], "method": "分子、分母同时增大，用交叉相乘：\n31×91＝2821；43×67＝2881。\n2821＜2881，所以 31/67 ＜ 43/91。", "explain": "交叉相乘后 31×91＝2821 ＜ 43×67＝2881，故 31/67＜43/91，选 B。", "tip": "分子分母都变大时不能凭直觉判，交叉相乘两步乘法最稳。", "hard": "别用“分子分母都变大，值应该变大”的直觉去猜。"}, {"type": "pure", "level": "基础", "topic": "分子分母同乘同除（凑整）", "stem": "计算 0.875 × 4,480 ＝（　）", "options": ["3,520", "3,920", "4,120", "4,320"], "answer": ["B"], "method": "把 0.875 写成 7/8。\n原式＝4480 ÷ 8 × 7＝560 × 7＝3920。", "explain": "0.875＝7/8，故 4480×0.875＝4480÷8×7＝3920，选 B。", "tip": "0.125、0.25、0.375、0.625、0.875 先换分数（1/8、1/4、3/8、5/8、7/8）。", "hard": "4480 能被 8 整除是本题捷径信号，遇到整十整百倍数先找可整除的分母。"}, {"type": "pure", "level": "进阶", "topic": "化同法（化同分子再比）", "stem": "比较 17/53 与 34/103 的大小，正确的是（　）", "options": ["17/53 ＞ 34/103", "17/53 ＜ 34/103", "两者相等", "无法比较"], "answer": ["B"], "method": "把分子化成相同：17/53＝34/106。\n分子都是 34，比分母：106＞103，分母越大分数越小。\n故 34/106＜34/103，即 17/53＜34/103。", "explain": "化同分子后 17/53＝34/106＜34/103，所以 17/53＜34/103，选 B。", "tip": "化同法优先化“容易被凑成整倍数”的那一边（这里 17→34 正好翻倍）。", "hard": "若改去化同分母（53→106、103→106），计算量更大还易错。"}, {"type": "pure", "level": "进阶", "topic": "差分法（差分数与小分数比）", "stem": "比较 53/97 与 61/109 的大小，正确的是（　）", "options": ["53/97 ＞ 61/109", "53/97 ＜ 61/109", "两者相等", "无法比较"], "answer": ["B"], "method": "61/109 为“大分数”、53/97 为“小分数”，差分数＝(61−53)/(109−97)＝8/12≈0.667。\n差分数 0.667 ＞ 小分数 53/97≈0.546，故大分数 ＞ 小分数。", "explain": "差分数≈0.67 大于小分数≈0.55，按差分法结论：大分数 ＞ 小分数，故选 B。", "tip": "差分法口诀：差分数比小分数大，则大分数更大；反之则更小。", "hard": "差分数比较只需估计（0.67 与 0.55 一望即分），不必精确算两个分数值。"}, {"type": "pure", "level": "进阶", "topic": "分子分母同加同减（错位加减 · 估算）", "stem": "计算 638 ÷ 1.07 ≈（　）", "options": ["446", "516", "596", "636"], "answer": ["C"], "method": "化除为乘：1/1.07≈1−0.07+0.07²≈0.9349。\n638×0.9349≈638−41.5≈596。", "explain": "638÷1.07≈638×0.9349≈596，选 C。", "tip": "除以 1+r 时用“乘（1−r）”近似，r 越小越准；r＝7% 时误差仅在千分位。", "hard": "只乘 0.93 会得到 593（略偏小），要估到 596 需保留 r 的一次项。"}, {"type": "pure", "level": "基础", "topic": "首数直除（估算）", "stem": "计算 5,678 ÷ 8.3 ≈（　）", "options": ["604", "644", "684", "724"], "answer": ["C"], "method": "先估量级：5678÷8≈710，结果在 680 附近。\n试 8.3×680＝5644，余 34；34÷8.3≈4。\n故结果≈684。", "explain": "8.3×684＝5677.2≈5678，故 5678÷8.3≈684，选 C。", "tip": "首位直除：先估量级，再用整十数试乘、看余数修正，一般一步到位。", "hard": "除数带小数先当整数估（8.3≈8），避免一上来就列竖式。"}, {"type": "pure", "level": "基础", "topic": "百分数加减", "stem": "计算 1 − 13.7% − 27.5% ＝（　）", "options": ["48.8%", "58.8%", "68.8%", "71.2%"], "answer": ["B"], "method": "先合并减数：13.7%＋27.5%＝41.2%。\n再用 100% 减：100%−41.2%＝58.8%。", "explain": "1−13.7%−27.5%＝100%−41.2%＝58.8%，选 B。", "tip": "多个百分数相减先“合并减数”再减 1，少一步少一处错。", "hard": "13.7＋27.5 小数位要对齐（＝41.2），错位相加会得到 40.2 等干扰值。"}, {"type": "pure", "level": "进阶", "topic": "增长量·百化分（12.5%→÷9）", "stem": "某指标现期值为 3,780，同比增长 12.5%，则增长量约为（　）", "options": ["336", "378", "420", "472"], "answer": ["C"], "method": "百化分：12.5%＝1/8，增长量＝现期量÷(n＋1)＝现期量÷9。\n3780÷9＝420。", "explain": "12.5%＝1/8，增长量＝现期量÷9＝420，选 C。", "tip": "求增长量首选百化分：r＝1/n 时增长量＝现期量÷(n＋1)；10%→÷11、25%→÷5。", "hard": "直接用现期×r＝3780×12.5%＝472.5，正是干扰项 D，属“忘了除分母”的典型错算。"}, {"type": "pure", "level": "进阶", "topic": "增长量·化除为乘", "stem": "某指标现期值为 2,486，同比增长 6.5%，则增长量约为（　）", "options": ["118", "152", "186", "214"], "answer": ["B"], "method": "先求基期：2486÷1.065≈2334。\n增长量＝现期−基期＝2486−2334≈152。\n（或直接 2486×13/213≈152。）", "explain": "基期＝2486÷1.065≈2334，增长量≈152，选 B。", "tip": "带小数的百分数先化分数：6.5%＝13/200，增长量＝现期×13/(200+13)。", "hard": "误用 2486×6.5%＝161.6 会滑向 152 与 186 之间，务必先化分数再乘。"}, {"type": "pure", "level": "进阶", "topic": "增长量·修正法", "stem": "某指标现期值为 6,450，同比增长 29%，则增长量约为（　）", "options": ["1,120", "1,450", "1,860", "2,150"], "answer": ["B"], "method": "用邻近整齐分数先估：29%≈30%，30%＝3/13，6450÷13×3≈1488。\n29% 比 30% 略小，按偏差往回收约 38，得≈1450。\n（也可用假设基期法：设基期 5000，5000×1.29＝6450，增长量＝1450。）", "explain": "6450÷1.29＝5000，增长量＝6450−5000＝1450，选 B。", "tip": "修正法：先用邻近的 1/n 估，再按 r 的偏差回收；29% 与 30% 仅差 1%，回收量很小。", "hard": "用 30% 不回收获 1488，与正确值 1450 相差 38，接近干扰项边界，必须回收。"}, {"type": "pure", "level": "基础", "topic": "反向题·求增长率", "stem": "某指标基期值为 1,248，现期值为 1,560，则增长率为（　）", "options": ["20%", "25%", "28%", "32%"], "answer": ["B"], "method": "增长率＝现期÷基期−1。\n1560÷1248＝1.25，故增长率＝25%。", "explain": "1560÷1248＝1.25，增长率＝1.25−1＝25%，选 B。", "tip": "求增长率用“现期÷基期−1”，别用（现期−基期）÷现期（那是比重口径）。", "hard": "1560−1248＝312，若拿 312÷1560≈20%，会误选 A。"}, {"type": "applied", "level": "仿真", "topic": "基期量·化除为乘（估算）", "stem": "2024 年该市地区生产总值约为（　）", "data": "【材料】2025 年某市地区生产总值 12,845.6 亿元，比上年增长 5.3%。", "options": ["11,600 亿元", "12,200 亿元", "12,800 亿元", "13,500 亿元"], "answer": ["B"], "method": "求基期用“现期÷(1+r)”：12845.6÷1.053。\n估算：12845.6÷1.05≈12234，r 略大故商略小，取 12,200。", "explain": "基期＝12845.6÷1.053≈12,200（亿元），选 B。", "tip": "求基期一律用除法；除数带小数时先按 1.05 估，再按 r 偏差微调。", "hard": "误用 12845.6×(1−5.3%)＝12,165，会误选 A，方向对但方法错。"}, {"type": "applied", "level": "进阶", "topic": "比重·直除估算", "stem": "2025 年该省出口额占进出口总额的比重约为（　）", "data": "【材料】2025 年某省进出口总额 4,236.8 亿美元，其中出口 2,715.3 亿美元。", "options": ["58%", "61%", "64%", "67%"], "answer": ["C"], "method": "比重＝部分÷整体＝2715.3÷4236.8。\n估量级：2715÷4237，先算 4237×0.64≈2712，略小于 2715，故约 64.1%。", "explain": "2715.3÷4236.8≈0.641，即约 64%，选 C。", "tip": "比重题先估量级再用整百分数试乘，比硬除快。", "hard": "2715.3 与 4236.8 相差近 1500，若用“出口减进口”之类口径会偏离 64%。"}, {"type": "applied", "level": "仿真", "topic": "求整体·部分÷比重（估算）", "stem": "2025 年该市地区生产总值约为（　）", "data": "【材料】2025 年某市第三产业增加值 8,913.7 亿元，占全市地区生产总值的 61.2%。", "options": ["13,900 亿元", "14,600 亿元", "15,300 亿元", "16,100 亿元"], "answer": ["B"], "method": "整体＝部分÷比重＝8913.7÷0.612。\n0.612≈0.6，8913.7÷0.6≈14856；实际除数大一些，商小一些，取 14,600。", "explain": "整体＝8913.7÷61.2%≈14,565，约 14,600 亿元，选 B。", "tip": "已知“部分”和“占比”求整体用除法；把比重凑成 0.6 先估量级。", "hard": "误用 8913.7×(1−0.612)＝3458 或 8913.7×0.612＝5455，都属口径用错。"}, {"type": "applied", "level": "仿真", "topic": "间隔增长率（估算）", "stem": "2025 年该指标比 2023 年增长约（　）", "data": "【材料】某指标 2024 年同比增长 7.2%，2025 年同比增长 8.1%。", "options": ["13.5%", "14.7%", "15.9%", "17.2%"], "answer": ["C"], "method": "间隔增长率＝r₁＋r₂＋r₁×r₂。\n7.2%＋8.1%＝15.3%，r₁×r₂≈0.6%。\n合计≈15.9%。", "explain": "间隔增长率＝7.2%＋8.1%＋7.2%×8.1%≈15.3%＋0.58%≈15.9%，选 C。", "tip": "间隔增长率公式：r₁＋r₂＋r₁r₂，第三项是乘积项，小但别丢。", "hard": "只加两项得 15.3%，会误选 B（14.7%）附近——乘积项虽小，却是本题的得分点。"}, {"type": "applied", "level": "仿真", "topic": "两期比重差（估算）", "stem": "2025 年该市高新技术产业产值占工业总产值的比重与上年相比约（　）", "data": "【材料】2025 年某市高新技术产业产值 2,164.5 亿元，比上年增长 12.3%；全市工业总产值 8,650.2 亿元，比上年增长 6.8%。", "options": ["上升 0.6 个百分点", "上升 1.2 个百分点", "上升 2.0 个百分点", "下降 0.5 个百分点"], "answer": ["B"], "method": "现期比重＝2164.5÷8650.2≈25.0%。\n基期比重＝(2164.5÷1.123)÷(8650.2÷1.068)≈1927.4÷8099.4≈23.8%。\n差值＝25.0%−23.8%＝1.2 个百分点，方向为上升。", "explain": "现期比重约 25.0%、基期比重约 23.8%，故比重比上年上升约 1.2 个百分点，选 B。", "tip": "部分增速（12.3%）＞整体增速（6.8%），比重必然上升；差值用“现期比重−基期比重”。", "hard": "只看“25.0%”不看增速关系，容易多算或少算一个百分点；先判方向再定量。"}, {"type": "applied", "level": "仿真", "topic": "年均增长率（开平方估算）", "stem": "2021—2025 年该市规模以上工业增加值的年均增长率约为（　）", "data": "【材料】2021 年某市规模以上工业增加值 3,245.6 亿元，2025 年增至 4,178.9 亿元。", "options": ["4.8%", "5.6%", "6.5%", "7.4%"], "answer": ["C"], "method": "总比值＝4178.9÷3245.6≈1.288，增长 4 次（2021→2025），故年均增速＝1.288 的 4 次方根−1。\n开两次平方：√1.288≈1.135，√1.135≈1.065。\n年均增长率≈6.5%。", "explain": "总比值≈1.288，4 次方根≈1.065，年均增长率≈6.5%，选 C。", "tip": "年均增长率＝(末值/初值)^(1/n)−1；4 年就开两次平方，先估后调。", "hard": "1.288 若直接用“总增长÷4＝7.2%”是错误口径（几何平均≠算术平均）。"}, {"type": "applied", "level": "进阶", "topic": "倍数比较·直除估算", "stem": "2025 年该市城镇居民人均可支配收入约是农村居民的多少倍（　）", "data": "【材料】2025 年某市城镇居民人均可支配收入 68,432 元，增长 5.6%；农村居民人均可支配收入 32,118 元，增长 7.1%。", "options": ["1.95", "2.13", "2.35", "2.60"], "answer": ["B"], "method": "倍数＝68432÷32118。\n估量级：32118×2＝64236，余 4196；4196÷32118≈0.13。\n故≈2.13。", "explain": "68432÷32118≈2.13，即约 2.13 倍，选 B。", "tip": "倍数题先看“几倍余多少”：2 倍余 4196，再除以 32118 得 0.13，合计 2.13。", "hard": "两个增速（5.6%、7.1%）是干扰信息，问题问的是“现期倍数”，不需要还原基期。"}, {"type": "applied", "level": "仿真", "topic": "下降型·求减少量（估算）", "stem": "2025 年该市钢材产量比上年约减少（　）", "data": "【材料】2025 年某市钢材产量 1,486.2 万吨，比上年下降 6.5%。", "options": ["82 万吨", "103 万吨", "125 万吨", "148 万吨"], "answer": ["B"], "method": "先求上年（基期）：1486.2÷(1−6.5%)＝1486.2÷0.935≈1589.5。\n减少量＝1589.5−1486.2≈103.3。", "explain": "基期＝1486.2÷0.935≈1589.5，减少量≈103 万吨，选 B。", "tip": "下降型求减少量：先“现期÷(1−降幅)”还原基期，再相减；除数小于 1，商比现期大。", "hard": "误用 1486.2×6.5%＝96.6 会滑向 A（82）附近，下降型的基数应是“上年”而非“当年”。"}]}];
